// ═══ UTILS ═══
// Nota: $() ya está definido al inicio del archivo con caché de DOM.
const fmt=n=>Number(n||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
// ═══ MEJORA 2: PARSEO SEGURO DE NÚMEROS ═══
// toNumero(valor, default) — convierte texto a número con validación.
// Si el valor no es un número válido, devuelve el default.
// Acepta strings con comas como separador de miles ("1,234.56" → 1234.56).
// Si esperas decimales (precios, totales) usa toNumero(v, 0).
// Si esperas entero (cantidades), usa toEntero(v, 1).
function toNumero(valor, defecto) {
  if (defecto === undefined) defecto = 0;
  if (valor === null || valor === undefined || valor === '') return defecto;
  if (typeof valor === 'number') return isFinite(valor) ? valor : defecto;
  // Limpiar string: quitar comas (separador de miles), espacios, signo $
  var limpio = String(valor).replace(/[\s,$]/g, '').trim();
  if (limpio === '') return defecto;
  var n = parseFloat(limpio);
  return (isNaN(n) || !isFinite(n)) ? defecto : n;
}
function toEntero(valor, defecto) {
  if (defecto === undefined) defecto = 0;
  var n = toNumero(valor, defecto);
  return Math.trunc(n);
}
const _hoyReal=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
const _horaReal=()=>{const d=new Date();return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');};
// ═══ CAPTURA RETROACTIVA — VIGENCIA ESTRICTA ══════════════════════════════
// BUG RAÍZ (caso real 08-ago-2026): window._capturaMesActivo es una bandera de
// sesión que reescribe hoy()/hora() para TODO lo que se registre después. Solo
// se limpiaba al pulsar "✕ Salir" del banner: si en vez de eso se cerraba el
// panel de admin (adminVolverPanel), se abría un modal encima del banner, o
// simplemente se seguía trabajando, el modo quedaba prendido en silencio y
// CADA movimiento posterior se guardaba con fecha pasada — y el Monitor lo
// marcaba (correctamente) como "SÍ retroactivo". El movimiento no estaba mal
// etiquetado: su fecha REALMENTE estaba mal. Huella inconfundible del bug:
// movimientos capturados el 08-ago que quedaron con fecha 2026-08-01, es decir
// exactamente el `anio-mes-01` que devolvía el fallback de abajo cuando el
// usuario nunca eligió fecha manual.
//
// Blindaje (3 candados independientes, cualquiera corta el modo):
//   1. El banner azul debe existir y estar VISIBLE. El modo ya no puede estar
//      activo sin su indicador en pantalla: si el banner se oculta o se quita,
//      el modo se apaga solo.
//   2. Vigencia máxima de 2 h desde la última acción retroactiva. Una sesión de
//      captura olvidada caduca sola en vez de contaminar el resto del día.
//   3. Requiere fecha elegida explícitamente. Ya NO existe el fallback mudo al
//      día 1 del mes: sin fecha manual, se usa la fecha real de hoy.
const CAPTURA_RETRO_VIGENCIA_MS = 2*60*60*1000;
function _capturaRetroApagar(motivo){
  if(!window._capturaMesActivo) return;
  window._capturaMesActivo   = null;
  window._capturaFechaManual = null;
  window._capturaHoraManual  = null;
  window._capturaMesActivadoTs = null;
  window._capturaRetroAvisado  = false;
  const _b = document.getElementById('captura-mes-banner');
  if(_b) _b.style.display = 'none';
  console.warn('[CapturaRetro] Modo retroactivo apagado automáticamente:', motivo);
  if(typeof toast==='function') toast('📅 Modo captura retroactiva desactivado — los registros vuelven a llevar la fecha de hoy','ok');
}
// Devuelve el modo retroactivo SOLO si sigue vigente; si no, lo apaga y devuelve null.
function _capturaRetroVigente(){
  const m = window._capturaMesActivo;
  if(!m) return null;
  const banner = document.getElementById('captura-mes-banner');
  if(!banner || banner.style.display === 'none' || !banner.isConnected){
    _capturaRetroApagar('el banner de captura ya no está visible');
    return null;
  }
  // Sin marca de tiempo se considera CADUCADO (nunca "vigente para siempre"):
  // toda activación legítima sella _capturaMesActivadoTs, así que un modo sin
  // sello es un residuo de sesión y debe apagarse, no heredarse.
  const ts = window._capturaMesActivadoTs || 0;
  if(!ts || (Date.now() - ts) > CAPTURA_RETRO_VIGENCIA_MS){
    _capturaRetroApagar(ts ? 'caducó por inactividad (más de 2 h)' : 'modo sin sello de activación (residuo de sesión)');
    return null;
  }
  return m;
}
window._capturaRetroVigente = _capturaRetroVigente;
window._capturaRetroApagar  = _capturaRetroApagar;
// hoy() y hora() respetan el modo captura retroactiva SOLO mientras esté vigente
const hoy=()=>{
  const m = _capturaRetroVigente();
  // Sin fecha elegida explícitamente NO se inventa una del pasado: se usa hoy.
  if(m && window._capturaFechaManual){
    window._capturaMesActivadoTs = Date.now(); // renovar vigencia por uso real
    return window._capturaFechaManual;
  }
  return _hoyReal();
};
const hora=()=>{
  const m = _capturaRetroVigente();
  if(m && window._capturaFechaManual && window._capturaHoraManual){
    return window._capturaHoraManual;
  }
  return _horaReal();
};
const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
// ═══ COLOR POR TIPO DE ARCHIVO ════════════════════════════════════════════
// A petición expresa: en las listas de documentos adjuntos (Placas, Expediente
// Digital, Escrituras) todas las etiquetas se veían iguales — con 8 o 10
// archivos por trámite era imposible distinguir de un vistazo cuál es una foto,
// cuál un PDF y cuál un Word. Ahora cada familia de archivo tiene su color e
// icono. Las imágenes (jpg, jpeg, png, webp…) comparten un mismo color, tal
// como se pidió, porque para el trámite son la misma cosa: una foto del documento.
// Paleta elegida por la usuaria (11-ago-2026):
//   imágenes → beige (el color que ya tenían todas las etiquetas)
//   PDF      → azul claro
//   ofimática (Word y Excel juntos) → verde suave
//   cualquier otro → morado pastel
const _DOC_ESTILOS = {
  imagen: { bg:'#f7f0dc', borde:'#d4b870', texto:'#633806', icono:'🖼️' },
  pdf:    { bg:'#e3f0fb', borde:'#7aa8d0', texto:'#123a5c', icono:'📕' },
  office: { bg:'#e6f4ea', borde:'#8dc4a0', texto:'#1a5233', icono:'📗' },
  otro:   { bg:'#f0eafa', borde:'#b9a5db', texto:'#493068', icono:'📄' }
};
function _docFamilia(nombre, tipo){
  const n = String(nombre||'').toLowerCase();
  const t = String(tipo||'').toLowerCase();
  const ext = n.includes('.') ? n.slice(n.lastIndexOf('.')+1) : '';
  if(t.startsWith('image/') || ['jpg','jpeg','png','webp','gif','bmp','heic','heif','tif','tiff','svg'].includes(ext)) return 'imagen';
  if(t === 'application/pdf' || ext === 'pdf') return 'pdf';
  // Word y Excel comparten color: ambos son documentos de ofimática.
  if(t.includes('word') || t.includes('sheet') || t.includes('excel') ||
     ['doc','docx','odt','rtf','xls','xlsx','csv','ods'].includes(ext)) return 'office';
  return 'otro';
}
function _docEstilo(nombre, tipo){ return _DOC_ESTILOS[_docFamilia(nombre, tipo)]; }
window._docFamilia = _docFamilia;
window._docEstilo  = _docEstilo;
const empNombre=()=>localStorage.getItem('empleado_nombre')||'Usuario';
const empEmail=()=>localStorage.getItem('empleado_email')||'';
// ═══ HORARIO DE CAPTURA — checador + avisos programados ═══════════════════
// HORARIO_CAPTURA_INICIO sigue siendo el horario OFICIAL (8:30) — es la
// referencia contra la que se mide puntualidad/tardanza en el Checador y no
// cambia. HORARIO_APERTURA_SISTEMA es aparte: la hora real desde la que el
// sistema deja entrar a los empleados (7:00, permanente, para todos) — a
// petición expresa: a veces llegan temprano y se les habilita el acceso,
// pero seguir contando "tarde" a partir de las 8:30 tal cual siempre.
const HORARIO_CAPTURA_INICIO  = '08:30';
const HORARIO_APERTURA_SISTEMA = '07:00';
const HORARIO_CAPTURA_FIN     = '17:30';
const TOLERANCIA_TARDANZA_MIN = 10;
function _minutosDeHHMM(hhmm){
  const p = String(hhmm||'0:0').split(':');
  return (parseInt(p[0],10)||0)*60 + (parseInt(p[1],10)||0);
}
// Hora "verificada": corrige el reloj de la PC con el desvío medido contra
// el servidor (horaDriveDesviacion, ver sincronizarHoraCDMX/verificarHoraConDrive
// más arriba) — así, si un empleado adelanta o atrasa el reloj de su equipo
// para intentar burlar el horario/checador/captura retroactiva, el sistema
// sigue usando la hora real. Si aún no hay verificación disponible (recién
// cargó la página, o sin conexión), se usa el reloj local tal cual — nunca
// bloquea por falta de red, solo dejamos de corregir mientras no haya dato.
function _ahoraVerificado(){
  const desvio = (typeof horaDriveDesviacion === 'number') ? horaDriveDesviacion : 0;
  return new Date(Date.now() + desvio);
}
function _minutosAhora(){
  const d = _ahoraVerificado();
  return d.getHours()*60 + d.getMinutes();
}
// ═══ TIEMPO EXTRA POR EMPLEADO (otorgado por el administrador) ═════════════
// D.tiempoExtra[email] = { tipo:'hora'|'indefinido_hoy'|'indefinido_permanente',
//   hasta:'HH:MM' (solo tipo 'hora'), fecha:'YYYY-MM-DD' (día en que se otorgó,
//   usado para que 'hora' e 'indefinido_hoy' expiren solos al día siguiente),
//   otorgadoPor, otorgadoTs }. 'indefinido_permanente' no expira solo — se
// queda activo hasta que el administrador lo apague a mano.
function _teClaveHoy(){
  return (typeof hoy === 'function') ? hoy() : new Date().toISOString().slice(0,10);
}
function _teObtener(email){
  if(!email || typeof D === 'undefined' || !D.tiempoExtra) return null;
  const t = D.tiempoExtra[String(email).toLowerCase()];
  if(!t) return null;
  // 'hora' e 'indefinido_hoy' son válidos solo el día en que se otorgaron —
  // si ya es otro día, se consideran vencidos (se limpian solos, sin que el
  // administrador tenga que hacer nada al día siguiente).
  if((t.tipo === 'hora' || t.tipo === 'indefinido_hoy') && t.fecha !== _teClaveHoy()) return null;
  return t;
}
// ¿el tiempo extra otorgado deja el sistema abierto en este momento exacto?
function _teEstaAbierto(email){
  const t = _teObtener(email);
  if(!t) return false;
  if(t.tipo === 'indefinido_permanente' || t.tipo === 'indefinido_hoy') return true;
  if(t.tipo === 'hora') return _minutosAhora() < _minutosDeHHMM(t.hasta);
  return false;
}
function _teDescribir(t){
  if(!t) return null;
  if(t.tipo === 'hora') return 'Abierto hoy hasta las '+t.hasta+' hrs'+(t.otorgadoPor?' (otorgado por '+t.otorgadoPor+')':'');
  if(t.tipo === 'indefinido_hoy') return 'Abierto hasta las 11:59 pm de hoy (mañana vuelve el horario normal)';
  if(t.tipo === 'indefinido_permanente') return 'Abierto permanente (hasta que lo apagues)';
  return null;
}
// domingo | antes | manana | tarde | cerrado
function _horarioEstado(){
  // Tiempo extra otorgado por el administrador: tiene prioridad sobre TODO,
  // incluido el bloqueo de domingo — si el admin autorizó, el sistema queda
  // abierto ('tarde') sin más preguntas.
  const _teEmail = (typeof empleadoActual !== 'undefined' && empleadoActual) ? empleadoActual.email : null;
  if(_teEmail && _teEstaAbierto(_teEmail)) return 'tarde';
  // Domingo: el despacho no labora — se aplica ANTES que cualquier otra
  // regla y cubre el día completo (no importa la hora). Solo bloquea a
  // empleados; horarioGateLogin() nunca llama esto para admin.
  if(_ahoraVerificado().getDay() === 0) return 'domingo';
  const mins   = _minutosAhora();
  const inicio = _minutosDeHHMM(HORARIO_APERTURA_SISTEMA);
  const fin    = _minutosDeHHMM(HORARIO_CAPTURA_FIN);
  if(mins < inicio) return 'antes';
  if(mins < 720)    return 'manana';
  if(mins < fin)    return 'tarde';
  return 'cerrado';
}
// "Buenos días" / "Buenas tardes" / "Buenas noches" según la hora real —
// usado en avisos que pueden aparecer a cualquier hora (ej. domingo).
function _saludoPorHora(){
  const h = _ahoraVerificado().getHours();
  if(h < 12) return 'Buenos días';
  if(h < 19) return 'Buenas tardes';
  return 'Buenas noches';
}
// Extrae el primer nombre de pila, saltando prefijos como LIC/ING/DR/MTRO
function _primerNombreEmpleado(nombreCompleto){
  const partes = String(nombreCompleto||'').trim().split(/\s+/).filter(Boolean);
  if(!partes.length) return 'Usuario';
  let idx = 0;
  if(/^(LIC|ING|DR|MTRO|C\.P|LICDA|ABOG)\.?$/i.test(partes[0])) idx = 1;
  return partes[idx] || partes[0];
}
// Quita cualquier "cortina" de carga que siga tapando el sistema (el splash
// negro texturizado de sesión restaurada, o el modal de login dejado puesto
// en el login manual). Se llama justo en el momento en que ya se sabe qué
// mostrar (aviso de horario, o nada si es admin) — nunca antes — para que el
// dashboard sin bloquear jamás quede expuesto ni un instante de por medio.
function _lexCortinaQuitar(){
  if(typeof _lexSplashOcultar === 'function') _lexSplashOcultar();
  if(window._lexLoginCortina && window._lexLoginCortina.parentNode){
    window._lexLoginCortina.parentNode.removeChild(window._lexLoginCortina);
  }
  window._lexLoginCortina = null;
}
// ── Modal de bienvenida por horario (antes/mañana/tarde/cerrado) ──────────
let _hgCountdownTimer = null;
function _horarioGateMostrar(estado, nombre){
  const ov = document.getElementById('modal-horario-gate');
  if(!ov) return;
  // FIX (candado real a media sesión): el fondo transparente/sin blur de
  // este overlay asume que ya está la cortina oscura del login detrás. Si
  // se dispara con el dashboard ya abierto (empleada que siguió trabajando
  // tras las 5:30 con la sesión ya iniciada), no hay cortina — se oscurece
  // el fondo aquí mismo para que el bloqueo también se vea, no solo funcione.
  if(!window._lexLoginCortina){
    ov.style.background = 'rgba(0,0,0,0.6)';
    ov.style.backdropFilter = 'blur(4px)';
    ov.style.webkitBackdropFilter = 'blur(4px)';
  }
  const elIcono     = document.getElementById('hg-icono');
  const elTitulo    = document.getElementById('hg-titulo');
  const elCuerpo    = document.getElementById('hg-cuerpo');
  const elCountdown = document.getElementById('hg-countdown');
  const elBtn       = document.getElementById('hg-btn');
  elCountdown.style.display = 'none';
  elBtn.style.display = 'block';
  if(estado === 'domingo'){
    elIcono.textContent  = '📅';
    elTitulo.textContent = 'Día no laborable';
    elCuerpo.innerHTML =
      '<div style="font-weight:700;margin-bottom:10px;">¡'+_saludoPorHora()+', '+escHTML(nombre)+'!</div>'+
      'Hoy domingo el despacho no labora.<br>'+
      'El sistema permanece cerrado y la captura de movimientos estará disponible nuevamente el siguiente día hábil.';
    elBtn.textContent = 'Cerrar sesión';
    elBtn.onclick = function(){
      // Mismo guardrail que "Horario concluido": se pregunta ANTES de tocar
      // el candado — si cancela, se queda bloqueado tal cual.
      if(typeof cerrarSesionUsuario==='function') cerrarSesionUsuario();
    };
  } else if(estado === 'antes'){
    elIcono.textContent  = '🌅';
    elTitulo.textContent = 'Bienvenida';
    elCuerpo.innerHTML =
      '<div style="font-weight:700;margin-bottom:10px;">¡Buenos días, '+escHTML(nombre)+'!</div>'+
      'Aún no inicia el horario de captura.<br>'+
      '🕣 El sistema se habilita a las 7:00 a. m.<br>'+
      'Puedes esperar aquí — se desbloqueará automáticamente en cuanto sea la hora.<br>'+
      '¡Que tengas un excelente día!';
    elBtn.style.display = 'none';
    elCountdown.style.display = 'block';
    _horarioGateCountdownIniciar();
  } else if(estado === 'manana'){
    elIcono.textContent  = '🌅';
    elTitulo.textContent = 'Bienvenida';
    elCuerpo.innerHTML =
      '<div style="font-weight:700;margin-bottom:10px;">¡Buenos días, '+escHTML(nombre)+'!</div>'+
      'Horario de captura vigente:<br>'+
      '🕣 8:30 a. m. - 5:30 p. m.<br>'+
      'Recuerde registrar oportunamente sus movimientos durante la jornada para mantener la información actualizada.<br>'+
      '¡Excelente jornada de trabajo!';
    elBtn.textContent = 'Entendido';
    elBtn.onclick = _horarioGateCerrar;
  } else if(estado === 'tarde'){
    elIcono.textContent  = '☀️';
    elTitulo.textContent = 'Bienvenida';
    elCuerpo.innerHTML =
      '<div style="font-weight:700;margin-bottom:10px;">¡Buenas tardes, '+escHTML(nombre)+'!</div>'+
      'Bienvenido(a) nuevamente al sistema.<br>'+
      'Verifique que los movimientos realizados durante el día se encuentren registrados correctamente antes del cierre de operaciones.';
    elBtn.textContent = 'Entendido';
    elBtn.onclick = _horarioGateCerrar;
  } else {
    elIcono.textContent  = '🌙';
    elTitulo.textContent = 'Horario concluido';
    // A partir de las 7:00 p. m. el saludo cambia a "Buenas noches" (antes de
    // eso, entre 5:30 y 7:00 p. m., se mantiene "Buenas tardes").
    const _saludoCierre = (new Date().getHours() >= 19) ? 'Buenas noches' : 'Buenas tardes';
    elCuerpo.innerHTML =
      '<div style="font-weight:700;margin-bottom:10px;">¡'+_saludoCierre+', '+escHTML(nombre)+'!</div>'+
      'El horario de captura ha concluido.<br>'+
      'El sistema permanece cerrado desde las 5:30 p. m. y la captura de movimientos estará disponible nuevamente en el siguiente horario de operación.';
    elBtn.textContent = 'Cerrar sesión';
    elBtn.onclick = function(){
      // GUARDRAIL: antes se ocultaba el candado (ov.classList.remove) ANTES
      // de preguntar la confirmación de cerrarSesionUsuario() — si el usuario
      // le daba "Cancelar", el candado ya se había quitado y el sistema
      // quedaba desbloqueado sin querer. Ahora se pregunta PRIMERO; si
      // cancela, no se toca el modal y el sistema sigue bloqueado. Si
      // confirma, cerrarSesionUsuario() recarga la página sola (no hace
      // falta ocultar nada aquí: la recarga limpia todo).
      if(typeof cerrarSesionUsuario==='function') cerrarSesionUsuario();
    };
  }
  ov.classList.add('show');
}
function _horarioGateCountdownIniciar(){
  if(_hgCountdownTimer){ clearInterval(_hgCountdownTimer); _hgCountdownTimer = null; }
  const elCountdown = document.getElementById('hg-countdown');
  function tick(){
    const faltan = _minutosDeHHMM(HORARIO_APERTURA_SISTEMA) - _minutosAhora();
    if(faltan <= 0){
      clearInterval(_hgCountdownTimer); _hgCountdownTimer = null;
      _horarioGateCerrar();
      if(typeof toast==='function') toast('🌅 El sistema ya está habilitado — ¡buen inicio de jornada!');
      try{ registrarConexionDiaria(); }catch(e){}
      return;
    }
    if(!elCountdown) return;
    const h = Math.floor(faltan/60), m = faltan % 60;
    elCountdown.textContent = '⏳ Faltan ' + (h>0?h+'h ':'') + m + ' min';
  }
  tick();
  _hgCountdownTimer = setInterval(tick, 15000);
}
function _horarioGateCerrar(){
  const ov = document.getElementById('modal-horario-gate');
  if(ov) ov.classList.remove('show');
  if(_hgCountdownTimer){ clearInterval(_hgCountdownTimer); _hgCountdownTimer = null; }
  // Recién AHORA el usuario queda autorizado a ver el sistema real — se
  // retira la cortina (que hasta este momento tapaba el fondo con la
  // textura oscura del login detrás del aviso).
  if(typeof _lexCortinaQuitar === 'function') _lexCortinaQuitar();
  if(window._avisoTardanzaPendiente != null){
    const mins = window._avisoTardanzaPendiente;
    window._avisoTardanzaPendiente = null;
    setTimeout(function(){ if(typeof toast==='function') toast('⏰ Registrado con '+mins+' min de retraso','err'); }, 300);
  }
}
// Punto de entrada: se llama tras cada login/restauración de sesión
async function horarioGateLogin(){
  try{
    if(!empleadoActual) { _lexCortinaQuitar(); return; }
    const esAdminUI = empleadoActual.email.toLowerCase() === (typeof ADMIN_EMAIL!=='undefined'?ADMIN_EMAIL.toLowerCase():'');
    if(!esAdminUI){
      const estado  = _horarioEstado();
      const nombre  = _primerNombreEmpleado(empleadoActual.nombre);
      // OJO: la cortina NO se quita aquí. Se deja puesta (el aviso de horario
      // tiene z-index más alto, así que se ve encima sin problema) para que
      // el fondo detrás del aviso sea SIEMPRE la textura oscura del login —
      // nunca el sistema real, ni borroso ni de fondo. Se retira hasta que el
      // usuario quede realmente autorizado a entrar: en _horarioGateCerrar()
      // (mañana/tarde, al cerrar el aviso, o al terminar la cuenta regresiva).
      // Para "cerrado" nunca se quita — la única salida es cerrar sesión.
      _horarioGateMostrar(estado, nombre);
      if(estado === 'manana' || estado === 'tarde'){
        try{
          const resultadoPunt = await registrarConexionDiaria();
          if(resultadoPunt && resultadoPunt.estado === 'tarde'){
            window._avisoTardanzaPendiente = resultadoPunt.minutosTarde;
          }
        }catch(e){ console.warn('[horarioGateLogin] puntualidad', e); }
      }
    } else {
      // Admin: no hay aviso de horario que mostrar, pero igual hay que
      // retirar la cortina de carga para que el panel se revele.
      _lexCortinaQuitar();
    }
    if(!window._avisoProgramadoInterval){
      window._avisoProgramadoInterval = setInterval(_avisoProgramadoChequear, 60000);
    }
    setTimeout(_avisoProgramadoChequear, esAdminUI ? 500 : 1800);
  } catch(e){
    console.warn('[horarioGateLogin]', e);
    _lexCortinaQuitar(); // red de seguridad: nunca dejar la cortina pegada si algo falla
  }
}
// ── Avisos programados durante la jornada (aplican a todos, incluido admin) ──
// _formatoFaltaTiempo: expresa en minutos/horas el tiempo REAL que falta para
// el cierre — usado por los avisos 16:30/17:15 para que, si el sistema se abre
// tarde (después de esa hora exacta), el mensaje diga cuánto falta DE VERDAD
// en vez de repetir el texto fijo pensado solo para quien lo ve justo a tiempo.
function _formatoFaltaTiempo(mins){
  if(mins <= 0) return 'unos momentos';
  if(mins < 60) return mins + ' minuto' + (mins===1?'':'s');
  const h = Math.floor(mins/60), m = mins % 60;
  let txt = h + ' hora' + (h===1?'':'s');
  if(m > 0) txt += ' ' + m + ' min';
  return txt;
}
const AVISOS_PROGRAMADOS = [
  { hhmm:'12:00', color:'#2dba58', titulo:'RECORDATORIO DE CONTABILIDAD',
    cuerpo:'Se recomienda registrar oportunamente los ingresos, egresos y demás movimientos realizados durante la jornada para mantener la información actualizada.' },
  { hhmm:'15:00', color:'#1a5fa0', titulo:'SEGUIMIENTO DE REGISTROS CONTABLES',
    cuerpo:'Verifique que todos los movimientos efectuados hasta este momento se encuentren debidamente registrados en el sistema.' },
  { hhmm:'16:30', color:'#c8952a', titulo:'AVISO DE CIERRE CONTABLE',
    cuerpo: function(){
      const falta = _minutosDeHHMM(HORARIO_CAPTURA_FIN) - _minutosAhora();
      return 'Falta ' + _formatoFaltaTiempo(falta) + ' para el cierre del sistema. Si existen movimientos pendientes, regístrelos ahora para evitar omisiones en la contabilidad del día.';
    } },
  { hhmm:'17:15', color:'#e0781a', titulo:'ÚLTIMO AVISO',
    cuerpo: function(){
      const falta = _minutosDeHHMM(HORARIO_CAPTURA_FIN) - _minutosAhora();
      return 'El sistema cerrará en ' + _formatoFaltaTiempo(falta) + '. Después de las 5:30 p. m. no será posible registrar ingresos, egresos ni movimientos correspondientes a la jornada de hoy.';
    } },
  { hhmm:'17:30', color:'#c0161a', titulo:'SISTEMA CERRADO',
    cuerpo:'El horario autorizado para el registro de movimientos ha concluido. La captura de información permanecerá deshabilitada hasta el siguiente día hábil. En caso de una incidencia justificada, comuníquese con el administrador del sistema.' }
];
function _avisoProgramadoVistoHoyKey(hhmm){
  const email  = (empleadoActual && empleadoActual.email || 'anon').toLowerCase();
  const diaKey = _hoyReal();
  return 'lex_aviso_'+email+'_'+diaKey+'_'+hhmm;
}
function _avisoProgramadoChequear(){
  try{
    if(!empleadoActual) return;
    // Si el candado de horario (aviso "Horario concluido"/cuenta regresiva)
    // sigue mostrado, no se compite con él ni se apila otro modal encima —
    // eso era justo lo que oscurecía el fondo (dos overlays translúcidos uno
    // sobre otro tapaban por completo la textura dorada de la cortina). El
    // aviso programado se reintenta solo (cada 60s) y se muestra normal en
    // cuanto el candado se cierre de verdad (mañana/tarde) o nunca si el
    // horario sigue "cerrado" — ese estado ya deja claro que el sistema está
    // cerrado, este aviso sería redundante.
    const _gateSC = document.getElementById('modal-horario-gate');
    if(_gateSC && _gateSC.classList.contains('show')) return;
    // Cierre automático de caja: revisa (sin bloquear este chequeo) si el
    // servidor ya marcó que pasaron las 5:30 p.m. y hoy no se ha cerrado.
    if(typeof _chequearCierreAutomaticoCaja === 'function') _chequearCierreAutomaticoCaja();
    // FIX (caso real: empleada siguió trabajando después de las 5:30 con la
    // sesión ya abierta desde antes): el candado real (_horarioGateMostrar)
    // antes solo se evaluaba UNA VEZ, al iniciar sesión (horarioGateLogin) —
    // una sesión abierta antes de las 5:30 nunca lo volvía a ver, y el aviso
    // de las 17:30 de AVISOS_PROGRAMADOS de aquí abajo es solo informativo,
    // no bloquea nada. Ahora, en cada revisión (cada 60s), si quien tiene la
    // sesión NO es admin y el horario ya está realmente cerrado (o es
    // domingo), se aplica el candado real — el mismo modal de "Horario
    // concluido"/"Día no laborable" que ya existe, con la única salida de
    // cerrar sesión. Se revisa en cada tick (no solo una vez al día) para
    // que no haya forma de seguir trabajando con la sesión abierta.
    const _esAdminChk = empleadoActual.email && typeof ADMIN_EMAIL !== 'undefined' &&
      empleadoActual.email.toLowerCase() === ADMIN_EMAIL.toLowerCase();
    if(!_esAdminChk){
      const _estadoChk = _horarioEstado();
      if(_estadoChk === 'cerrado' || _estadoChk === 'domingo'){
        _horarioGateMostrar(_estadoChk, _primerNombreEmpleado(empleadoActual.nombre));
        return; // el candado ya quedó puesto — no compite con el aviso de abajo
      }
      // ── Tiempo extra activo: los avisos normales (4:30/5:15/5:30, keyeados
      // al cierre de las 5:30) ya no aplican — en su lugar, un único aviso
      // 5 minutos antes de que concluya el tiempo extra otorgado (solo
      // aplica al tipo 'hora'; los indefinidos no tienen cierre que avisar).
      const _teAct = _teObtener(empleadoActual.email);
      if(_teAct){
        if(_teAct.tipo === 'hora'){
          const _faltanTE = _minutosDeHHMM(_teAct.hasta) - _minutosAhora();
          if(_faltanTE <= 5 && _faltanTE > 0){
            const _teKey = 'lex_aviso_te_'+empleadoActual.email.toLowerCase()+'_'+_teAct.fecha+'_'+_teAct.hasta;
            if(!localStorage.getItem(_teKey)){
              localStorage.setItem(_teKey, '1');
              _avisoProgramadoMostrar({ color:'#c0161a', titulo:'CIERRE EN 5 MINUTOS',
                cuerpo:'El tiempo extra autorizado está por concluir. El sistema cerrará a las '+_teAct.hasta+' hrs.' });
            }
          }
        }
        return;
      }
    }
    const mins = _minutosAhora();
    let masReciente = null;
    for(let i = 0; i < AVISOS_PROGRAMADOS.length; i++){
      if(mins >= _minutosDeHHMM(AVISOS_PROGRAMADOS[i].hhmm)) masReciente = AVISOS_PROGRAMADOS[i];
    }
    if(!masReciente) return;
    const key = _avisoProgramadoVistoHoyKey(masReciente.hhmm);
    if(localStorage.getItem(key)) return;
    localStorage.setItem(key, '1');
    _avisoProgramadoMostrar(masReciente);
  } catch(e){ console.warn('[avisoProgramado]', e); }
}
function _avisoProgramadoMostrar(av){
  const ov = document.getElementById('modal-aviso-programado');
  if(!ov) return;
  const elBorde  = document.getElementById('ap-borde');
  const elTitulo = document.getElementById('ap-titulo');
  const elCuerpo = document.getElementById('ap-cuerpo');
  if(elBorde)  elBorde.style.background = av.color;
  if(elTitulo) elTitulo.textContent = av.titulo;
  if(elCuerpo) elCuerpo.textContent = (typeof av.cuerpo === 'function') ? av.cuerpo() : av.cuerpo;
  ov.classList.add('show');
}
// ── CANDADO DE EDICIÓN POR FOLIO ──────────────────────────────────────
// A petición expresa: si dos personas editan el mismo folio al mismo
// tiempo, gana quien guarda al último y el otro cambio se pierde sin
// aviso. Este candado bloquea de forma ESTRICTA (no solo advierte):
// al abrir cualquier flujo de edición de un folio, primero se intenta
// tomar el candado en Supabase (tabla folio_locks, función RPC atómica
// intentar_candado_folio — evita condición de carrera entre 2 clientes
// que lo pidan en el mismo instante). Si otra persona ya lo tiene, se
// bloquea la edición y se avisa quién lo tiene. El candado expira solo
// a los 10 minutos por si alguien cierra el navegador sin guardar/cancelar.
function _lockSessionId(){
  var k = 'lex_session_id';
  var v = localStorage.getItem(k);
  if(!v){ v = 'sess-' + Date.now() + '-' + Math.random().toString(36).slice(2); localStorage.setItem(k, v); }
  return v;
}
// Intenta adquirir el candado del folio. Resuelve siempre (nunca rechaza):
// {ok:true} si se pudo (o ya era tuyo), {ok:false, locked_by_name, expires_at} si no.
// Si Supabase no responde, "falla abierto" (permite editar) para no dejar
// el sistema inutilizable por un problema de red — solo avisa por consola.
async function _lockIntentarAdquirir(folioN){
  try{
    if(!(window.SB && window.SB_DESPACHO_ID) || folioN == null) return {ok:true};
    var { data, error } = await _sbConTimeout(window.SB.rpc('intentar_candado_folio', {
      p_despacho_id: window.SB_DESPACHO_ID,
      p_folio: Number(folioN),
      p_nombre: empNombre(),
      p_email: empEmail(),
      p_session: _lockSessionId(),
      p_minutos: 10
    }), 8000, 'candado de folio');
    if(error) throw error;
    var fila = (data && data[0]) || {ok:true};
    return fila;
  }catch(e){
    console.warn('[candadoFolio] no se pudo verificar, se permite editar:', e);
    return {ok:true};
  }
}
function _lockLiberar(folioN){
  try{
    if(!(window.SB && window.SB_DESPACHO_ID) || folioN == null) return;
    window.SB.rpc('liberar_candado_folio', {
      p_despacho_id: window.SB_DESPACHO_ID,
      p_folio: Number(folioN),
      p_session: _lockSessionId()
    }).then(function(){}).catch(function(e){ console.warn('[candadoFolio] liberar:', e); });
  }catch(e){ console.warn('[candadoFolio] liberar:', e); }
}
function _lockAvisoBloqueo(res, folioN){
  var quien = (res && res.locked_by_name) ? res.locked_by_name : 'otra persona';
  alert('🔒 El folio ' + (folioN != null ? '#' + folioN + ' ' : '') + 'está siendo editado ahora mismo por ' + quien + '.\n\nEspera un momento e inténtalo de nuevo (el candado se libera solo, incluso si esa persona cierra el navegador sin guardar).');
  if(typeof toast === 'function') toast('🔒 Folio en edición por ' + quien, 'err');
}
window._lockLiberar = _lockLiberar;
// ═══ R2 CLOUDFLARE — configuración y helpers ═══
const R2_WORKER = 'https://lex-mexico-worker.fcolex0.workers.dev';
// Respaldo temporal: el Worker sigue aceptando este token fijo mientras se
// termina de confirmar que todo usa el token de sesión real (ver _r2AuthToken).
const R2_TOKEN  = 'LexMx2026-R2-7kP9nQvT';
// Token real de autenticación: el de sesión de Supabase del empleado actual
// (único por persona, expira solo, se puede revocar deshabilitando su cuenta).
// Si por algún motivo no hay sesión activa todavía, cae de regreso al token
// fijo de arriba, que el Worker sigue aceptando como respaldo temporal.
async function _r2AuthToken(){
  try{
    if(window.SB){
      const { data } = await window.SB.auth.getSession();
      const tok = data && data.session && data.session.access_token;
      if(tok) return tok;
    }
  } catch(e){ /* silencioso */ }
  return R2_TOKEN;
}
window.subirR2 = async function(file, path, bucket) {
  try {
    const fd = new FormData();
    fd.append('file', file);
    fd.append('path', path);
    fd.append('bucket', bucket || 'recibos');
    const res = await fetch(R2_WORKER + '/r2/upload?bucket=' + encodeURIComponent(bucket || 'recibos'), {
      method: 'POST',
      headers: { 'X-Auth-Token': await _r2AuthToken() },
      body: fd
    });
    if (!res.ok) { console.error('subirR2 error', res.status, await res.text()); return false; }
    return true;
  } catch(e) { console.error('subirR2 excepcion', e); return false; }
}
window.descargarR2 = async function(path, bucket, _silencioso) {
  try {
    // ⚠️ Cache-busting: sin esto, el navegador puede servir una copia vieja en
    // caché para la MISMA url (mismo path) aunque el archivo en R2 ya se haya
    // regenerado — causaba que un PDF recién corregido y resubido siguiera
    // mostrando el contenido anterior hasta cerrar/reabrir el navegador.
    const url = R2_WORKER + '/r2/file?path=' + encodeURIComponent(path)
              + '&bucket=' + (bucket || 'recibos')
              + '&token=' + await _r2AuthToken()
              + '&_cb=' + Date.now();
    const res = await fetch(url, { cache: 'no-store' });
    if (res.ok) return await res.blob();
    // 404 en archivos opcionales (meta.json) es normal — no llenar consola
    var esOpcional = path.endsWith('meta.json') || _silencioso;
    if (!esOpcional) console.error('descargarR2 error', res.status, path);
    return null;
  } catch(e) { console.error('descargarR2 excepcion', e); return null; }
}
window.listarR2 = async function(prefix, bucket) {
  try {
    const url = R2_WORKER + '/r2/list?prefix=' + encodeURIComponent(prefix || '')
              + '&bucket=' + (bucket || 'recibos')
              + '&token=' + await _r2AuthToken()
              + '&_cb=' + Date.now();
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) return [];
    const data = await res.json();
    return data.objects || [];
  } catch(e) { console.error('listarR2 excepcion', e); return []; }
}
window.borrarR2 = async function(path, bucket) {
  try {
    const url = R2_WORKER + '/r2/file?path=' + encodeURIComponent(path)
              + '&bucket=' + (bucket || 'recibos');
    const res = await fetch(url, {
      method: 'DELETE',
      headers: { 'X-Auth-Token': await _r2AuthToken() }
    });
    return res.ok;
  } catch(e) { console.error('borrarR2 excepcion', e); return false; }
}
// ── Recuperación robusta y validada del PDF de un recibo (compartida) ──
// Devuelve un Blob PDF VÁLIDO (cabecera %PDF) o null. Repara la ruta guardada
// en el recibo cuando lo encuentra por listado. No toca el DOM.
// `abortar` (opcional): callback que, si devuelve true, cancela la operación en vuelo.
window.obtenerBlobPdfReciboValidado = async function(recibo, abortar){
  if(!recibo || !window.SB_DESPACHO_ID) return null;
  const _ab = typeof abortar === 'function' ? abortar : function(){ return false; };
  const _letra    = (recibo.letra || (typeof letraVersion==='function'?letraVersion(recibo):'A') || 'A').toUpperCase();
  const _folioStr = typeof folioFormato==='function' ? folioFormato(recibo.folio, recibo.anio_folio) : String(recibo.folio);

  // Descarga + validación de que el blob sea un PDF real (empieza con %PDF)
  const _bajar = async function(path){
    if(!path || typeof window.descargarR2!=='function') return null;
    const b = await window.descargarR2(path, 'recibos', true);
    if(_ab()) return null;
    if(!b || b.size < 100) return null;
    if(!(b.type.includes('pdf') || b.type==='application/octet-stream' || b.type==='')) return null;
    const a = await b.slice(0,4).arrayBuffer();
    return String.fromCharCode.apply(null, new Uint8Array(a)) === '%PDF' ? b : null;
  };

  let _blob = null;

  // 1) Rutas directas guardadas en el recibo
  const _cands = [];
  if(recibo.archivoR2Raiz) _cands.push(recibo.archivoR2Raiz);
  if(recibo.archivoR2 || recibo.archivo) _cands.push(window.SB_DESPACHO_ID + '/recibos/' + (recibo.archivoR2 || recibo.archivo));
  if(recibo.archivo) _cands.push(window.SB_DESPACHO_ID + '/recibos/' + recibo.archivo);
  if(recibo.nombre && recibo.archivo && typeof _nombreArchivoR2Legacy==='function'){
    _cands.push(window.SB_DESPACHO_ID + '/recibos/' + _nombreArchivoR2Legacy(recibo.archivo.replace(/\.pdf$/i,''), recibo.nombre));
  }
  for(let i=0;i<_cands.length && !_blob;i++){
    if(_ab()) return null;
    _blob = await _bajar(_cands[i]);
  }

  // 2) Búsqueda por listado del bucket (prefijo del despacho → raíz). Repara la ruta.
  if(!_blob && typeof window.listarR2==='function'){
    if(_ab()) return null;
    const _folioEsc = _folioStr.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const _reNuevo  = new RegExp('(^|[^0-9])' + _folioEsc + (_letra==='A'?'a?':_letra) + '([^0-9]|_|\\.pdf)', 'i');
    const _reViejo  = _letra==='A' ? new RegExp('Recibo_0*' + (parseInt(recibo.folio)||0) + '_', 'i') : null;
    const _buscar = function(objs){
      if(!objs || !objs.length) return null;
      let m = objs.find(o => _reNuevo.test((o.key||o.name||'').split('/').pop()));
      if(!m && _reViejo) m = objs.find(o => _reViejo.test((o.key||o.name||'').split('/').pop()));
      return m ? (m.key||m.name||null) : null;
    };
    let _key = _buscar(await window.listarR2(window.SB_DESPACHO_ID + '/recibos/', 'recibos'));
    if(_ab()) return null;
    if(!_key) _key = _buscar(await window.listarR2('', 'recibos'));
    if(_ab()) return null;
    if(_key){
      _blob = await _bajar(_key);
      if(_blob){
        if(_key.startsWith(window.SB_DESPACHO_ID + '/recibos/')){
          recibo.archivoR2 = _key.split('/').pop();
          if(!recibo.archivo) recibo.archivo = recibo.archivoR2;
        } else {
          recibo.archivoR2Raiz = _key; // ruta completa en la raíz del bucket
        }
      }
    }
  }

  // 3) Supabase Storage (validado %PDF)
  if(!_blob && window.SB && recibo.archivo){
    try{
      const _sbPath = window.SB_DESPACHO_ID + '/recibos/' + recibo.archivo;
      const { data:_sd, error:_se } = await window.SB.storage.from(STORAGE_BUCKET).createSignedUrl(_sbPath, 120);
      if(_ab()) return null;
      if(!_se && _sd && _sd.signedUrl){
        const _res = await fetch(_sd.signedUrl);
        if(_ab()) return null;
        if(_res.ok){
          const _b = await _res.blob();
          if(_ab()) return null;
          const _arr = await _b.slice(0,4).arrayBuffer();
          if(String.fromCharCode.apply(null, new Uint8Array(_arr)) === '%PDF') _blob = _b;
        }
      }
    }catch(_eSB){ console.warn('[obtenerBlobPdfReciboValidado] Storage:', _eSB); }
  }

  // 4) Recuperar pdfBase64 desde versiones_recibo (y re-subir a R2 en 2º plano)
  if(!_blob && window.SB){
    try{
      const _anio = recibo.anio_folio || new Date().getFullYear();
      let _vr = null;
      const { data:_vd1 } = await window.SB.from('versiones_recibo')
        .select('datos_completos, pdf_storage_path, letra')
        .eq('despacho_id', window.SB_DESPACHO_ID).eq('folio_base', recibo.folio)
        .eq('anio_folio', _anio).eq('letra', _letra).limit(1);
      _vr = (_vd1 && _vd1.length) ? _vd1[0] : null;
      if(!_vr){
        const { data:_vd2 } = await window.SB.from('versiones_recibo')
          .select('datos_completos, pdf_storage_path, letra')
          .eq('despacho_id', window.SB_DESPACHO_ID).eq('folio_base', recibo.folio)
          .eq('anio_folio', _anio).order('letra',{ascending:false}).limit(1);
        _vr = (_vd2 && _vd2.length) ? _vd2[0] : null;
      }
      if(_ab()) return null;
      if(_vr && _vr.datos_completos && _vr.datos_completos.pdfBase64){
        const _b64  = _vr.datos_completos.pdfBase64;
        const _b64d = _b64.includes(',') ? _b64.split(',')[1] : _b64;
        const _bin  = atob(_b64d);
        const _buf  = new Uint8Array(_bin.length);
        for(let i=0;i<_bin.length;i++) _buf[i]=_bin.charCodeAt(i);
        _blob = new Blob([_buf],{type:'application/pdf'});
        recibo.pdfBase64 = _b64;
        try{
          const _r2path = _vr.pdf_storage_path
            || (window.SB_DESPACHO_ID + '/recibos/' + (recibo.archivoR2 || recibo.archivo || (String(recibo.folio).padStart(4,'0') + (_vr.letra||'A') + '.pdf')));
          const _f = new File([_blob], _r2path.split('/').pop(), {type:'application/pdf'});
          if(typeof window.subirR2==='function') window.subirR2(_f, _r2path, 'recibos').catch(function(){});
        }catch(_eUp){}
      }
    }catch(_eVR){ console.warn('[obtenerBlobPdfReciboValidado] versiones_recibo:', _eVR); }
  }

  return _blob;
};
// ═══ FIN R2 ═══

// ── Helpers R2 para resúmenes de acuerdos ──────────────────────
function _r2ResumenPath(driveFileId) {
  const dep = window.SB_DESPACHO_ID || 'despacho';
  return dep + '/acuerdos/' + driveFileId + '/resumen.json';
}
async function _r2GuardarResumen(driveFileId, resumen) {
  try {
    // Leer ocrTexto existente para no sobreescribirlo
    let ocrTexto = '';
    try {
      const prev = await _r2CargarResumen(driveFileId);
      if (prev && prev.ocrTexto) ocrTexto = prev.ocrTexto;
    } catch(e) {}
    const json = JSON.stringify({ resumen, ocrTexto, ts: Date.now() });
    const blob = new Blob([json], { type: 'application/json' });
    const file = new File([blob], 'resumen.json', { type: 'application/json' });
    await window.subirR2(file, _r2ResumenPath(driveFileId), 'expedientes');
  } catch(e) { console.warn('[R2Resumen] guardar:', e); }
}
async function _r2CargarResumen(driveFileId) {
  try {
    const blob = await window.descargarR2(_r2ResumenPath(driveFileId), 'expedientes', true);
    if (!blob) return null;
    const txt = await blob.text();
    const data = JSON.parse(txt);
    // Devuelve objeto completo: { resumen, ocrTexto }
    return { resumen: data.resumen || null, ocrTexto: data.ocrTexto || null };
  } catch(e) { return null; }
}
