// ═══ MONITOR DE CONTABILIDAD ══════════════════════════════════════════════
// Botón "🛡️ Monitor" — oculto para empleados, igual que Scanner. Bitácora
// real de auditoría (quién y cuándo REAL causó cada alta/baja, aunque el
// movimiento en sí quede fechado de forma retroactiva — created_at de
// sesiones_log lo pone el propio servidor, nadie lo puede alterar desde el
// navegador), errores/alteraciones del sistema relacionados a Contabilidad,
// y una reconciliación mensual (sumas reales, cortes de caja, generado o
// perdido por mes) para tener certeza de que nada se infla ni se elimina
// sin dejar rastro.
let _monTabActual = 'bitacora';
function abrirContabMonitor(){
  let ov = document.getElementById('overlay-contab-monitor');
  if(!ov){
    ov = document.createElement('div');
    ov.id = 'overlay-contab-monitor';
    ov.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,0.82);z-index:9600;'
      + 'align-items:center;justify-content:center;font-family:inherit;';
    ov.innerHTML =
      '<div style="background:#fdfaf4;border:2px solid #8c3a3a;border-radius:12px;width:97%;max-width:1180px;'
      + 'max-height:92vh;box-shadow:0 24px 60px rgba(0,0,0,0.6);overflow:hidden;display:flex;flex-direction:column;">'
      + '<div style="background:linear-gradient(135deg,#2a0808,#1a0808);padding:16px 20px;display:flex;align-items:center;gap:10px;flex-shrink:0;">'
      +   '<span style="font-size:1.4rem;">🛡️</span>'
      +   '<div style="flex:1;">'
      +     '<div style="font-family:serif;font-size:1.05rem;color:#e8a8a8;">Monitor de Contabilidad</div>'
      +     '<div style="font-size:0.62rem;color:rgba(232,168,168,0.65);font-family:monospace;letter-spacing:0.08em;">CERTEZA DE QUE NADA SE INFLA NI SE ELIMINA SIN RASTRO</div>'
      +   '</div>'
      +   '<button onclick="cerrarContabMonitor()" style="background:none;border:none;color:rgba(232,168,168,0.65);font-size:1.4rem;cursor:pointer;line-height:1;">✕</button>'
      + '</div>'
      + '<div style="display:flex;background:#f5e8e8;border-bottom:1px solid #e0c0c0;flex-shrink:0;">'
      +   '<div class="mon-tab" data-t="bitacora" style="padding:11px 20px;cursor:pointer;font-size:12.5px;font-weight:600;color:#7a4040;border-bottom:2.5px solid transparent;">📜 Bitácora Real</div>'
      +   '<div class="mon-tab" data-t="errores" style="padding:11px 20px;cursor:pointer;font-size:12.5px;font-weight:600;color:#7a4040;border-bottom:2.5px solid transparent;">⚠️ Errores del Sistema</div>'
      +   '<div class="mon-tab" data-t="reconciliacion" style="padding:11px 20px;cursor:pointer;font-size:12.5px;font-weight:600;color:#7a4040;border-bottom:2.5px solid transparent;">🔄 Reconciliación Mensual</div>'
      + '</div>'
      + '<div id="mon-body" style="padding:20px;overflow-y:auto;flex:1;"></div>'
      + '</div>';
    document.body.appendChild(ov);
    ov.querySelectorAll('.mon-tab').forEach(function(t){
      t.onclick = function(){
        _monTabActual = t.getAttribute('data-t');
        _monPintarTabs();
        _monRender();
      };
    });
  }
  ov.style.display = 'flex';
  _monPintarTabs();
  _monRender();
}
function _monPintarTabs(){
  const ov = document.getElementById('overlay-contab-monitor');
  if(!ov) return;
  ov.querySelectorAll('.mon-tab').forEach(function(x){
    const on = x.getAttribute('data-t') === _monTabActual;
    x.style.borderBottomColor = on ? '#c04040' : 'transparent';
    x.style.background = on ? '#fdfaf4' : '';
    x.style.color = on ? '#3a1010' : '#7a4040';
  });
}
function cerrarContabMonitor(){
  const ov = document.getElementById('overlay-contab-monitor');
  if(ov) ov.style.display = 'none';
}
function _monRender(){
  if(_monTabActual === 'bitacora') _monRenderBitacora();
  else if(_monTabActual === 'errores') _monRenderErrores();
  else _monRenderReconciliacion();
}
async function _monRenderBitacora(){
  const body = document.getElementById('mon-body');
  if(!body) return;
  body.innerHTML = '<div style="text-align:center;padding:40px;color:#7a6840;">Cargando bitácora…</div>';
  try{
    if(!(window.SB && window.SB_DESPACHO_ID)){
      body.innerHTML = '<div style="text-align:center;padding:40px;color:#7a6840;">Sin conexión a Supabase.</div>';
      return;
    }
    const { data, error } = await window.SB.from('sesiones_log')
      .select('*')
      .eq('despacho_id', window.SB_DESPACHO_ID)
      .eq('modulo', 'contabilidad')
      .order('created_at', { ascending:false })
      .limit(50);
    if(error) throw error;
    const filas = data || [];
    if(!filas.length){
      body.innerHTML = '<div style="text-align:center;padding:40px;color:#7a6840;">Aún no hay movimientos registrados en la bitácora — esta función empezó a registrar a partir de hoy. Los movimientos de antes no tienen este dato.</div>';
      return;
    }
    let html = '<div style="font-size:0.68rem;color:#7a4040;margin-bottom:12px;">Últimos '+filas.length+' movimientos de Contabilidad — hora REAL del servidor, no la fecha que aparezca en el recibo si fue retroactivo.</div>';
    html += '<table style="width:100%;border-collapse:collapse;font-size:0.72rem;">';
    html += '<thead><tr style="text-align:left;border-bottom:2px solid #e0c0c0;color:#7a4040;">'
      + '<th style="padding:6px 8px;">Hora Real</th><th style="padding:6px 8px;">Quién</th><th style="padding:6px 8px;">Acción</th>'
      + '<th style="padding:6px 8px;">Folio</th><th style="padding:6px 8px;">Monto</th><th style="padding:6px 8px;">Tipo</th>'
      + '<th style="padding:6px 8px;">¿Retroactivo?</th><th style="padding:6px 8px;">Descripción</th></tr></thead><tbody>';
    filas.forEach(function(f){
      const d = f.detalle || {};
      const horaReal = f.created_at ? new Date(f.created_at).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}) : '—';
      const accionColor = f.accion === 'eliminado' ? '#c0161a' : (f.accion === 'creado' ? '#1a7a3a' : (f.accion === 'restaurado' ? '#1a5a8c' : '#a0560a'));
      html += '<tr style="border-bottom:1px solid #f0e8e0;">'
        + '<td style="padding:6px 8px;white-space:nowrap;">'+esc(horaReal)+'</td>'
        + '<td style="padding:6px 8px;">'+esc(f.usuario||f.email||'—')+'</td>'
        + '<td style="padding:6px 8px;font-weight:700;color:'+accionColor+';">'+esc(f.accion||'—')+'</td>'
        + '<td style="padding:6px 8px;">'+(d.folio!=null ? esc(String(d.folio)+(d.letra||'')) : '—')+'</td>'
        + '<td style="padding:6px 8px;">$'+fmt(d.monto||0)+'</td>'
        + '<td style="padding:6px 8px;">'+esc(d.tipo||'—')+'</td>'
        + '<td style="padding:6px 8px;">'+(d.retroactivo ? '<span style="color:#c0161a;font-weight:700;">SÍ ('+esc(d.fecha_mov||'')+')</span>' : 'No')+'</td>'
        + '<td style="padding:6px 8px;color:#7a6840;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+esc(d.descripcion||'')+'">'+esc((d.descripcion||'').slice(0,60))+'</td>'
        + '</tr>';
    });
    html += '</tbody></table>';
    body.innerHTML = html;
  }catch(e){
    body.innerHTML = '<div style="text-align:center;padding:40px;color:#c0161a;">Error al cargar la bitácora: '+esc(e.message||String(e))+'</div>';
  }
}
function _monRenderErrores(){
  const body = document.getElementById('mon-body');
  if(!body) return;
  const keywords = ['recibo','contab','mov','sync','placas','caja','folio'];
  const errs = (window.LEX_ERRORS||[]).filter(function(e){
    const m = (e.modulo||'').toLowerCase();
    return keywords.some(function(k){ return m.indexOf(k) >= 0; });
  }).slice().reverse().slice(0,80);
  if(!errs.length){
    body.innerHTML = '<div style="text-align:center;padding:40px;color:#1a7a3a;">✓ Sin errores o alteraciones registradas relacionadas a Contabilidad en esta sesión.</div>';
    return;
  }
  let html = '<div style="font-size:0.68rem;color:#7a4040;margin-bottom:12px;">Errores y alteraciones del sistema relacionados a Contabilidad — solo de esta sesión del navegador.</div>';
  errs.forEach(function(e){
    const color = e.nivel === 'error' ? '#c0161a' : (e.nivel === 'warn' ? '#a8730c' : '#7a6840');
    html += '<div style="border-bottom:1px solid #f0e8e0;padding:8px 4px;font-size:0.72rem;">'
      + '<span style="color:'+color+';font-weight:700;">['+esc(e.nivel||'')+']</span> '
      + '<span style="color:#7a6840;">'+esc(e.modulo||'')+'</span> — '
      + esc(e.mensaje||'') + ' <span style="color:#999;font-size:0.62rem;">('+new Date(e.fecha).toLocaleString('es-MX')+')</span>'
      + '</div>';
  });
  body.innerHTML = html;
}
function _monRenderReconciliacion(){
  const body = document.getElementById('mon-body');
  if(!body) return;
  // Solo lo que de verdad pidió el usuario: un botón que suma y resta todo y
  // dice si cuadra (✓) o alerta la discrepancia. Se quitó la tabla mensual de
  // apoyo porque no mostraba datos reales/confiables.
  let html = '<button onclick="_monRecalcularTodo()" style="padding:10px 20px;border-radius:8px;border:none;background:#8c3a3a;color:#fff;font-weight:700;cursor:pointer;font-size:0.82rem;margin-bottom:14px;">🔄 Recalcular Todo</button>';
  html += '<div id="mon-recon-resultado" style="margin-bottom:20px;"></div>';
  body.innerHTML = html;
  _monRecalcularTodo();
}
// ── El botón que de verdad pidió el usuario: recalcula todos los ingresos y
// egresos y los compara contra lo que cada corte de caja formal (esCorte)
// declaró haber entregado. Si coincide (con $1 de tolerancia por redondeo),
// palomita verde. Si no, alerta en rojo con el corte y la diferencia exacta
// — así se detecta si algo se infló o se borró después de un corte.
function _monRecalcularTodo(){
  const resultado = document.getElementById('mon-recon-resultado');
  if(!resultado) return;
  resultado.innerHTML = '<div style="text-align:center;padding:16px;color:#7a6840;">⏳ Recalculando…</div>';
  // FIX: todo el cálculo era síncrono y corría en el mismo instante que se
  // pintaba "Recalculando…", así que el navegador nunca llegaba a mostrar ese
  // mensaje y el resultado (si no cambiaba) parecía que el botón no había
  // hecho nada. Se fuerza una pequeña pausa real y se agrega la hora exacta
  // de la verificación para que cada clic muestre evidencia visible de que sí
  // se ejecutó.
  setTimeout(function(){
  try{
    const cortes = (D.cierres||[])
      .filter(function(c){ return c && c.esCorte === true && c.fecha; })
      .sort(function(a,b){ return (a.fecha+'T'+(a.hora||'00:00')).localeCompare(b.fecha+'T'+(b.hora||'00:00')); });
    const horaChk = new Date().toLocaleTimeString('es-MX');
    if(!cortes.length){
      resultado.innerHTML = '<div style="text-align:center;padding:16px;color:#7a6840;">No hay cortes de caja formales (esCorte) todavía para verificar.</div>';
      return;
    }
    if(typeof getSaldoHasta !== 'function'){
      resultado.innerHTML = '<div style="text-align:center;padding:16px;color:#c0161a;">No se encontró la función getSaldoHasta — no se puede recalcular.</div>';
      return;
    }
    const TOL = 1; // tolerancia de $1 por redondeo
    const problemas = [];
    cortes.forEach(function(c){
      const esperado = getSaldoHasta(c.fecha, c.hora);
      const registrado = parseFloat(c.saldoEntregado != null ? c.saldoEntregado : c.saldo) || 0;
      const dif = registrado - esperado;
      if(Math.abs(dif) > TOL){
        problemas.push({fecha:c.fecha, hora:c.hora, esperado:esperado, registrado:registrado, dif:dif});
      }
    });
    if(!problemas.length){
      resultado.innerHTML = '<div style="text-align:center;padding:22px;background:#eef8f0;border:2px solid #4dca6a;border-radius:10px;">'
        + '<div style="font-size:2rem;">✅</div>'
        + '<div style="font-weight:700;color:#1a7a3a;font-size:1rem;margin-top:6px;">Todo cuadra</div>'
        + '<div style="font-size:0.75rem;color:#3a7a4a;margin-top:4px;">Los '+cortes.length+' corte(s) de caja registrados coinciden con la suma real de los movimientos — nada se infló ni se eliminó sin dejar rastro.</div>'
        + '<div style="font-size:0.62rem;color:#5a8a6a;margin-top:8px;">Verificado a las '+esc(horaChk)+'</div>'
        + '</div>';
    } else {
      let html = '<div style="padding:16px;background:#fff0f0;border:2px solid #c0161a;border-radius:10px;">'
        + '<div style="font-weight:700;color:#c0161a;font-size:0.95rem;margin-bottom:8px;">⚠️ '+problemas.length+' discrepancia(s) encontrada(s)</div>';
      problemas.forEach(function(p){
        html += '<div style="font-size:0.76rem;color:#7a2020;padding:6px 0;border-top:1px solid rgba(192,22,26,0.15);">'
          + 'Corte del '+esc(p.fecha)+' '+esc(p.hora)+': se entregó $'+fmt(p.registrado)+', pero los movimientos de ese periodo suman $'+fmt(p.esperado)+' '
          + '— diferencia de <b>$'+fmt(Math.abs(p.dif))+'</b> ('+(p.dif>0?'de más':'de menos')+').'
          + '</div>';
      });
      html += '<div style="font-size:0.62rem;color:#a04040;margin-top:8px;">Verificado a las '+esc(horaChk)+'</div>';
      html += '</div>';
      resultado.innerHTML = html;
    }
  }catch(e){
    resultado.innerHTML = '<div style="text-align:center;padding:16px;color:#c0161a;">Error al recalcular: '+esc(e.message||String(e))+'</div>';
  }
  }, 250);
}
function _csTarjeta(icono, titulo, desc, onclickFn){
  return '<div onclick="'+onclickFn+'" style="cursor:pointer;border:1.5px solid rgba(200,149,42,0.35);'
    + 'border-radius:10px;padding:16px;background:#fff;transition:all 0.15s;" '
    + 'onmouseover="this.style.borderColor=\'#c8952a\';this.style.background=\'#fffaf0\';" '
    + 'onmouseout="this.style.borderColor=\'rgba(200,149,42,0.35)\';this.style.background=\'#fff\';">'
    + '<div style="font-size:1.6rem;margin-bottom:6px;">'+icono+'</div>'
    + '<div style="font-weight:700;color:#3a2a10;margin-bottom:4px;">'+titulo+'</div>'
    + '<div style="font-size:0.72rem;color:#7a6840;line-height:1.4;">'+desc+'</div>'
    + '</div>';
}
function _csHome(){
  const sub = document.getElementById('cs-subtitulo');
  if(sub) sub.textContent = 'HERRAMIENTAS RÁPIDAS';
  const body = document.getElementById('cs-body');
  if(!body) return;
  body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">'
    + _csTarjeta('💰','Préstamos','Ver préstamos y pagos registrados en Caja Rápida, con total prestado/pagado/pendiente.','_csAbrirPrestamos()')
    + _csTarjeta('📋','Folios sin Liquidar','Lista completa de folios con saldo pendiente &gt; $0, ordenados de mayor a menor.','_csAbrirSinLiquidar()')
    + _csTarjeta('🚗','Folios Vehiculares','Folios de trámite vehicular: en proceso, liquidados y cancelados.',"_csAbrirFolios('vehicular')")
    + _csTarjeta('📁','Folios Normales','Folios de trámite normal: en proceso, liquidados y cancelados.',"_csAbrirFolios('normal')")
    + _csTarjeta('📜','Folios de Escrituras','Folios de trámite de escrituras: en proceso, liquidados y cancelados.',"_csAbrirFolios('escritura')")
    + _csTarjeta('⚖️','Folios de Juicios','Folios de trámite de juicio: en proceso, liquidados y cancelados.',"_csAbrirFolios('juicio')")
    + '</div>';
}
// ── Herramienta 4: Folios sin Liquidar (saldoPendiente > 0) ───────────────
function _csAbrirSinLiquidar(){
  const sub = document.getElementById('cs-subtitulo');
  if(sub) sub.textContent = 'FOLIOS SIN LIQUIDAR';
  const body = document.getElementById('cs-body');
  if(!body) return;
  const recs = (typeof appData!=='undefined' && Array.isArray(appData.recibos) ? appData.recibos : [])
    .filter(function(r){ return r && !r.cancelado && (parseFloat(r.saldoPendiente)||0) > 0; })
    .sort(function(a,b){ return (parseFloat(b.saldoPendiente)||0) - (parseFloat(a.saldoPendiente)||0); });
  const totalPend = recs.reduce(function(s,r){ return s + (parseFloat(r.saldoPendiente)||0); }, 0);
  let html = '<button onclick="_csHome()" style="background:none;border:1.5px solid rgba(200,149,42,0.4);border-radius:20px;padding:6px 14px;font-size:0.74rem;color:#8c6518;cursor:pointer;margin-bottom:14px;">← Volver</button>';
  html += '<div style="display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap;">'
    + '<div style="flex:1;min-width:140px;background:#fff8e8;border:1.5px solid #e0c060;border-radius:8px;padding:10px 14px;">'
    +   '<div style="font-size:0.6rem;color:#8c6518;letter-spacing:0.05em;">FOLIOS SIN LIQUIDAR</div>'
    +   '<div style="font-size:1.1rem;font-weight:700;color:#8c6518;">'+recs.length+'</div>'
    + '</div>'
    + '<div style="flex:1;min-width:140px;background:#fff0f0;border:1.5px solid #e0a0a0;border-radius:8px;padding:10px 14px;">'
    +   '<div style="font-size:0.6rem;color:#a03030;letter-spacing:0.05em;">SALDO PENDIENTE TOTAL</div>'
    +   '<div style="font-size:1.1rem;font-weight:700;color:#c0161a;">$'+fmt(totalPend)+'</div>'
    + '</div>'
    + '</div>';
  if(!recs.length){
    html += '<div style="padding:24px;text-align:center;color:#9a8050;">No hay folios con saldo pendiente — todo liquidado ✓</div>';
  } else {
    html += '<div style="border:1px solid rgba(200,149,42,0.25);border-radius:8px;overflow:hidden;max-height:50vh;overflow-y:auto;">'
      + recs.map(function(r){
        const letra = r.letra || 'A';
        const str = (typeof folioConLetra==='function') ? folioConLetra(r.folio, r.anio_folio, letra) : (r.folio+letra);
        return '<div style="display:flex;gap:10px;padding:9px 12px;border-bottom:1px solid rgba(200,149,42,0.15);font-size:0.76rem;align-items:center;">'
          + '<div style="width:70px;flex-shrink:0;"><span onclick="cerrarContabScanner();abrirFichaDesdeContab('+r.folio+')" style="cursor:pointer;text-decoration:underline;text-underline-offset:2px;color:#1a4a8a;font-weight:700;">#'+esc(str)+'</span></div>'
          + '<div style="flex:1;font-weight:600;color:#3a2a10;">'+esc(r.nombre||(r.clientes&&r.clientes[0]&&r.clientes[0].nombre)||'—')+'</div>'
          + '<div style="width:110px;flex-shrink:0;text-align:right;font-weight:700;color:#c0161a;">$'+fmt(parseFloat(r.saldoPendiente)||0)+'</div>'
          + '</div>';
      }).join('')
      + '</div>';
  }
  body.innerHTML = html;
}
// ── Herramienta 1: Préstamos ──────────────────────────────────────────────
// Heurística simple: busca la palabra PRESTAMO/PRÉSTAMO en la descripción de
// los movimientos de Caja Rápida (no hay un módulo dedicado de préstamos —
// hoy se registran como movimientos manuales normales). No distingue
// automáticamente de quién es cada préstamo; el usuario revisa la descripción.
// Palabras sin valor para identificar a la "persona" del préstamo — se
// descartan y lo que sobra de la descripción se usa como su nombre.
const _CS_STOP_PRESTAMO = new Set(['SE','SELE','LE','LA','LO','LOS','LAS','UN','UNA','UNOS','UNAS','A','AL','DEL','DE',
  'EL','ELLA','ELLOS','QUE','PARA','POR','CON','EN','Y','O','U','SU','SUS','MI','MIS','TU','TUS',
  'ESTE','ESTA','ESTOS','ESTAS','ESE','ESA','ESOS','ESAS','SIN',
  'HIZO','HACE','DEVUELVE','DEVUELVEN','DEVOLVIO','DEVOLVIERON','PAGO','PAGARON','PAGA',
  'PRESTAMO','PRESTAMOS','PRESTA','PRESTO','PRESTADO','PRESTARON','PRESTAR',
  'CAJA','DESPACHO','LIC','DINERO','RECIBOS','RECIBO','MULTAS','MULTA','CATASTRO','OAXACA',
  'COMPLETAR','COMPRA','BOLETOS','OTRO','OTROS','DIA','DIAS',
  'ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE']);
function _csNormPrestamo(s){
  return String(s||'').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
}
function _csPersonaPrestamo(desc){
  const norm = _csNormPrestamo(desc);
  const palabras = norm.replace(/[^A-Z\s]/g,' ').split(/\s+/).filter(Boolean);
  const candidatos = palabras.filter(function(w){ return w.length>=3 && !_CS_STOP_PRESTAMO.has(w) && isNaN(w); });
  return candidatos.length ? candidatos.join(' ') : 'SIN IDENTIFICAR';
}
// Herramienta 1: Préstamos — simple, una tarjeta por persona.
// Lógica contable:
//   · Un movimiento de préstamo puede ser el PRÉSTAMO EN SÍ o el PAGO/DEVOLUCIÓN
//     de uno anterior — hay que distinguirlos, si no, cada pago se cuenta
//     también como si fuera un préstamo nuevo (doble conteo).
//   · Se detecta que es un PAGO cuando el texto dice "SE LE PAGÓ" o
//     "SE LE DEVUELVE/DEVOLVIÓ" (con o sin espacio: "SELE") — esa frase
//     concreta solo se usa para saldar un préstamo, nunca para darlo.
//   · Cada préstamo (no-pago) se compara contra los pagos de esa misma
//     persona para ver si ya se saldó (mismo monto, fecha igual o posterior).
//   · Ingreso = la persona prestó AL despacho. Egreso = el despacho le
//     prestó A la persona. El saldo por persona es una sola resta simple:
//     lo que le debe el despacho a ella, menos lo que ella le debe al despacho.
// Ícono moneda-con-$ + flecha (verde/abajo = ingreso, rojo/arriba = egreso),
// tamaño regular y bien visible — reemplaza los emojis 📥/📤 que se veían
// casi idénticos entre sí.
function _csIconoFlujo(tipo){
  const color = tipo==='ingreso' ? '#1a7a3a' : '#c0161a';
  const flecha = tipo==='ingreso' ? 'M12 19V26M7 21L12 26L17 21' : 'M12 26V19M7 24L12 19L17 24';
  return '<svg width="22" height="28" viewBox="0 0 24 30" style="vertical-align:middle;margin-right:5px;flex-shrink:0;">'
    + '<circle cx="12" cy="10" r="9" fill="none" stroke="'+color+'" stroke-width="2"/>'
    + '<text x="12" y="14" text-anchor="middle" font-size="11" font-weight="800" fill="'+color+'" font-family="monospace,sans-serif">$</text>'
    + '<path d="'+flecha+'" fill="none" stroke="'+color+'" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>'
    + '</svg>';
}
function _csAbrirPrestamos(){
  const sub = document.getElementById('cs-subtitulo');
  if(sub) sub.textContent = 'PRÉSTAMOS — QUIÉN DEBE A QUIÉN';
  const body = document.getElementById('cs-body');
  if(!body) return;
  const _RE_PRESTAMO = /PREST(?!ACION|IGIO)/;
  const _RE_ES_PAGO  = /SE\s?LE\s+(PAGO|DEVOLV|DEVUELV)/;
  const todos = (typeof getAllMovs==='function' ? getAllMovs() : []).filter(function(m){
    return _RE_PRESTAMO.test(_csNormPrestamo((m.descripcion||'')+' '+(m.cat||'')));
  }).map(function(m){
    const norm = _csNormPrestamo(m.descripcion||'');
    return {
      fecha: m.fecha||'', hora: m.hora||'', monto: parseFloat(m.monto)||0,
      tipo: m.tipo, desc: m.descripcion||'', persona: _csPersonaPrestamo(m.descripcion),
      esPago: _RE_ES_PAGO.test(norm)
    };
  }).sort(function(a,b){ return (a.fecha+'T'+a.hora).localeCompare(b.fecha+'T'+b.hora); });
  const prestamosReales = todos.filter(function(m){ return !m.esPago; });
  const pagos           = todos.filter(function(m){ return m.esPago; });
  // Emparejar cada préstamo con un pago de la MISMA persona, tipo OPUESTO
  // (si prestaron ingreso, el pago sale como egreso, y viceversa), mismo
  // monto, fecha igual o posterior — sin repetir el mismo pago dos veces.
  const pagoUsado = new Array(pagos.length).fill(false);
  prestamosReales.forEach(function(p){
    p.liquidado = false; p.fechaPago = null;
    for(let i=0;i<pagos.length;i++){
      if(pagoUsado[i]) continue;
      const g = pagos[i];
      if(g.persona===p.persona && g.tipo!==p.tipo && Math.abs(g.monto-p.monto)<0.01 && (g.fecha+'T'+g.hora) >= (p.fecha+'T'+p.hora)){
        pagoUsado[i] = true; p.liquidado = true; p.fechaPago = g.fecha; break;
      }
    }
  });
  const pagosSinPrestamo = pagos.filter(function(g,i){ return !pagoUsado[i]; });
  // Agrupar por persona
  const grupos = {};
  prestamosReales.forEach(function(p){
    if(!grupos[p.persona]) grupos[p.persona] = [];
    grupos[p.persona].push(p);
  });
  let html = '<button onclick="_csHome()" style="background:none;border:1.5px solid rgba(200,149,42,0.4);border-radius:20px;padding:6px 14px;font-size:0.74rem;color:#8c6518;cursor:pointer;margin-bottom:14px;">← Volver</button>';
  html += '<div style="font-size:0.72rem;color:#7a6840;margin-bottom:16px;line-height:1.5;display:flex;align-items:center;flex-wrap:wrap;gap:14px;">'
    + '<span style="display:flex;align-items:center;">'+_csIconoFlujo('ingreso')+'<b>&nbsp;Entró dinero</b>&nbsp;= la persona le prestó AL despacho.</span>'
    + '<span style="display:flex;align-items:center;">'+_csIconoFlujo('egreso')+'<b>&nbsp;Salió dinero</b>&nbsp;= el despacho le prestó A la persona.</span>'
    + '</div>';
  if(!Object.keys(grupos).length){
    html += '<div style="padding:24px;text-align:center;color:#9a8050;">No se encontró ningún préstamo en la descripción de los movimientos.</div>';
  } else {
    Object.keys(grupos).sort().forEach(function(persona){
      const items = grupos[persona];
      // Saldo simple: lo que el despacho le debe a la persona (préstamos que
      // ELLA hizo y siguen sin pagarse) menos lo que ella le debe al despacho
      // (préstamos que EL DESPACHO le dio y ella no ha regresado).
      const leDebeDespacho = items.filter(function(p){ return p.tipo==='ingreso' && !p.liquidado; }).reduce(function(s,p){ return s+p.monto; },0);
      const ellaDebe       = items.filter(function(p){ return p.tipo==='egreso'  && !p.liquidado; }).reduce(function(s,p){ return s+p.monto; },0);
      let fraseSaldo, colorSaldo;
      if(Math.abs(leDebeDespacho-ellaDebe) < 0.01){
        fraseSaldo = '✅ A mano — no se deben nada'; colorSaldo = '#1a7a3a';
      } else if(leDebeDespacho > ellaDebe){
        fraseSaldo = '🔴 El despacho le debe $'+fmt(leDebeDespacho-ellaDebe); colorSaldo = '#c0161a';
      } else {
        fraseSaldo = '🟡 '+esc(persona)+' le debe $'+fmt(ellaDebe-leDebeDespacho)+' al despacho'; colorSaldo = '#8c6518';
      }
      html += '<div style="border:1.5px solid rgba(200,149,42,0.4);border-radius:10px;margin-bottom:14px;overflow:hidden;">'
        + '<div style="background:rgba(200,149,42,0.12);padding:10px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">'
        +   '<span style="font-weight:700;color:#3a2a10;font-size:0.88rem;">'+(persona==='SIN IDENTIFICAR' ? '❓ Sin identificar' : esc(persona))+'</span>'
        +   '<span style="font-weight:700;font-size:0.8rem;color:'+colorSaldo+';">'+fraseSaldo+'</span>'
        + '</div>';
      items.forEach(function(p){
        const badge = _csIconoFlujo(p.tipo);
        const direccion = p.tipo==='ingreso'
          ? '<span style="display:inline-flex;align-items:center;">'+badge+esc(persona)+' le prestó al despacho</span>'
          : '<span style="display:inline-flex;align-items:center;">'+badge+'El despacho le prestó a '+esc(persona)+'</span>';
        const estado = p.liquidado
          ? '<span style="color:#1a7a3a;font-weight:700;">✅ Ya se pagó'+(p.fechaPago?' ('+esc(p.fechaPago)+')':'')+'</span>'
          : '<span style="color:#c0161a;font-weight:700;">⏳ Todavía se debe</span>';
        const descCorta = p.desc.length>70 ? p.desc.slice(0,70)+'…' : p.desc;
        html += '<div style="padding:10px 14px;border-top:1px solid rgba(200,149,42,0.15);font-size:0.78rem;">'
          + '<div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
          +   '<span>'+direccion+' — <b>$'+fmt(p.monto)+'</b></span>'
          +   '<span>'+estado+'</span>'
          + '</div>'
          + '<div style="color:#9a8050;font-size:0.68rem;margin-top:2px;" title="'+esc(p.desc)+'">'+esc(p.fecha)+' · '+esc(descCorta)+'</div>'
          + '</div>';
      });
      html += '</div>';
    });
  }
  if(pagosSinPrestamo.length){
    html += '<div style="margin-top:6px;padding:10px 14px;background:#fff8e8;border:1px dashed #e0c060;border-radius:8px;font-size:0.72rem;color:#8c6518;">'
      + '⚠ Hay '+pagosSinPrestamo.length+' pago(s) de préstamo cuyo préstamo original no encontré (monto o persona no coinciden) — revísalos aparte: '
      + pagosSinPrestamo.map(function(g){ return esc(g.fecha)+' "'+esc(g.desc.slice(0,50))+'" $'+fmt(g.monto); }).join('; ')
      + '</div>';
  }
  body.innerHTML = html;
}
// ── Herramienta: Folios por Tipo de Trámite ───────────────────────────────
// Agrupa los folios "puros" (número+letra) por r.tipoTramite (normal,
// vehicular, escritura, juicio) y dentro de cada uno separa 3 estados:
//   🟡 En proceso   = !cancelado && saldoPendiente > 0
//   ✅ Liquidados   = !cancelado && saldoPendiente <= 0
//   🔴 Cancelados   = r.cancelado === true
const _CS_TIPO_LABEL = {
  vehicular: '🚗 FOLIOS VEHICULARES',
  normal:    '📁 FOLIOS NORMALES',
  escritura: '📜 FOLIOS DE ESCRITURAS',
  juicio:    '⚖️ FOLIOS DE JUICIOS'
};
function _csAbrirFolios(tipo){
  const sub = document.getElementById('cs-subtitulo');
  if(sub) sub.textContent = _CS_TIPO_LABEL[tipo] || ('FOLIOS — '+tipo.toUpperCase());
  const body = document.getElementById('cs-body');
  if(!body) return;
  // Agrupar TODAS las versiones (A, B, C...) de un mismo folio en un solo
  // "paquete" — el estatus del paquete lo decide la ÚLTIMA versión (la más
  // reciente cronológicamente), no cada letra por separado.
  const todosDelTipo = (typeof appData!=='undefined' && Array.isArray(appData.recibos) ? appData.recibos : [])
    .filter(function(r){ return r && (r.tipoTramite||'normal') === tipo; });
  const paquetes = {};
  todosDelTipo.forEach(function(r){
    const key = String(r.folio);
    if(!paquetes[key]) paquetes[key] = [];
    paquetes[key].push(r);
  });
  const recs = Object.keys(paquetes).map(function(key){
    const versiones = paquetes[key].slice().sort(function(a,b){
      const la = (a.letra||'A'), lb = (b.letra||'A');
      if(la !== lb) return la.localeCompare(lb);
      return String(a.fecha||'').localeCompare(String(b.fecha||''));
    });
    const primera = versiones[0];
    const ultima  = versiones[versiones.length-1];
    // La etiqueta del paquete siempre usa la letra de la PRIMERA versión
    // (normalmente "A") — nunca se muestran las letras secundarias B/C/D.
    const letra = primera.letra || 'A';
    const str = (typeof folioConLetra==='function') ? folioConLetra(primera.folio, primera.anio_folio, letra) : (primera.folio+letra);
    return { r: ultima, str: str, folioNum: parseFloat(primera.folio)||0 };
  }).sort(function(a,b){ return a.folioNum - b.folioNum; });
  const cancelados = recs.filter(function(x){ return !!x.r.cancelado; });
  const enProceso  = recs.filter(function(x){ return !x.r.cancelado && (parseFloat(x.r.saldoPendiente)||0) > 0.009; });
  const liquidados = recs.filter(function(x){ return !x.r.cancelado && (parseFloat(x.r.saldoPendiente)||0) <= 0.009; });
  let html = '<button onclick="_csHome()" style="background:none;border:1.5px solid rgba(200,149,42,0.4);border-radius:20px;padding:6px 14px;font-size:0.74rem;color:#8c6518;cursor:pointer;margin-bottom:14px;">← Volver</button>';
  html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
    + '<div style="flex:1;min-width:120px;background:#fff8e8;border:1.5px solid #e0c060;border-radius:8px;padding:10px 14px;">'
    +   '<div style="font-size:0.6rem;color:#8c6518;letter-spacing:0.05em;">EN PROCESO</div>'
    +   '<div style="font-size:1.1rem;font-weight:700;color:#8c6518;">'+enProceso.length+'</div>'
    + '</div>'
    + '<div style="flex:1;min-width:120px;background:#f0fff4;border:1.5px solid #a0d0b0;border-radius:8px;padding:10px 14px;">'
    +   '<div style="font-size:0.6rem;color:#1a7a3a;letter-spacing:0.05em;">LIQUIDADOS</div>'
    +   '<div style="font-size:1.1rem;font-weight:700;color:#1a7a3a;">'+liquidados.length+'</div>'
    + '</div>'
    + '<div style="flex:1;min-width:120px;background:#fff0f0;border:1.5px solid #e0a0a0;border-radius:8px;padding:10px 14px;">'
    +   '<div style="font-size:0.6rem;color:#a03030;letter-spacing:0.05em;">CANCELADOS</div>'
    +   '<div style="font-size:1.1rem;font-weight:700;color:#c0161a;">'+cancelados.length+'</div>'
    + '</div>'
    + '</div>';
  function _chips(lista, colorBorde, colorTxt){
    if(!lista.length) return '<div style="font-size:0.72rem;color:#9a8050;padding:6px 0;">— ninguno —</div>';
    return '<div style="display:flex;flex-wrap:wrap;gap:6px;">'
      + lista.map(function(x){
        return '<span onclick="cerrarContabScanner();abrirFichaDesdeContab('+x.r.folio+')" '
          + 'title="'+esc(x.r.nombre||(x.r.clientes&&x.r.clientes[0]&&x.r.clientes[0].nombre)||'')+'" '
          + 'style="cursor:pointer;font-family:monospace;font-weight:700;font-size:0.76rem;padding:4px 10px;border-radius:14px;border:1.5px solid '+colorBorde+';color:'+colorTxt+';background:'+colorBorde+'18;">#'+esc(x.str)+'</span>';
      }).join('')
      + '</div>';
  }
  html += '<div style="margin-bottom:16px;">'
    + '<div style="font-weight:700;color:#8c6518;font-size:0.8rem;margin-bottom:8px;">🟡 En Proceso ('+enProceso.length+')</div>'
    + _chips(enProceso, '#e0c060', '#8c6518')
    + '</div>';
  html += '<div style="margin-bottom:16px;">'
    + '<div style="font-weight:700;color:#1a7a3a;font-size:0.8rem;margin-bottom:8px;">✅ Liquidados ('+liquidados.length+')</div>'
    + _chips(liquidados, '#a0d0b0', '#1a7a3a')
    + '</div>';
  html += '<div style="margin-bottom:16px;">'
    + '<div style="font-weight:700;color:#c0161a;font-size:0.8rem;margin-bottom:8px;">🔴 Cancelados ('+cancelados.length+')</div>'
    + _chips(cancelados, '#e0a0a0', '#c0161a')
    + '</div>';
  if(!recs.length){
    html += '<div style="padding:24px;text-align:center;color:#9a8050;">No hay folios de este tipo registrados.</div>';
  }
  body.innerHTML = html;
}
// Estado de sesión para acordeones (en memoria, se resetea al recargar)
// true = abierto manualmente, false = cerrado manualmente, undefined = sin tocar (usa default)
window._contabMesesAbiertos = window._contabMesesAbiertos || {};
window._contabAniosAbiertos = window._contabAniosAbiertos || {};

// Toggle acordeón de mes
function contabToggleMes(id) {
  const el    = document.getElementById(id);
  const arrow = document.getElementById(id + '-arrow');
  if (!el) return;
  const open = el.style.display !== 'none';
  el.style.display = open ? 'none' : 'block';
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
  // Guardar estado manual en sesión
  window._contabMesesAbiertos[id] = !open;
}
// Toggle acordeón de año
function contabToggleAnio(id) {
  const el    = document.getElementById(id);
  const arrow = document.getElementById(id + '-arrow');
  if (!el) return;
  const open = el.style.display !== 'none';
  el.style.display = open ? 'none' : 'block';
  if (arrow) arrow.style.transform = open ? '' : 'rotate(90deg)';
  // Guardar estado manual en sesión
  window._contabAniosAbiertos[id] = !open;
}
// ── Export CSV — respeta TODOS los filtros activos ──────────────
function exportCSV() {
  const q       = (document.getElementById('cBuscar')?.value || '').toLowerCase().trim();
  const filtroA = (document.getElementById('cFiltroAnio')?.value || '');
  const filtroM = (document.getElementById('cFiltroMes')?.value  || '');
  let movs = getAllMovs();
  if (filtroC === 'ing') movs = movs.filter(m => m.tipo === 'ingreso');
  else if (filtroC === 'egr') movs = movs.filter(m => m.tipo === 'egreso');
  if (filtroA) movs = movs.filter(m => m.fecha && m.fecha.startsWith(filtroA));
  if (filtroM) movs = movs.filter(m => m.fecha && m.fecha.substring(5,7) === filtroM);
  if (q) movs = movs.filter(m =>
    (m.descripcion||'').toLowerCase().includes(q) ||
    (m.nombre||'').toLowerCase().includes(q) ||
    (m.cat||'').toLowerCase().includes(q) ||
    (m.folioCaja||'').toLowerCase().includes(q) ||
    (m.folio!=null && folioConLetra(m.folio, m.anio_folio, letraDeRecibo(m.folio)).includes(q)) ||
    (m.responsable||'').toLowerCase().includes(q)
  );
  const DIAS_S  = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  const MESES_S = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  function _fb(f){
    try{ const [y,m,d]=f.split('-').map(Number); return DIAS_S[new Date(y,m-1,d).getDay()].toUpperCase()+' '+d+' DE '+MESES_S[m-1].toUpperCase()+' '+y; }
    catch(e){return f;}
  }
  // Incluir cierres sin movimientos en el rango
  const cierresSM = (D.cierres||[]).filter(c => {
    if(!c||!c.sinMovimientos||!c.fecha) return false;
    if(filtroA && !c.fecha.startsWith(filtroA)) return false;
    if(filtroM && c.fecha.substring(5,7)!==filtroM) return false;
    return true;
  });
  const grupos = {};
  movs.forEach(m => { const f=m.fecha||'—'; if(!grupos[f]) grupos[f]=[]; grupos[f].push(m); });
  cierresSM.forEach(c => { if(!grupos[c.fecha]) grupos[c.fecha]=[]; });
  const fechasAsc = Object.keys(grupos).filter(f=>f!=='—').sort();
  let acum = 0;
  const dataFecha = {};
  fechasAsc.forEach(f => {
    const ms  = grupos[f];
    const ing = ms.filter(m=>m.tipo==='ingreso').reduce((s,m)=>s+(parseFloat(m.monto)||0),0);
    const egr = ms.filter(m=>m.tipo==='egreso').reduce((s,m)=>s+(parseFloat(m.monto)||0),0);
    acum += ing - egr;
    const cierre = (D.cierres||[]).find(c=>c.fecha===f);
    dataFecha[f] = { ing, egr, saldo:ing-egr, acum, cierre };
    if(cierre && cierre.esCorte) acum = 0;
  });
  const lineas = ['\uFEFF' + 'HORA,FOLIO,NOMBRE,DESCRIPCIÓN,CATEGORÍA,FUENTE,RESPONSABLE,MONTO'];
  const periodo = (filtroA||'todos') + (filtroM?'-'+filtroM:'');
  lineas.push(`"=== LEX-MEXICO · Contabilidad · Periodo: ${periodo} ==="`);
  [...fechasAsc].reverse().forEach(f => {
    const { ing, egr, saldo, acum:acumDia, cierre } = dataFecha[f];
    const esSM = cierre && cierre.sinMovimientos;
    lineas.push('');
    lineas.push(`"📅 ${_fb(f)}${cierre&&!esSM?' 🔒':esSM?' 🔒 sin movimientos':''}"`);
    if (esSM) {
      const etiq = cierre.auto?' (auto)':'';
      lineas.push([cierre.hora||'23:59','—','""',`"${(cierre.leyenda||'Sin movimientos').replace(/"/g,"'")}${etiq}"`,'—','Cierre','—','$0.00'].join(','));
      lineas.push(['"EFECTIVO EN CAJA"','','','','','','',`"$${fmt(acumDia)}"`].join(','));
      return;
    }
    grupos[f].forEach(m => {
      const folio   = m.fuente==='recibo' ? folioFormato(m.folio||0) : (m.folioCaja||'—');
      const nombre  = m.fuente==='recibo' ? (m.nombre||'') : '';
      const desc    = m.fuente==='recibo' ? (m.descripcion||m.nombre||'') : (m.descripcion||'');
      const monto   = (m.tipo==='egreso'?'-':'+')+' $'+fmt(m.monto);
      lineas.push([
        m.hora||'—', folio,
        `"${nombre.replace(/"/g,"'")}"`,
        `"${desc.replace(/"/g,"'")}"`,
        m.cat||'—',
        m.fuente==='recibo'?'Recibo':'Caja',
        m.responsable||'—',
        monto
      ].join(','));
    });
    lineas.push(['"RESUMEN DEL DÍA"','','','','',`"▲ $${fmt(ing)}${egr>0?' | ▼ $'+fmt(egr):''}"`,'',`"${saldo>=0?'+':''} $${fmt(saldo)}"`].join(','));
    lineas.push(['"EN CAJA"','','','','','','',`"$${fmt(acumDia)}"`].join(','));
    if(cierre && cierre.esCorte) {
      lineas.push([`"🔒 CORTE ${cierre.hora||''}"`, '','','','','','',`"-$${fmt(acumDia)} → $0.00"`].join(','));
    }
  });
  // Totales finales
  const tIng = movs.filter(m=>m.tipo==='ingreso').reduce((s,m)=>s+(parseFloat(m.monto)||0),0);
  const tEgr = movs.filter(m=>m.tipo==='egreso').reduce((s,m)=>s+(parseFloat(m.monto)||0),0);
  lineas.push('');
  lineas.push(['"TOTAL DEL PERIODO"','','','','',`"▲ $${fmt(tIng)} | ▼ $${fmt(tEgr)}"`, '',`"${tIng-tEgr>=0?'+':''} $${fmt(tIng-tEgr)}"`].join(','));
  const suffix = (filtroA?'_'+filtroA:'') + (filtroM?'_'+filtroM:'');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([lineas.join('\n')],{type:'text/csv;charset=utf-8;'}));
  a.download = 'LEX_Contabilidad' + suffix + '_' + hoy() + '.csv';
  a.click();
  toast('CSV descargado ✓','ok');
}
// ═══ RECIBOS ═══
function renderRec(){
  // Fusionar REC.recibos y appData.recibos sin duplicados (por folio)
  // appData.recibos es la fuente principal (cargada desde Drive vía sincronizarFolio)
  // REC.recibos puede contener datos del archivo FOLIO_ID — unir ambas
  const recArr1=(typeof REC!=='undefined'?REC.recibos:[])||[];
  const recArr2=(typeof appData!=='undefined'?appData.recibos:[])||[];
  const foliosVistos=new Set();
  const rTodos=[...recArr2,...recArr1].filter(x=>{
    if(foliosVistos.has(x.folio))return false;
    foliosVistos.add(x.folio);return true;
  }).sort((function(a,b){ var fa=(a.fecha||a.fecha_recibo||'')+'T'+(a.hora||'00:00'); var fb=(b.fecha||b.fecha_recibo||'')+'T'+(b.hora||'00:00'); if(fb!==fa) return fb.localeCompare(fa); if(a.folio!==b.folio) return (b.folio||0)-(a.folio||0); var la=(a.letra||'A'),lb=(b.letra||'A'); return la<lb?-1:la>lb?1:0; }));
  // Mejora 4: aplicar filtros
  const r = aplicarFiltrosRecibos(rTodos);
  $('rTot').textContent=rTodos.length;
  const pend=rTodos.filter(x=>!x.cancelado&&x.saldoPendiente>0);
  const liq=rTodos.filter(x=>!x.cancelado&&!(x.saldoPendiente>0));
  $('rPend').textContent=pend.length;$('rLiq').textContent=liq.length;
  const _rSaldo=$('rSaldo'); if(_rSaldo) _rSaldo.textContent='$'+fmt(pend.reduce((s,x)=>s+(x.saldoPendiente||0),0));
  // Mejora 4: mostrar info del filtro
  const info = document.getElementById('recFiltroInfo');
  if (info) {
    if (r.length === rTodos.length) {
      info.textContent = '';
    } else {
      info.textContent = 'Mostrando ' + r.length + ' de ' + rTodos.length;
    }
  }
  const tb=$('tbRecibos'),v=$('recVacio');
  if(!r.length){
    tb.innerHTML='';
    v.style.display='block';
    if (rTodos.length > 0) {
      v.textContent='Ningún recibo coincide con los filtros aplicados.';
    } else {
      v.textContent=tokenOk()?'No hay recibos registrados aún.':'Inicia sesión para ver los recibos generados.';
    }
    return;
  }
  v.style.display='none';
  tb.innerHTML=r.map(x=>{
    const total=toNumero(x.total,0),ant=toNumero(x.anticipo,0);
    const saldo=x.saldoPendiente??Math.max(0,total-ant);
    const tag=x.cancelado?'<span class="tag tag-r">Cancelado</span>':saldo>0?'<span class="tag tag-a">Pendiente</span>':'<span class="tag tag-v">Liquidado</span>';
    return `<tr>
      <td class="mono" style="font-weight:700;color:var(--gold-d)">#${folioConLetra(x.folio, x.anio_folio, x.letra||letraVersion(x)||'A')}</td>
      <td>${esc(x.nombre)}</td><td style="font-size:0.7rem">${x.fecha||'—'}</td>
      <td class="monto">$${fmt(total)}</td>
      <td class="monto ing">$${fmt(ant)}</td>
      <td class="monto ${saldo>0?'egr':''}">${saldo>0?'$'+fmt(saldo):'—'}</td>
      <td>${tag}</td>
    </tr>`;
  }).join('');
}
// ═══ MEJORA 4: FILTROS Y EXPORTACIÓN DE RECIBOS ═══
function aplicarFiltrosRecibos(lista) {
  const q = (document.getElementById('recFiltroQ')?.value || '').toLowerCase().trim();
  const desde = document.getElementById('recFiltroDesde')?.value || '';
  const hasta = document.getElementById('recFiltroHasta')?.value || '';
  const estado = document.getElementById('recFiltroEstado')?.value || 'todos';
  return lista.filter(x => {
    // Filtro por estado
    if (estado === 'liquidado') {
      if (x.cancelado || (x.saldoPendiente || 0) > 0) return false;
    } else if (estado === 'pendiente') {
      if (x.cancelado || !((x.saldoPendiente || 0) > 0)) return false;
    } else if (estado === 'cancelado') {
      if (!x.cancelado) return false;
    }
    // Filtro por rango de fechas (formato YYYY-MM-DD)
    if (desde || hasta) {
      const fechaRec = x.fecha || x.fecha_recibo || '';
      // Normalizar fecha del recibo a YYYY-MM-DD
      let fechaNorm = '';
      if (/^\d{4}-\d{2}-\d{2}/.test(fechaRec)) {
        fechaNorm = fechaRec.substring(0, 10);
      } else if (/^\d{2}\/\d{2}\/\d{4}/.test(fechaRec)) {
        const partes = fechaRec.substring(0, 10).split('/');
        fechaNorm = partes[2] + '-' + partes[1] + '-' + partes[0];
      }
      if (fechaNorm) {
        if (desde && fechaNorm < desde) return false;
        if (hasta && fechaNorm > hasta) return false;
      }
    }
    // Filtro de búsqueda por texto
    if (q) {
      const folioStr = String(x.folio || '');
      const nombre = (x.nombre || '').toLowerCase();
      const responsable = (x.responsable || '').toLowerCase();
      // Conceptos: buscar en descripciones
      const conceptosTxt = ((x.conceptos || []).map(c => 
        (c.concepto || '') + ' ' + (c.descripcion || '')
      ).join(' ')).toLowerCase();
      const tramites = (x.tramites || '').toLowerCase();
      const placa = (x.placa || '').toLowerCase();
      if (!folioStr.includes(q) && 
          !nombre.includes(q) && 
          !responsable.includes(q) &&
          !conceptosTxt.includes(q) &&
          !tramites.includes(q) &&
          !placa.includes(q)) {
        return false;
      }
    }
    return true;
  });
}
function filtrarRecibos() {
  // Aplicar filtros con debounce de 200ms
  if (typeof debounce === 'function') {
    if (!filtrarRecibos._debounced) {
      filtrarRecibos._debounced = debounce(() => renderRec(), 200);
    }
    filtrarRecibos._debounced();
  } else {
    renderRec();
  }
}
function limpiarFiltrosRecibos() {
  const ids = ['recFiltroQ','recFiltroDesde','recFiltroHasta'];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const sel = document.getElementById('recFiltroEstado');
  if (sel) sel.value = 'todos';
  renderRec();
}
function exportarRecibosCSV() {
  const recArr1 = (typeof REC !== 'undefined' ? REC.recibos : []) || [];
  const recArr2 = (typeof appData !== 'undefined' ? appData.recibos : []) || [];
  const foliosVistos = new Set();
  const rTodos = [...recArr2, ...recArr1].filter(x => {
    if (foliosVistos.has(x.folio)) return false;
    foliosVistos.add(x.folio); return true;
  }).sort((function(a,b){ var fa=(a.fecha||a.fecha_recibo||'')+'T'+(a.hora||'00:00'); var fb=(b.fecha||b.fecha_recibo||'')+'T'+(b.hora||'00:00'); if(fb!==fa) return fb.localeCompare(fa); if(a.folio!==b.folio) return (b.folio||0)-(a.folio||0); var la=(a.letra||'A'),lb=(b.letra||'A'); return la<lb?-1:la>lb?1:0; }));
  // Aplicar los mismos filtros que están activos en pantalla
  const r = aplicarFiltrosRecibos(rTodos);
  if (r.length === 0) {
    toast('No hay recibos para exportar con los filtros actuales', 'err');
    return;
  }
  const BOM = '\uFEFF';
  const headers = [
    'Folio', 'Cliente', 'Fecha', 'Hora', 'Responsable',
    'Total', 'Anticipo', 'Saldo', 'Estado',
    'Tipo trámite', 'Placa', 'Conceptos', 'Trámites'
  ];
  const escapar = (s) => {
    if (s === null || s === undefined) return '""';
    const txt = String(s).replace(/"/g, '""');
    return '"' + txt + '"';
  };
  const lineas = [headers.map(escapar).join(',')];
  r.forEach(x => {
    const total = toNumero(x.total, 0);
    const ant = toNumero(x.anticipo, 0);
    const saldo = x.saldoPendiente ?? Math.max(0, total - ant);
    const estado = x.cancelado ? 'Cancelado' : (saldo > 0 ? 'Pendiente' : 'Liquidado');
    const conceptos = (x.conceptos || []).map(c => 
      (c.concepto || '') + (c.descripcion ? ': ' + c.descripcion : '') + 
      (c.precio ? ' ($' + c.precio + ')' : '')
    ).join(' | ');
    lineas.push([
      x.folio || '',
      x.nombre || '',
      x.fecha || x.fecha_recibo || '',
      x.hora || x.hora_recibo || '',
      x.responsable || '',
      total,
      ant,
      saldo,
      estado,
      x.tipoTramite || '',
      x.placa || '',
      conceptos,
      x.tramites || ''
    ].map(escapar).join(','));
  });
  const csv = BOM + lineas.join('\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8;'}));
  a.download = 'LEX_Recibos_' + hoy() + '.csv';
  a.click();
  toast('✓ ' + r.length + ' recibos exportados a CSV', 'ok');
}
