function setDirF(f,el){filtroDT=f;document.querySelectorAll('#panel-directorio .fbtn').forEach(b=>b.classList.remove('active'));el.classList.add('active');renderDir();}
// Mejora 2: actualizar el datalist global de clientes para autocompletado
// Se llama cada vez que el directorio cambia (renderDir, sincronización, etc.)
function actualizarDatalistClientes() {
  const dl = document.getElementById('datalist-clientes');
  if (!dl) return;
  const todos = D.directorio || [];
  // Obtener nombres únicos, ordenados alfabéticamente
  const nombresSet = new Set();
  todos.forEach(c => {
    if (c.nombre && c.nombre.trim()) nombresSet.add(c.nombre.trim());
  });
  const nombres = Array.from(nombresSet).sort((a,b) => a.localeCompare(b,'es'));
  // Generar HTML
  dl.innerHTML = nombres.map(n => '<option value="'+esc(n)+'">').join('');
}
function renderDir(){
  const todos = D.directorio || [];
  const setStat = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };
  setStat('dirStTot', todos.length);
  setStat('dirStCli', todos.filter(c=>(c.tipo||'').toLowerCase().includes('cliente')).length);
  setStat('dirStGes', todos.filter(c=>(c.tipo||'').toLowerCase().includes('gestor')).length);
  setStat('dirStLic', todos.filter(c=>(c.tipo||'').toLowerCase().includes('licenciado')).length);
  actualizarDatalistClientes();
  const q=($('dirQ')?.value||'').toLowerCase();
  let l=D.directorio.filter(c=>{
    if(filtroDT!=='todos'&&!c.tipo?.toLowerCase().includes(filtroDT)) return false;
    if(q){
      const tels=[(c.tel||''),(c.tel2||'')].join(' ');
      return (c.nombre||'').toLowerCase().includes(q)
        || tels.includes(q)
        || (c.desc||'').toLowerCase().includes(q)
        || (c.pob||'').toLowerCase().includes(q);
    }
    return true;
  });
  const g=$('dirGrid');
  if(!l.length){
    g.innerHTML='<div style="color:var(--muted);padding:20px;font-size:0.76rem;">Sin resultados.</div>';
    return;
  }
  // Ordenar alfabéticamente
  l = [...l].sort((a,b)=>(a.nombre||'').localeCompare(b.nombre||'','es'));
  // Agrupar por letra inicial
  const grupos = {};
  l.forEach(c => {
    const letra = (c.nombre||'?')[0].toUpperCase();
    if(!grupos[letra]) grupos[letra] = [];
    grupos[letra].push(c);
  });
  const tipoColor = t => {
    const tl = (t||'').toLowerCase();
    if(tl.includes('cliente'))    return '#2a9a4a';
    if(tl.includes('licenciado')) return '#1a4a8a';
    if(tl.includes('gestor'))     return '#c8952a';
    if(tl.includes('secretar'))   return '#7a3a8a';
    return '#7a6840';
  };
  g.innerHTML = Object.keys(grupos).sort().map(letra => {
    const filas = grupos[letra].map(c => {
      const idx = D.directorio.indexOf(c);
      const tels = [c.tel, c.tel2].filter(Boolean).join('  ·  ');
      const relacion = c.desc || c.pob || '';
      const color = tipoColor(c.tipo);
      return `<div style="display:flex;align-items:center;gap:0;padding:7px 12px;border-bottom:1px solid rgba(200,149,42,0.07);transition:background 0.12s;" onmouseover="this.style.background='rgba(200,149,42,0.05)'" onmouseout="this.style.background=''">
        <!-- Nombre -->
        <div style="flex:2;min-width:0;font-family:sans-serif;font-size:0.88rem;font-weight:600;color:var(--gold-l);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${esc(c.nombre)}</div>
        <!-- Tipo/Relación -->
        <div style="flex:2;min-width:0;font-size:0.72rem;color:#7a6840;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:0 8px;">
          <span style="display:inline-block;background:${color}22;color:${color};border-radius:4px;padding:1px 7px;font-size:0.62rem;font-weight:600;margin-right:5px;">${esc(c.tipo||'—')}</span>${relacion?esc(relacion):''}
        </div>
        <!-- Teléfonos -->
        <div style="flex:2;min-width:0;font-family:monospace;font-size:0.72rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${tels?'📞 '+tels:'—'}</div>
        <!-- Botón editar -->
        <button onclick="event.stopPropagation();_abrirFormContacto(${idx})" title="Editar" style="background:none;border:1px solid rgba(200,149,42,0.2);border-radius:6px;padding:3px 8px;cursor:pointer;color:var(--muted);font-size:0.75rem;margin-left:8px;transition:all 0.15s;flex-shrink:0;" onmouseover="this.style.borderColor='var(--gold)';this.style.color='var(--gold-d)'" onmouseout="this.style.borderColor='rgba(200,149,42,0.2)';this.style.color='var(--muted)'">✏️</button>
      </div>`;
    }).join('');
    return `<!-- Bloque ${letra} -->
    <div style="display:flex;align-items:center;gap:8px;padding:10px 12px 4px;background:rgba(200,149,42,0.06);border-top:1.5px solid rgba(200,149,42,0.15);margin-top:4px;">
      <span style="font-family:serif;font-size:1.1rem;font-weight:700;color:var(--gold);min-width:20px;">${letra}</span>
      <span style="font-family:monospace;font-size:0.55rem;color:var(--muted);">${grupos[letra].length} contacto${grupos[letra].length>1?'s':''}</span>
    </div>
    ${filas}`;
  }).join('');
}
function abrirContacto(idx){
  // Nuevo contacto → ir directo al formulario
  if(idx === undefined || idx < 0){
    _abrirFormContacto(-1);
    return;
  }
  // Contacto existente → mostrar perfil con historial
  _abrirPerfilContacto(idx);
}
let _perfilIdxActual = -1;
function _abrirPerfilContacto(idx){
  _perfilIdxActual = idx;
  const c = D.directorio[idx] || {};
  const initials = (c.nombre||'?').split(' ').slice(0,2).map(w=>w[0]?.toUpperCase()||'').join('');
  $('perfilAvatar').textContent = initials;
  $('perfilNombre').textContent = c.nombre || '—';
  $('perfilMeta').innerHTML = [
    c.tipo ? `<span class="tag ${c.tipo.toLowerCase().includes('cliente')?'tag-v':c.tipo.toLowerCase().includes('licenciado')?'tag-b':'tag-m'}" style="font-size:0.58rem;">${esc(c.tipo)}</span>` : '',
    c.tel  ? `📞 ${esc(c.tel)}` : '',
    c.pob  ? `📍 ${esc(c.pob)}` : '',
  ].filter(Boolean).join(' &nbsp;·&nbsp; ');
  // Llenar las 3 pestañas
  _perfilRenderRecibos(c);
  _perfilRenderPendientes(c);
  _perfilRenderJuicios(c);
  // Activar pestaña recibos por defecto
  perfilTab('recibos', document.querySelector('#mPerfilContacto .perfil-tab'));
  $('mPerfilContacto').classList.add('show');
}
function _perfilRenderRecibos(c){
  const nombre = (c.nombre||'').toLowerCase();
  const recibos = ((typeof appData!=='undefined'?appData.recibos:[])||[])
    .concat(REC.recibos||[])
    .filter((r,i,arr)=>arr.findIndex(x=>x.folio===r.folio)===i) // dedup
    .filter(r=>(r.nombre||'').toLowerCase().includes(nombre.split(' ')[0]) && nombre.length>2)
    .sort((a,b)=>b.folio-a.folio);
  const totalCobrado = recibos.reduce((s,r)=>s+(parseFloat(r.anticipo)||0),0);
  const totalPendiente = recibos.reduce((s,r)=>s+(parseFloat(r.saldoPendiente)||0),0);
  const totalFacturado = recibos.reduce((s,r)=>s+(parseFloat(r.total)||0),0);
  let html = '';
  if(recibos.length){
    html += `<div class="perfil-resumen">
      <div class="perfil-stat"><div class="perfil-stat-val" style="color:#4dca6a;">$${fmt(totalCobrado)}</div><div class="perfil-stat-lbl">Cobrado</div></div>
      <div class="perfil-stat"><div class="perfil-stat-val" style="color:#e8c875;">$${fmt(totalPendiente)}</div><div class="perfil-stat-lbl">Pendiente</div></div>
      <div class="perfil-stat"><div class="perfil-stat-val">$${fmt(totalFacturado)}</div><div class="perfil-stat-lbl">Total facturado</div></div>
    </div>`;
    html += recibos.map(r=>{
      const saldo = parseFloat(r.saldoPendiente)||0;
      const badge = saldo>0
        ? `<span class="perfil-row-badge" style="color:#e8c875;background:rgba(200,149,42,0.12);">$${fmt(saldo)} pend.</span>`
        : `<span class="perfil-row-badge" style="color:#4dca6a;background:rgba(40,180,80,0.1);">✓ Liquidado</span>`;
      const concepto = (r.conceptos||[]).map(c=>c.concepto).join(', ') || '—';
      return `<div class="perfil-row" onclick="cerrar('mPerfilContacto');abrirPreviaDesdeContab(${r.folio})">
        <div class="perfil-row-icon">🧾</div>
        <div class="perfil-row-main">
          <div class="perfil-row-title">#${folioConLetra(r.folio, r.anio_folio, r.letra||letraVersion(r)||'A')} — ${esc(concepto)}</div>
          <div class="perfil-row-sub">${r.fecha||''} · $${fmt(r.total||0)} total · $${fmt(r.anticipo||0)} cobrado</div>
        </div>
        ${badge}
      </div>`;
    }).join('');
  } else {
    html = `<div class="perfil-empty">📭 Sin recibos registrados</div>`;
  }
  $('perfilTabRecibos').innerHTML = html;
}
function _perfilRenderPendientes(c){
  const nombre = (c.nombre||'').toLowerCase().split(' ')[0];
  const pendientes = (D.pendientes||[])
    .filter(p=> nombre.length>2 && (p.nombre||'').toLowerCase().includes(nombre))
    .sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''));
  if(!pendientes.length){
    $('perfilTabPendientes').innerHTML = `<div class="perfil-empty">📭 Sin pendientes registrados</div>`;
    return;
  }
  $('perfilTabPendientes').innerHTML = pendientes.map(p=>{
    const badge = p.completado
      ? `<span class="perfil-row-badge" style="color:#4dca6a;background:rgba(40,180,80,0.1);">✓ Listo</span>`
      : `<span class="perfil-row-badge" style="color:#e8c875;background:rgba(200,149,42,0.12);">Activo</span>`;
    return `<div class="perfil-row" onclick="cerrar('mPerfilContacto');ir('pendientes')">
      <div class="perfil-row-icon">📌</div>
      <div class="perfil-row-main">
        <div class="perfil-row-title">${esc(p.nombre||'—')}</div>
        <div class="perfil-row-sub">${esc(p.desc||'')}${p.resp?' · '+esc(p.resp):''}</div>
      </div>
      ${badge}
    </div>`;
  }).join('');
}
function _perfilRenderJuicios(c){
  const nombre = (c.nombre||'').toLowerCase().split(' ')[0];
  const juicios = (D.juicios||[])
    .filter(j=> nombre.length>2 && (j.nombre||'').toLowerCase().includes(nombre))
    .sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''));
  if(!juicios.length){
    $('perfilTabJuicios').innerHTML = `<div class="perfil-empty">📭 Sin juicios registrados</div>`;
    return;
  }
  $('perfilTabJuicios').innerHTML = juicios.map(j=>{
    const badge = j.estatus
      ? `<span class="perfil-row-badge" style="color:#a0c0ff;background:rgba(100,150,255,0.12);">${esc(j.estatus)}</span>`
      : '';
    return `<div class="perfil-row" onclick="cerrar('mPerfilContacto');ir('juicios')">
      <div class="perfil-row-icon">⚖️</div>
      <div class="perfil-row-main">
        <div class="perfil-row-title">${esc(j.nombre||'—')}</div>
        <div class="perfil-row-sub">${j.expediente?'Exp. '+esc(j.expediente)+' · ':''}${esc(j.juzgado||'')}</div>
      </div>
      ${badge}
    </div>`;
  }).join('');
}
function perfilTab(tab, el){
  document.querySelectorAll('#mPerfilContacto .perfil-tab').forEach(t=>t.classList.remove('active'));
  document.querySelectorAll('#mPerfilContacto .perfil-tab-body').forEach(b=>b.classList.remove('active'));
  if(el) el.classList.add('active');
  $('perfilTab'+tab.charAt(0).toUpperCase()+tab.slice(1))?.classList.add('active');
}
function perfilEditar(){
  cerrar('mPerfilContacto');
  _abrirFormContacto(_perfilIdxActual);
}
function _abrirFormContacto(idx){
  eiC=idx>=0?idx:-1;const c=idx>=0?D.directorio[idx]:{};
  $('cN').value=c.nombre||'';
  $('cT').value=c.tel||'';
  $('cT2').value=c.tel2||'';
  // Si el tipo no está en las opciones, agregarlo dinámicamente
  const sel=$('cTipo');
  const tipoVal=c.tipo||'Cliente';
  if(tipoVal && ![...sel.options].some(o=>o.value===tipoVal)){
    const opt=document.createElement('option');
    opt.value=tipoVal; opt.textContent=tipoVal; sel.appendChild(opt);
  }
  sel.value=tipoVal;
  $('cP').value=c.pob||'';
  $('cEmail').value=c.email||'';
  $('cRFC').value=c.rfc||'';
  $('cDesc').value=c.desc||'';
  $('cO').value=c.obs||'';
  $('mCTitulo').textContent=idx>=0?'Editar Contacto':'Nuevo Contacto';
  const btnEl=$('btnEliminarContacto');
  if(btnEl) btnEl.style.display=idx>=0?'inline-flex':'none';
  const hist=$('cTelHistorial');
  const histLista=$('cTelHistorialLista');
  const anteriores=(c.telHistorial||[]).filter(h=>h.tel&&h.tel!==c.tel);
  if(anteriores.length&&hist&&histLista){
    hist.style.display='block';
    histLista.innerHTML=anteriores.map(h=>`<span style="display:inline-block;background:#f0ead8;padding:2px 8px;border-radius:10px;margin:2px;font-family:monospace;">📞 ${esc(h.tel)}${h.desde&&h.desde!=='anterior'?' <span style="opacity:0.5;font-size:0.85em;">'+h.desde+'</span>':''}</span>`).join('');
  } else if(hist){ hist.style.display='none'; }
  $('mContacto').classList.add('show');
}
function guardarContacto(){
  try {
  const nombre=$('cN').value.trim();
  if(!nombre){toast('El nombre es obligatorio','err');return;}
  const tel=$('cT').value.trim();
  const tel2=$('cT2').value.trim();
  if(eiC>=0){
    // Editar existente — preservar historial de teléfonos
    const c=D.directorio[eiC];
    const telAnterior=(c.tel||'').trim();
    if(!c.telHistorial) c.telHistorial=telAnterior?[{tel:telAnterior,desde:'anterior'}]:[];
    if(tel&&tel!==telAnterior){
      const yaEsta=c.telHistorial.some(h=>h.tel===tel);
      if(!yaEsta) c.telHistorial.push({tel:tel,desde:hoy()});
    }
    if(tel2&&tel2!==tel){
      const yaEsta2=c.telHistorial.some(h=>h.tel===tel2);
      if(!yaEsta2) c.telHistorial.push({tel:tel2,desde:hoy()});
    }
    c.nombre=nombre; c.tel=tel; c.tel2=tel2;
    c.tipo=$('cTipo').value; c.pob=$('cP').value.trim();
    c.email=$('cEmail').value.trim(); c.rfc=$('cRFC').value.trim().toUpperCase();
    c.desc=$('cDesc').value.trim(); c.obs=$('cO').value.trim();
    // Id + marca de tiempo — necesarios para el merge de sincronizarFolio()
    // (mismo fix que carpetas/escrituras/citas/pendientes/juicios). Los
    // contactos viejos sin id lo reciben aquí, en su primera edición.
    if(!c.id) c.id = 'CONT-'+Date.now();
    c.fechaMod = new Date().toISOString();
  } else {
    // Nuevo contacto
    const historial=[];
    if(tel) historial.push({tel,desde:hoy()});
    if(tel2&&tel2!==tel) historial.push({tel:tel2,desde:hoy()});
    D.directorio.unshift({
      id: 'CONT-'+Date.now(),
      fechaMod: new Date().toISOString(),
      nombre, tel, tel2,
      tipo:$('cTipo').value, pob:$('cP').value.trim(),
      email:$('cEmail').value.trim(), rfc:$('cRFC').value.trim().toUpperCase(),
      desc:$('cDesc').value.trim(), obs:$('cO').value.trim(),
      telHistorial:historial
    });
  }
  save();renderDir();cerrar('mContacto');toast('Contacto guardado ✓','ok');syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
  } catch(e){ console.error('[guardarContacto]', e); toast('Error al guardar: '+e.message,'err'); }
}
async function eliminarContacto(){
  if(eiC<0)return;
  const c=D.directorio[eiC];
  const ok = await confirmarBonito({
    titulo: 'Eliminar contacto',
    mensaje: '¿Eliminar a '+c.nombre+' del directorio?\n\nEsta acción no se puede deshacer.',
    btnSi: 'Sí, eliminar',
    btnNo: 'Cancelar',
    peligro: true
  });
  if(!ok) return;
  const rowSheets = c._rowSheets;
  _marcarContactoEliminadoLocal(c.id);
  D.directorio.splice(eiC,1);
  save();renderDir();cerrar('mContacto');toast('Contacto eliminado','ok');syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
}
// ═══ CARPETAS ═══
function setCarpF(f,el){filtroCT=f;document.querySelectorAll('#panel-carpetas .stats-grid .stat').forEach(b=>b.classList.remove('active'));if(el)el.classList.add('active');renderCarp();}
// Devuelve las observaciones de una carpeta como arreglo de {texto,fecha}
// (lista numerada nueva, con la fecha registrada sola al agregarse). Si la
// carpeta es vieja y solo tiene el texto legado en c.obs, lo trata como una
// entrada más. La antigua "Descripción/Asunto" (c.descripcion) — antes un
// campo aparte — ahora se muestra como la nota #1, adelante de las demás;
// en cuanto se vuelva a guardar desde Editar Carpeta, ese texto pasa a vivir
// dentro de obsLista y c.descripcion se limpia (evita que se duplique).
function _carpObsArray(c){
  let lista = [];
  if(Array.isArray(c.obsLista) && c.obsLista.length){
    lista = c.obsLista
      .map(item => (item && typeof item === 'object') ? { texto:String(item.texto||''), fecha:String(item.fecha||'') } : { texto:String(item||''), fecha:'' })
      .filter(o => o.texto.trim() !== '');
  } else if(c.obs && String(c.obs).trim()!==''){
    lista = [{ texto:String(c.obs), fecha:'' }];
  }
  if(c.descripcion && String(c.descripcion).trim()!==''){
    lista = [{ texto:String(c.descripcion), fecha:_fechaCorta(c.fechaCreacion) }, ...lista];
  }
  return lista;
}
// HTML de las observaciones como lista numerada, justificada y con fecha
// (usa esc() global si existe).
function _carpObsHtmlEnum(c){
  const esc2 = (s) => (typeof esc === 'function' ? esc(s == null ? '' : s) : String(s == null ? '' : s));
  const lista = _carpObsArray(c);
  if(!lista.length) return '';
  return '<ol style="margin:0;padding-left:18px;">' + lista.map(o=>
    '<li style="margin-bottom:6px;line-height:1.5;text-align:justify;">'+esc2(o.texto)
    + (o.fecha ? ' <span style="font-family:monospace;font-size:0.6rem;color:#0e6a7c;white-space:nowrap;font-weight:600;">— 📅 '+esc2(o.fecha)+'</span>' : '')
    + '</li>'
  ).join('') + '</ol>';
}
// Texto completo de una carpeta para el buscador — incluye todo lo que se
// ve en la ficha de Detalles (subtipo del trámite, notario/volumen de
// escrituras, etc.) y cada nota de Observaciones/Notas internas, para que
// buscar una palabra que solo está adentro de esos cuadros sí encuentre la
// carpeta (antes solo buscaba en cliente/número/estatus/descripcion).
function _carpTextoBusqueda(c){
  const partes = [
    c.cliente, c.num, c.estatus, c.tipoTramite,
    c.juicioDesc, c.escTipo, c.escNotario, c.escVolumen, c.escInstrumento,
    c.regCivilTipo, c.docDesc
  ];
  _carpObsArray(c).forEach(o => partes.push(o.texto));
  return partes.filter(Boolean).join(' ').toLowerCase();
}
// Espacio dedicado y amplio para CONSULTAR qué contiene la carpeta. Ya no es
// editable aquí — es solo lectura; la numeración de Observaciones/Notas
// internas se edita exclusivamente desde "Editar Carpeta" (kObsLista) y esta
// ficha simplemente la muestra con espacio de sobra y bien distinguida.
function abrirDetallesCarpeta(idx){
  const c = D.carpetas[idx];
  if(!c) return;
  let modal = document.getElementById('mCarpDetalles');
  if(!modal){
    modal = document.createElement('div');
    modal.className = 'modal-ov';
    modal.id = 'mCarpDetalles';
    modal.innerHTML = `<div class="modal wide" style="max-width:640px;width:94vw;max-height:88vh;overflow-y:auto;box-sizing:border-box;margin:auto;background:linear-gradient(135deg,#fdfaf4 0%,#f5edd8 100%);border-radius:16px;border:2px solid #d4b870;">
      <div class="modal-hdr" style="background:linear-gradient(135deg,#fdfaf4,#f7f3e8);border-bottom:2px solid #d4b870;border-radius:14px 14px 0 0;">
        <h3 id="mCarpDetTitulo" style="color:#4a2f08;font-weight:700;font-family:monospace;font-size:0.85rem;letter-spacing:0.1em;text-transform:uppercase;">EXPEDIENTE</h3>
        <div style="display:flex;align-items:center;gap:8px;">
          <button id="mCarpDetBtnEditar" style="display:flex;align-items:center;gap:5px;background:#fdf6e3;border:1.5px solid #d4b870;border-radius:8px;padding:6px 14px;cursor:pointer;font-family:monospace;font-size:0.68rem;font-weight:700;color:#8c6518;">✏️ Editar expediente</button>
          <button class="modal-x" style="color:#8c6518;" onclick="cerrar('mCarpDetalles')">✕</button>
        </div>
      </div>
      <!-- Encabezado con la identificación del expediente, a dos columnas -->
      <div id="mCarpDetEncabezado" style="border-bottom:1.5px solid #ecdfa8;"></div>
      <div class="modal-body" style="padding:20px 24px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
          <label style="display:block;font-family:monospace;font-size:0.6rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:#8c6518;">Observaciones / Notas internas</label>
          <button id="mCarpDetBtnAgregar" type="button" style="display:flex;align-items:center;gap:4px;padding:4px 12px;border-radius:14px;border:1px solid #d4b870;background:#fdf6e3;color:#8c6518;font-size:0.65rem;font-weight:700;cursor:pointer;font-family:monospace;">✏️ Editar notas</button>
        </div>
        <div id="mCarpDetBox" style="width:100%;min-height:220px;border:2px solid #d4b870;border-radius:10px;padding:16px 18px;font-family:sans-serif;font-size:0.92rem;line-height:1.7;color:#1a1008;background:#fdf8e8;box-sizing:border-box;"></div>
      </div>
      <div style="padding:14px 24px 20px;border-top:1.5px solid #ecdfa8;background:linear-gradient(135deg,#fdfaf4,#f7f0dc);border-radius:0 0 14px 14px;display:flex;justify-content:flex-end;gap:10px;">
        <button onclick="cerrar('mCarpDetalles')" style="background:none;border:1.5px solid #d4b870;border-radius:10px;padding:10px 22px;cursor:pointer;font-family:monospace;font-size:0.68rem;letter-spacing:0.08em;text-transform:uppercase;color:#8c6518;font-weight:700;">Cancelar</button>
        <button id="mCarpDetBtnGuardar" style="background:linear-gradient(135deg,#8c6518,#c8952a,#e8c060);border:none;border-radius:10px;padding:10px 28px;cursor:pointer;font-family:monospace;font-size:0.72rem;letter-spacing:0.08em;text-transform:uppercase;color:#fff;font-weight:700;">💾 Guardar</button>
      </div>
    </div>`;
    document.body.appendChild(modal);
  }
  // Mostrar el modal ANTES de calcular el alto automático de los textarea de
  // Observaciones: mientras el modal tiene display:none, scrollHeight da 0 y
  // el auto-grow colapsaba cada textarea a 0px, dejando el texto (y hasta el
  // placeholder) invisible aunque sí estuviera cargado correctamente.
  modal.classList.add('show');
  const esc2 = (s) => (typeof esc === 'function' ? esc(s == null ? '' : s) : String(s == null ? '' : s));
  document.getElementById('mCarpDetTitulo').innerHTML = 'EXPEDIENTE · <span style="font-size:1.15em;">'+(esc2(c.num)||'—')+'</span>';
  document.getElementById('mCarpDetBtnEditar').onclick = function(){
    const idxLive = D.carpetas.indexOf(c);
    cerrar('mCarpDetalles');
    abrirCarpeta(idxLive >= 0 ? idxLive : idx);
  };
  // ── Encabezado a dos columnas: izquierda = identificación (número,
  // estatus, fecha); derecha = cliente y trámite (tipo + subtipo fundidos
  // en una sola línea, ya no repetidos en dos campos separados). Un solo
  // badge de estatus (antes se repetía con "Estado del Archivo", campo
  // legado que ya cubre lo mismo).
  (function(){
    const enc = document.getElementById('mCarpDetEncabezado');
    if(!enc) return;
    const chip2 = (label, bg, col, border) =>
      '<span style="display:inline-block;padding:3px 10px;border-radius:3px;font-family:monospace;font-size:0.64rem;font-weight:700;background:'+bg+';color:'+col+';border:1.5px solid '+border+';letter-spacing:0.04em;">'+esc2(label)+'</span>';
    const estatusChip = (() => {
      const e = (c.estatus||'').toUpperCase();
      if(!c.estatus) return '';
      if(e.includes('ARCHIVADO')) return chip2(c.estatus,'#f5f0e8','#5a4a20','#b89840');
      if(e.includes('CONCLUIDO')||e.includes('ENTREGAD')) return chip2(c.estatus,'#eaf4ed','#0d5c2a','#3aaa6a');
      if(e.includes('CANCELADO')) return chip2(c.estatus,'#fdf0f0','#8a1010','#e06060');
      return chip2(c.estatus,'#eef3ff','#1a3a8a','#6090d0');
    })();
    const TIPO_TRAMITE_LABEL = { juicio:'⚖️ Juicio', escritura:'📜 Escritura', registro_civil:'📋 Registro Civil', documentos:'📄 Documentos' };
    const tipoLbl = TIPO_TRAMITE_LABEL[c.tipoTramite] || c.tipoTramite || '—';
    // Subtipo/descripción según el tipo de trámite guardado
    let subtipo = '';
    if(c.tipoTramite === 'juicio' && c.juicioDesc) subtipo = c.juicioDesc;
    else if(c.tipoTramite === 'escritura'){
      const partes = [];
      if(c.escTipo) partes.push(c.escTipo);
      if(c.escNotario) partes.push('Notario: '+c.escNotario);
      if(c.escVolumen || c.escInstrumento) partes.push('V'+(c.escVolumen||'—')+' · I'+(c.escInstrumento||'—'));
      subtipo = partes.join(' · ');
    } else if(c.tipoTramite === 'registro_civil' && c.regCivilTipo) subtipo = {registro_extemporaneo:'Registro Extemporáneo',rectificacion_nombre:'Rectificación de Nombre',aclaracion_nombre:'Aclaración de Nombre'}[c.regCivilTipo]||c.regCivilTipo;
    else if(c.tipoTramite === 'documentos' && c.docDesc) subtipo = c.docDesc;
    const etq = (label) => '<div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;font-family:monospace;">'+label+'</div>';
    enc.innerHTML =
        '<div style="display:grid;grid-template-columns:150px minmax(0,1fr);">'
      +   '<div style="padding:18px 16px;border-right:1.5px solid #ecdfa8;">'
      +     etq('Estatus')
      +     (estatusChip ? '<div>'+estatusChip+'</div>' : '<div style="color:#c0b090;font-size:0.8rem;">—</div>')
      +     (c.ingreso ? ('<div style="margin-top:14px;">'+etq('Ingreso')+'<div style="font-size:0.85rem;color:#1a1008;font-weight:600;">📅 '+esc2(c.ingreso)+'</div></div>') : '')
      +     (c.celebEscritura ? ('<div style="margin-top:14px;">'+etq('Celebración')+'<div style="font-size:0.85rem;color:#1a1008;font-weight:600;">📅 '+esc2(c.celebEscritura)+'</div></div>') : '')
      +   '</div>'
      +   '<div style="padding:18px 20px;">'
      +     etq('Nombre / Cliente')
      +     '<div style="font-size:0.95rem;font-weight:600;color:#1a1008;margin-bottom:12px;">'+(esc2(c.cliente)||'—')+'</div>'
      +     etq('Trámite')
      +     '<div style="font-size:0.85rem;color:#1a3a7a;font-weight:600;line-height:1.5;">'+esc2(tipoLbl)+(subtipo ? ' <span style="color:#1a1008;font-weight:400;font-style:italic;">· '+esc2(subtipo)+'</span>' : '')+'</div>'
      +   '</div>'
      + '</div>';
  })();
  // ── Cuadro blanco: numeración de Observaciones/Notas internas. Por
  // defecto se abre en modo CONSULTA (solo lectura) — para editar hay que
  // pulsar el botón junto a la etiqueta, que entonces cambia a modo edición
  // con los renglones numerados y el "＋" para agregar más.
  _dObsState = _carpObsArray(c).map(o => ({ texto: o.texto }));
  if(!_dObsState.length) _dObsState = [{ texto:'' }];
  _dObsEditMode = false;
  _dObsRender();
  document.getElementById('mCarpDetBtnAgregar').onclick = function(){
    if(!_dObsEditMode){ _dObsEditMode = true; _dObsRender(); }
    else { _dObsAgregar(); }
  };
  document.getElementById('mCarpDetBtnGuardar').onclick = async function(){
    const btn = this;
    if(btn.disabled) return; // evita doble clic mientras guarda
    const original = btn.innerHTML;
    // Buscar por número de carpeta (permanente) en vez de por referencia
    // de objeto: si en el fondo llegó una sincronización con Supabase
    // mientras el modal estaba abierto, D.carpetas puede haberse
    // reconstruido con objetos nuevos y "c" ya no sería el mismo — eso
    // hacía que Guardar no encontrara nada y no pasara nada, sin aviso.
    const idxPrevio = D.carpetas.findIndex(x => x.num === c.num);
    if(idxPrevio < 0){
      if(typeof toast === 'function') toast('⚠ No se encontró la carpeta — vuelve a intentar', 'err');
      return;
    }
    // Guardrail contra pérdida de datos: si esta ficha guardaría las
    // Observaciones vacías pero la carpeta YA tenía texto real ahí, se pide
    // confirmación explícita antes de sobrescribir en silencio.
    const _obsNuevoVacio = !_dObsState.some(o => String((o&&o.texto)||'').trim()!=='');
    const _obsViejo = D.carpetas[idxPrevio] || {};
    const _teniaObsReal =
      (Array.isArray(_obsViejo.obsLista) && _obsViejo.obsLista.some(o => String((o&&typeof o==='object')?o.texto:o||'').trim()!=='')) ||
      (_obsViejo.obs && String(_obsViejo.obs).trim()!=='') ||
      (_obsViejo.descripcion && String(_obsViejo.descripcion).trim()!=='');
    if(_obsNuevoVacio && _teniaObsReal){
      const ok = await confirmarBonito({
        titulo: 'Observaciones vacías',
        mensaje: 'Esta carpeta ya tenía texto en Observaciones/Notas internas y así se guardaría vacío.\n\n¿Seguro que quieres borrar ese contenido?',
        btnSi: 'Sí, guardar vacío',
        btnNo: 'Cancelar',
        peligro: true
      });
      if(!ok) return;
    }
    btn.disabled = true;
    btn.style.opacity = '0.75';
    btn.style.cursor = 'wait';
    btn.innerHTML = '<span style="display:inline-block;width:11px;height:11px;border:2px solid #fff;border-top-color:transparent;border-radius:50%;animation:spin 0.6s linear infinite;margin-right:7px;vertical-align:-1px;"></span>Guardando…';
    // Pequeño respiro para que el spinner se pinte antes de trabajar —
    // si no, en equipos lentos el clic parece no hacer nada.
    setTimeout(() => {
      // Re-ubicar otra vez por si algo cambió durante la confirmación.
      const idxLive = D.carpetas.findIndex(x => x.num === c.num);
      if(idxLive < 0){
        btn.disabled = false; btn.style.opacity = ''; btn.style.cursor = ''; btn.innerHTML = original;
        if(typeof toast === 'function') toast('⚠ No se encontró la carpeta — vuelve a intentar', 'err');
        return;
      }
      const nuevaLista = _dObsState
        .map(o => String((o&&o.texto)||'').trim())
        .filter(t => t !== '')
        .map(t => ({ texto:t, fecha:_fechaHoyCorta() }));
      D.carpetas[idxLive].obsLista = nuevaLista;
      D.carpetas[idxLive].obs = nuevaLista.map(o=>o.texto).join('\n\n');
      // Ya fusionada dentro de obsLista (nota #1) — se limpia para que no se
      // vuelva a duplicar la próxima vez que se abra esta carpeta.
      D.carpetas[idxLive].descripcion = '';
      D.carpetas[idxLive].fechaModificacion = new Date().toISOString();
      try { renderCarp(); } catch(e){ console.warn('[abrirDetallesCarpeta] renderCarp:', e); }
      try { save(); } catch(e){ console.warn('[abrirDetallesCarpeta] save:', e); }
      try { saveCarpetas(); } catch(e){ console.warn('[abrirDetallesCarpeta] saveCarpetas:', e); }
      try { toast('📋 Observaciones guardadas ✓'); } catch(e){}
      btn.innerHTML = '✓ Guardado';
      btn.style.cursor = '';
      // Ya no se cierra la ficha al guardar — se queda abierta y regresa
      // sola al modo consulta con el texto recién guardado.
      _dObsState = nuevaLista.length ? nuevaLista.map(o => ({ texto:o.texto })) : [{ texto:'' }];
      _dObsEditMode = false;
      _dObsRender();
      setTimeout(() => {
        btn.disabled = false; btn.style.opacity = ''; btn.innerHTML = original;
      }, 900);
    }, 30);
  };
}
// Estado del widget de Observaciones dentro de la ficha de Detalles —
// independiente del de "Editar Carpeta" (_kObsState), aunque ambos leen y
// escriben el mismo dato (c.obsLista). _dObsEditMode controla si se muestra
// en modo CONSULTA (solo lectura, por defecto al abrir) o en modo EDICIÓN
// (textareas numerados, "＋" para agregar); se activa con el botón junto a
// la etiqueta "Observaciones / Notas internas".
let _dObsState = [{ texto:'' }];
let _dObsEditMode = false;
function _dObsSyncBoton(){
  const btn = document.getElementById('mCarpDetBtnAgregar');
  if(!btn) return;
  if(_dObsEditMode){ btn.innerHTML = '＋ Agregar nota'; btn.title = 'Agregar otra observación'; }
  else { btn.innerHTML = '✏️ Editar notas'; btn.title = 'Editar observaciones'; }
}
function _dObsRender(){
  const box = document.getElementById('mCarpDetBox');
  if(!box) return;
  if(!_dObsState.length) _dObsState = [{ texto:'' }];
  const esc2 = (s) => (typeof esc === 'function' ? esc(s == null ? '' : s) : String(s == null ? '' : s));
  if(!_dObsEditMode){
    // Modo consulta: solo lectura, sin textareas — cero riesgo de tocar el
    // texto sin querer. Se edita solo tras pulsar "✏️ Editar notas".
    const conTexto = _dObsState.filter(o => String((o&&o.texto)||'').trim()!=='');
    box.innerHTML = conTexto.length
      ? conTexto.map((o,i) =>
          '<div style="display:flex;gap:10px;'+(i>0?'margin-top:12px;padding-top:12px;border-top:1px solid #ecdfa8;':'')+'">'
          +   '<span style="flex-shrink:0;color:#0e6a7c;font-family:monospace;font-size:0.85rem;font-weight:700;">'+(i+1)+'.</span>'
          +   '<p style="font-size:0.85rem;line-height:1.6;margin:0;color:#1a1008;text-align:justify;">'+esc2(o.texto)+'</p>'
          + '</div>'
        ).join('')
      : '<div style="color:#a08858;font-style:italic;font-size:0.85rem;">Sin observaciones registradas.</div>';
    _dObsSyncBoton();
    return;
  }
  box.innerHTML = _dObsState.map((item, i) => {
    const txt = (item && item.texto) || '';
    return '<div style="display:flex;gap:12px;align-items:flex-start;'+(i>0?'margin-top:16px;padding-top:16px;border-top:2px solid #e0d4a8;':'')+'">'
      +   '<div style="flex-shrink:0;color:#0e6a7c;font-family:monospace;font-size:0.95rem;font-weight:700;margin-top:2px;">'+(i+1)+'.</div>'
      +   '<textarea rows="1" data-dobs-i="'+i+'" oninput="_dObsActualizar('+i+',this.value);_dObsAutoGrow(this)" placeholder="'+(i===0?'Nota principal para uso interno del despacho...':'Otra observación...')+'" style="flex:1;min-width:0;border:none;outline:none;resize:none;overflow:hidden;font-family:sans-serif;font-size:0.92rem;line-height:1.6;color:#1a1008;background:transparent;text-align:justify;box-sizing:border-box;">'+esc2(txt)+'</textarea>'
      + '</div>';
  }).join('');
  // Cada textarea crece con su contenido — nunca hay que arrastrar ni
  // hacer scroll para ver el texto completo de una observación.
  box.querySelectorAll('textarea[data-dobs-i]').forEach(_dObsAutoGrow);
  _dObsSyncBoton();
}
function _dObsAutoGrow(el){
  if(!el) return;
  el.style.height = 'auto';
  el.style.height = el.scrollHeight + 'px';
}
function _dObsActualizar(i, val){
  if(!_dObsState[i]) _dObsState[i] = { texto:'' };
  _dObsState[i].texto = val;
  // Ya no hay botón "✕": cualquier nota (incluida la #1) se quita sola en
  // cuanto se borra todo su texto; si no queda ninguna, _dObsRender() deja
  // un renglón #1 en blanco listo para escribir.
  if(val.trim() === ''){
    _dObsState.splice(i,1);
    _dObsRender();
  }
}
function _dObsAgregar(){
  _dObsState.push({ texto:'' });
  _dObsRender();
  const box = document.getElementById('mCarpDetBox');
  const nuevas = box ? box.querySelectorAll('textarea') : [];
  const last = nuevas[nuevas.length-1];
  if(last) last.focus();
}
// ELIMINADA: la ficha "Ver Detalle" (verDetalleCarpeta) — modal viejo,
// duplicaba la ficha de Detalles nueva (abrirDetallesCarpeta) y mostraba
// datos desactualizados (columna Descripción, botón "Editar" ambiguo).
// Todos los puntos que la abrían ahora usan abrirDetallesCarpeta().
function _verDetalleCarpeta_ELIMINADA_(idx){
  const c = D.carpetas[idx];
  if(!c) return;
  const allRecibos=(typeof appData!=='undefined'?appData.recibos:REC.recibos)||[];
  const folioOficial=parseInt(String(c.reciboOficial||'').replace('#','').trim())||null;
  const recVinculados=allRecibos.filter(r=>
    (r.carpetaNum && String(r.carpetaNum)===String(c.num))||(folioOficial&&r.folio===folioOficial)||
    (r._carpetaInterna&&String(r._carpetaInterna)===String(c.num))||(r.carpeta&&String(r.carpeta)===String(c.num))
  );
  const totalCobrado=recVinculados.reduce((s,r)=>s+(parseFloat(r.anticipo)||0)+(parseFloat(r.totalAbonado)||0)-parseFloat(r.anticipo||0),0)||recVinculados.reduce((s,r)=>s+parseFloat(r.total||0),0);
  const totalPactado=parseFloat(c.totalPactado)||0;
  const saldoPend=Math.max(0,totalPactado-totalCobrado);
  const pct=totalPactado>0?Math.min(100,Math.round(totalCobrado/totalPactado*100)):0;
  function chip(label,bg,col,border){
    return `<span style="display:inline-block;padding:3px 12px;border-radius:3px;font-family:monospace;font-size:0.7rem;font-weight:700;background:${bg};color:${col};border:1.5px solid ${border};letter-spacing:0.04em;">${esc(label)}</span>`;
  }
  function estatusStyle(est){
    const e=(est||'').toUpperCase();
    if(e.includes('ARCHIVADO')) return chip(est,'#f5f0e8','#5a4a20','#b89840');
    if(e.includes('CONCLUIDO')||e.includes('ENTREGAD')) return chip(est,'#eaf4ed','#0d5c2a','#3aaa6a');
    if(e.includes('CANCELADO')) return chip(est,'#fdf0f0','#8a1010','#e06060');
    return chip(est,'#eef3ff','#1a3a8a','#6090d0');
  }
  const tipoLabel={juicio:'⚖️ Juicio',escritura:'📜 Escritura',registro_civil:'📋 Registro Civil',documentos:'📄 Documentos'}[c.tipoTramite]||c.tipoTramite||'—';
  let subtipoTexto='';
  if(c.tipoTramite==='juicio'&&c.juicioDesc) subtipoTexto=c.juicioDesc;
  else if(c.tipoTramite==='escritura'&&c.escTipo) subtipoTexto=c.escTipo+(c.escNotario?' · Not. '+c.escNotario:'')+(c.escVolumen?' · Vol. '+c.escVolumen:'');
  else if(c.tipoTramite==='registro_civil'&&c.regCivilTipo) subtipoTexto={registro_extemporaneo:'Registro Extemporáneo',rectificacion_nombre:'Rectificación de Nombre',aclaracion_nombre:'Aclaración de Nombre'}[c.regCivilTipo]||c.regCivilTipo;
  else if(c.tipoTramite==='documentos'&&c.docDesc) subtipoTexto=c.docDesc;
  let recibosHtml='<div style="color:#aaa;font-size:0.72rem;font-family:\'JetBrains Mono\',monospace;padding:8px 0;">Sin recibos vinculados</div>';
  if(recVinculados.length){
    recibosHtml=`<table style="width:100%;border-collapse:collapse;font-family:monospace;font-size:0.68rem;">
      <thead><tr style="background:#f5f0e4;border-bottom:1.5px solid #d4c890;">
        <th style="padding:6px 8px;text-align:left;font-weight:700;color:#5a4a20;">Folio</th>
        <th style="padding:6px 8px;text-align:left;font-weight:700;color:#5a4a20;">Fecha</th>
        <th style="padding:6px 8px;text-align:right;font-weight:700;color:#5a4a20;">Total</th>
        <th style="padding:6px 8px;text-align:center;font-weight:700;color:#5a4a20;">Estado</th>
      </tr></thead><tbody>
      ${recVinculados.map(r=>`<tr style="border-bottom:1px solid #e8e0d0;">
        <td style="padding:5px 8px;color:#1a3a7a;">#${r.folio||'—'}</td>
        <td style="padding:5px 8px;color:#555;">${r.fecha||r.fechaEmision||'—'}</td>
        <td style="padding:5px 8px;text-align:right;color:#0d5c2a;font-weight:700;">$${fmt(r.total||r.anticipo||0)}</td>
        <td style="padding:5px 8px;text-align:center;">${r.liquidado?'<span style="color:#0d5c2a;font-weight:700;">✅ Liq.</span>':'<span style="color:#9a6010;">⏳ Pend.</span>'}</td>
      </tr>`).join('')}
      </tbody></table>`;
  }
  const finSec = totalPactado>0?`
    <div style="margin-top:10px;padding:12px 14px;background:#f8f5ec;border:1.5px solid #d4c890;border-radius:4px;">
      <div style="display:flex;gap:20px;flex-wrap:wrap;margin-bottom:8px;">
        <div><div style="font-size:0.58rem;color:#9a8050;font-family:monospace;text-transform:uppercase;letter-spacing:0.08em;">Pactado</div><div style="font-size:1rem;font-weight:700;color:#1a1a1a;font-family:monospace;">$${fmt(totalPactado)}</div></div>
        <div><div style="font-size:0.58rem;color:#9a8050;font-family:monospace;text-transform:uppercase;letter-spacing:0.08em;">Cobrado</div><div style="font-size:1rem;font-weight:700;color:#0d5c2a;font-family:monospace;">$${fmt(totalCobrado)}</div></div>
        ${saldoPend>0?`<div><div style="font-size:0.58rem;color:#9a8050;font-family:monospace;text-transform:uppercase;letter-spacing:0.08em;">Pendiente</div><div style="font-size:1rem;font-weight:700;color:#c0161a;font-family:monospace;">$${fmt(saldoPend)}</div></div>`:
        '<div style="align-self:center;background:#eaf4ed;border:1.5px solid #3aaa6a;color:#0d5c2a;padding:4px 14px;border-radius:3px;font-family:\'JetBrains Mono\',monospace;font-size:0.72rem;font-weight:700;">✅ LIQUIDADO</div>'}
      </div>
      <div style="height:6px;background:#e0ddd5;border-radius:4px;overflow:hidden;"><div style="height:100%;width:${pct}%;background:${pct>=100?'#2aaa6a':'#c8952a'};border-radius:4px;transition:width 0.4s;"></div></div>
      <div style="text-align:right;font-family:monospace;font-size:0.62rem;color:#9a8050;margin-top:3px;">${pct}% cobrado</div>
    </div>`:
    (recVinculados.length?`<div style="padding:8px 0;font-family:monospace;font-size:0.7rem;color:#555;">Total cobrado: <strong style="color:#0d5c2a;">$${fmt(totalCobrado)}</strong> · ${recVinculados.length} recibo${recVinculados.length>1?'s':''}</div>`:``);
  const html=`
  <div style="font-family:monospace;">
    <!-- Encabezado expediente -->
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:18px;">
      <div>
        <div style="font-size:0.6rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.12em;margin-bottom:4px;">Número de Expediente</div>
        <div style="font-family:monospace;font-size:1.5rem;font-weight:700;color:#1a1a1a;border:2px solid #1a1a1a;padding:4px 14px;display:inline-block;letter-spacing:0.05em;">${fmtCarpNumHTML(c.num)}</div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:0.6rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.12em;margin-bottom:6px;">Estatus</div>
        ${estatusStyle(c.estatus)}
        ${c.prioridad?`<div style="margin-top:4px;">${chip({URGENTE:'🔴 Urgente',BUEN_TIEMPO:'🟢 Buen Tiempo',REZAGADO:'🟡 Rezagado'}[c.prioridad]||c.prioridad,{URGENTE:'#fff0f0',BUEN_TIEMPO:'#eaf4ed',REZAGADO:'#fff8e8'}[c.prioridad]||'#f5f0e8',{URGENTE:'#8a1010',BUEN_TIEMPO:'#0d5c2a',REZAGADO:'#7a5010'}[c.prioridad]||'#5a4a20',{URGENTE:'#d05050',BUEN_TIEMPO:'#3aaa6a',REZAGADO:'#c8952a'}[c.prioridad]||'#c4b078')}</div>`:''}
      </div>
    </div>
    <!-- Separador -->
    <div style="border-top:1.5px solid #1a1a1a;margin-bottom:16px;"></div>
    <!-- Datos principales -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px 20px;margin-bottom:16px;">
      <div><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Nombre / Cliente</div>
        <div style="font-size:0.92rem;font-weight:600;color:#1a1a1a;">${esc(c.cliente||'—')}</div></div>
      <div><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Tipo de Trámite</div>
        <div style="font-size:0.88rem;color:#1a3a7a;font-weight:600;">${esc(tipoLabel)}</div></div>
      ${subtipoTexto?`<div style="grid-column:1/-1;"><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Subtipo / Detalle del Trámite</div>
        <div style="font-size:0.85rem;color:#333;font-style:italic;text-align:justify;">${esc(subtipoTexto)}</div></div>`:''}
      ${_carpObsArray(c).length?`<div style="grid-column:1/-1;background:#fffde8;border-left:3px solid #c8952a;padding:8px 12px;border-radius:0 4px 4px 0;"><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:4px;">Observaciones</div>
        <div style="font-size:0.82rem;color:#5a4a10;">${_carpObsHtmlEnum(c)}</div></div>`:''}
      ${c.ingreso?`<div><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Fecha de Ingreso</div>
        <div style="font-size:0.85rem;color:#333;">📅 ${esc(c.ingreso)}</div></div>`:''}
      ${c.celebEscritura?`<div><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Fecha Celebración Escritura</div>
        <div style="font-size:0.85rem;color:#333;">📅 ${esc(c.celebEscritura)}</div></div>`:''}
      ${c.reciboOficial?`<div><div style="font-size:0.58rem;color:#9a8050;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:2px;">Recibo Oficial Vinculado</div>
        <div style="font-size:0.85rem;color:#8c6518;font-weight:600;">🧾 ${esc(c.reciboOficial)}</div></div>`:''}
    </div>
    <!-- Separador -->
    <div style="border-top:1px solid #d0c8b0;margin-bottom:14px;"></div>
    <!-- Información financiera -->
    <div style="margin-bottom:14px;">
      <div style="font-size:0.62rem;color:#5a4a20;text-transform:uppercase;letter-spacing:0.12em;font-weight:700;margin-bottom:8px;">💰 Resumen Financiero</div>
      ${finSec||'<div style="color:#aaa;font-size:0.72rem;padding:4px 0;">Sin información financiera registrada</div>'}
    </div>
    <!-- Recibos -->
    <div style="border-top:1px solid #d0c8b0;margin-bottom:14px;padding-top:14px;">
      <div style="font-size:0.62rem;color:#5a4a20;text-transform:uppercase;letter-spacing:0.12em;font-weight:700;margin-bottom:8px;">🧾 Recibos Vinculados (${recVinculados.length})</div>
      ${recibosHtml}
    </div>
  </div>`;
  let modal=document.getElementById('mDetalleCarpeta');
  if(!modal){
    modal=document.createElement('div');
    modal.className='modal-ov';
    modal.id='mDetalleCarpeta';
    modal.innerHTML=`<div class="modal wide" style="max-width:680px;width:94vw;max-height:88vh;overflow-y:auto;box-sizing:border-box;margin:auto;">
      <div class="modal-hdr" style="background:linear-gradient(135deg,#fdfaf4,#f7f3e8);border-bottom:2px solid #d4b870;">
        <h3 id="mDetCarpTitulo" style="color:#8c6518;font-family:monospace;font-size:0.85rem;letter-spacing:0.1em;text-transform:uppercase;">Expediente</h3>
        <div style="display:flex;gap:8px;align-items:center;">
          <button id="mDetCarpEditBtn" style="background:rgba(200,149,42,0.12);border:1.5px solid #d4b870;color:#8c6518;border-radius:8px;padding:5px 14px;font-family:monospace;font-size:0.7rem;font-weight:700;cursor:pointer;letter-spacing:0.05em;transition:background 0.15s;" onmouseover="this.style.background='rgba(200,149,42,0.22)'" onmouseout="this.style.background='rgba(200,149,42,0.12)'">✏️ Editar</button>
          <button class="modal-x" style="color:#8c6518;" onclick="cerrar('mDetalleCarpeta')">✕</button>
        </div>
      </div>
      <div class="modal-body" id="mDetCarpBody" style="padding:20px 24px;background:#faf8f4;"></div>
    </div>`;
    document.body.appendChild(modal);
  }
  const _carpIdx = idx;
  document.getElementById('mDetCarpTitulo').textContent='Expediente · '+(c.num||'');
  document.getElementById('mDetCarpBody').innerHTML=html;
  document.getElementById('mDetCarpEditBtn').onclick=function(){cerrar('mDetalleCarpeta');setTimeout(()=>abrirCarpeta(_carpIdx),100);};
  modal.classList.add('show');
}
// Formatea el número de carpeta para mostrarlo como HTML: el prefijo "CARP.-"
// en el mismo tono del texto circundante y el número en negro, negrita y
// ligeramente más grande, para identificarlo más rápido de un vistazo.
function fmtCarpNumHTML(num){
  const n = num || '—';
  const m = /^(CARP\.-\s*|ARCH-0*)(\d+)$/.exec(n);
  if(!m) return esc(n);
  const prefijo = m[1].indexOf('CARP.-')===0 ? 'CARP.- ' : 'ARCH-';
  return esc(prefijo)+'<b style="color:#000;font-weight:700;font-size:1.12em;">'+esc(m[2])+'</b>';
}
function renderCarp(){
  const q=($('carpQ')?.value||'').toLowerCase();
  // "Archivado" y "Cancelado" tienen cada uno su propia tarjeta/filtro,
  // separados de "Concluidas" (antes CANCELADO se contaba dentro de
  // Concluidas aunque la tabla mostrara una etiqueta distinta — confundía
  // porque el número no cuadraba).
  const EST_CONCLUIDO=['CONCLUIDO','CONCLUIDO Y ENTREGADA','CONCLUIDO Y ENTREGADO','CONCLUIDO Y ENTRAGADO'];
  const EST_ARCHIVADO=['ARCHIVADO'];
  const EST_CANCELADO=['CANCELADO'];
  // Mejora 5: actualizar contadores arriba (siempre con TODAS las carpetas, sin filtro)
  const todas = D.carpetas || [];
  let cntActiva = 0, cntConcluida = 0, cntArchivada = 0, cntCancelada = 0;
  todas.forEach(c => {
    const est = (c.estatus||'').toUpperCase().trim();
    const esConcluida = EST_CONCLUIDO.some(x => est.startsWith(x));
    const esArchivada = !esConcluida && EST_ARCHIVADO.some(x => est.startsWith(x));
    const esCancelada = !esConcluida && !esArchivada && EST_CANCELADO.some(x => est.startsWith(x));
    if (esConcluida) {
      cntConcluida++;
    } else if (esArchivada) {
      cntArchivada++;
    } else if (esCancelada) {
      cntCancelada++;
    } else {
      cntActiva++;
    }
  });
  const setStat = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
  setStat('carpStTot', todas.length);
  setStat('carpStAct', cntActiva);
  setStat('carpStCon', cntConcluida);
  setStat('carpStArch', cntArchivada);
  setStat('carpStCanc', cntCancelada);
  let l=D.carpetas.filter(c=>{
    const est=(c.estatus||'').toUpperCase().trim();
    const esConcluida=EST_CONCLUIDO.some(x=>est.startsWith(x));
    const esArchivada=!esConcluida&&EST_ARCHIVADO.some(x=>est.startsWith(x));
    const esCancelada=!esConcluida&&!esArchivada&&EST_CANCELADO.some(x=>est.startsWith(x));
    if(filtroCT==='activa')return !esConcluida&&!esArchivada&&!esCancelada;
    if(filtroCT==='entregada')return esConcluida;
    if(filtroCT==='archivada')return esArchivada;
    if(filtroCT==='cancelada')return esCancelada;
    return true;
  }).filter(c=>!q||_carpTextoBusqueda(c).includes(q));
  const el=$('listaCarp');
  if(!l.length){el.innerHTML='<div style="color:var(--muted);padding:24px;font-size:0.76rem;">Sin carpetas en este filtro.</div>';return;}
  function estatusCell(est){
    const e=(est||'').toUpperCase();
    // Paleta login: dorado/ámbar base, verde para concluido, rojo para cancelado
    let bg='rgba(200,149,42,0.12)',col='#8c6518',border='rgba(200,149,42,0.45)';
    if(e.includes('ARCHIVADO')){bg='rgba(200,149,42,0.08)';col='#7a6030';border='rgba(200,149,42,0.3)';}
    else if(e.includes('CONCLUIDO')||e.includes('ENTREGAD')){bg='rgba(26,122,58,0.1)';col='#0f5228';border='rgba(26,122,58,0.35)';}
    else if(e.includes('CANCELADO')){bg='rgba(192,22,26,0.1)';col='#8a1010';border='rgba(192,22,26,0.3)';}
    else if(e.includes('TRÁMITE')||e.includes('TRAMITE')||e.includes('PROCESO')||e==='ACTIVO'){bg='rgba(26,74,138,0.1)';col='#1a3a7a';border='rgba(26,74,138,0.3)';}
    return `<span style="display:inline-block;padding:3px 11px;border-radius:20px;font-family:monospace;font-size:0.6rem;font-weight:700;background:${bg};color:${col};border:1.5px solid ${border};letter-spacing:0.05em;white-space:nowrap;text-transform:uppercase;">${esc(est||'—')}</span>`;
  }
  const thStyle=`padding:11px 13px;text-align:left;font-family:monospace;font-size:0.58rem;font-weight:700;color:#8c6518;letter-spacing:0.14em;text-transform:uppercase;white-space:nowrap;border-bottom:2px solid #d4b870;background:linear-gradient(135deg,#fdf8ee,#f5edcc);`;
  el.innerHTML=`
    <style>
      .carp-tr { transition: background 0.22s, box-shadow 0.22s; }
      .carp-tr:hover { background: #FBF5E2 !important; box-shadow: 0 0 0 1.5px #C8AA60; }
      .carp-tr:hover td:first-child { border-radius: 6px 0 0 6px; }
      .carp-tr:hover td:last-child  { border-radius: 0 6px 6px 0; }
      .carp-tr:hover .carp-num-badge { border-color: #C8AA60; }
      .carp-action-btn { background:none;border:1.5px solid rgba(200,149,42,0.3);color:#b07820;border-radius:6px;width:28px;height:28px;cursor:pointer;font-size:0.8rem;display:inline-flex;align-items:center;justify-content:center;transition:all 0.15s;margin:0 1px; }
      .carp-action-btn:hover { background:rgba(200,149,42,0.15);border-color:#c8952a;transform:translateY(-1px);box-shadow:0 2px 8px rgba(200,149,42,0.2); }
    </style>
    <div style="overflow-x:auto;border:2px solid #d4b870;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px rgba(200,149,42,0.12);">
    <table style="width:100%;border-collapse:collapse;font-family:sans-serif;">
      <thead>
        <tr>
          <th style="${thStyle}white-space:nowrap;padding-left:16px;">EXP.</th>
          <th style="${thStyle}">NOMBRE</th>
          <th style="${thStyle}white-space:nowrap;">TIPO DE TRÁMITE</th>
          <th style="${thStyle}text-align:center;">ESTATUS</th>
          <th style="${thStyle}text-align:center;padding-right:14px;"></th>
        </tr>
      </thead>
      <tbody>
        ${l.map((c,rowI)=>{
          const idx=D.carpetas.indexOf(c);
          const tipoLabel={juicio:'JUICIO',escritura:'ESCRITURA',registro_civil:'REG. CIVIL',documentos:'DOCUMENTOS'}[c.tipoTramite]||(c.tipoTramite?c.tipoTramite.toUpperCase():'—');
          let subTipo='';
          if(c.tipoTramite==='juicio'&&c.juicioDesc) subTipo=c.juicioDesc;
          else if(c.tipoTramite==='escritura'&&c.escTipo) subTipo=c.escTipo;
          else if(c.tipoTramite==='registro_civil'&&c.regCivilTipo) subTipo={registro_extemporaneo:'Reg. Extemporáneo',rectificacion_nombre:'Rectif. Nombre',aclaracion_nombre:'Aclar. Nombre'}[c.regCivilTipo]||c.regCivilTipo;
          else if(c.tipoTramite==='documentos'&&c.docDesc) subTipo=c.docDesc;
          const tipoTexto=subTipo?tipoLabel+' — '+subTipo:tipoLabel;
          const rowBg=rowI%2===0?'#fdfaf4':'#faf5e8';
          const tdStyle=`padding:10px 13px;font-size:0.76rem;color:#2a1a06;border-bottom:1px solid rgba(212,184,112,0.25);vertical-align:middle;`;
          return `<tr class="carp-tr" onclick="abrirDetallesCarpeta(${idx})" style="background:${rowBg};cursor:pointer;">
            <td style="${tdStyle}padding-left:16px;">
              <span class="carp-num-badge" style="border:1.5px solid #d4b870;padding:3px 10px;font-family:monospace;font-size:0.68rem;font-weight:700;color:#8c6518;white-space:nowrap;border-radius:6px;background:#fdfaf4;transition:all 0.15s;display:inline-block;">${fmtCarpNumHTML(c.num)}</span>
            </td>
            <td style="${tdStyle}font-weight:600;white-space:nowrap;color:#1a0f02;">${esc(c.cliente||'—')}</td>
            <td style="${tdStyle}font-family:monospace;font-size:0.67rem;color:#6a4a10;white-space:nowrap;">${esc(tipoTexto)}</td>
            <td style="${tdStyle}text-align:center;">${estatusCell(c.estatus)}</td>
            <td style="${tdStyle}text-align:center;white-space:nowrap;padding-right:14px;" onclick="event.stopPropagation()">
              <button onclick="abrirDetallesCarpeta(${idx})" title="Detalles: qué contiene esta carpeta" class="carp-action-btn" style="width:auto;padding:0 10px;font-size:0.62rem;font-family:monospace;font-weight:700;letter-spacing:0.02em;">📋 Detalles</button>
              <button onclick="abrirCarpeta(${idx})" title="Editar" class="carp-action-btn">✏️</button>
              <button onclick="abrirMenuCarpeta(event,${idx})" title="Más opciones" class="carp-action-btn">☰</button>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
    </div>`;
}
// Abre el detalle del expediente y lanza el diálogo de impresión del
// navegador sobre esa misma vista — antes este botón llamaba a una función
// que no existía y no hacía nada al hacer clic.
function imprimirCarpeta(idx){
  const c=D.carpetas[idx];
  if(!c){ if(typeof toast==='function') toast('Carpeta no encontrada','err'); return; }
  abrirDetallesCarpeta(idx);
  setTimeout(()=>{ window.print(); }, 300);
}
function abrirMenuCarpeta(event,idx){
  event.stopPropagation();
  // Eliminar menú previo
  const prev=document.getElementById('_carpMenu');
  if(prev){prev.remove();if(prev._idx===idx)return;}
  const c=D.carpetas[idx];if(!c)return;
  const menu=document.createElement('div');
  menu._idx=idx;
  menu.id='_carpMenu';
  menu.style.cssText='position:fixed;z-index:9999;background:#fdfaf4;border:1.5px solid #d4b870;border-radius:10px;box-shadow:0 8px 32px rgba(140,101,24,0.18);min-width:180px;overflow:hidden;font-family:\'Outfit\',sans-serif;';
  const items=[
    {ico:'👁',lbl:'Ver detalle',fn:`abrirDetallesCarpeta(${idx})`},
    {ico:'✏️',lbl:'Editar carpeta',fn:`abrirCarpeta(${idx})`},
    {ico:'🖨️',lbl:'Imprimir expediente',fn:`imprimirCarpeta(${idx})`},
    {sep:true},
    {ico:'🗑️',lbl:'Eliminar',fn:`abrirCarpeta(${idx});setTimeout(()=>document.getElementById('kBtnElim')&&document.getElementById('kBtnElim').click(),200)`,danger:true},
  ];
  menu.innerHTML=items.map(it=>it.sep?`<div style="height:1px;background:#ecdfa8;margin:2px 0;"></div>`:
    `<button onclick="${it.fn};document.getElementById('_carpMenu')&&document.getElementById('_carpMenu').remove();" style="width:100%;background:none;border:none;padding:9px 14px;text-align:left;cursor:pointer;font-family:sans-serif;font-size:0.8rem;color:${it.danger?'#c0161a':'#1a1008'};display:flex;align-items:center;gap:9px;transition:background 0.12s;" onmouseover="this.style.background='rgba(200,149,42,0.1)'" onmouseout="this.style.background='none'">
      <span style="font-size:0.85rem;">${it.ico}</span>${it.lbl}</button>`).join('');
  document.body.appendChild(menu);
  // Posicionar
  const rect=event.target.getBoundingClientRect();
  let left=rect.right-menu.offsetWidth;
  let top=rect.bottom+4;
  if(left<8)left=8;
  if(top+200>window.innerHeight)top=rect.top-200;
  menu.style.left=left+'px';menu.style.top=top+'px';
  setTimeout(()=>document.addEventListener('click',function h(){menu.remove();document.removeEventListener('click',h);},{once:true}),10);
}
function kActualizarSubtipo(){
  const t=$('kTipoTramite').value;
  ['juicio','escritura','registro_civil','documentos'].forEach(x=>{
    const el=document.getElementById('kSub-'+x);
    if(el) el.style.display=(x===t)?'block':'none';
  });
}
// ── Observaciones / Notas internas de Carpetas — lista numerada ────────────
// Antes era un solo cuadro de texto libre. Ahora la nota #1 siempre está
// visible por defecto y "＋" agrega notas adicionales numeradas. Se guarda
// como c.obsLista (array); c.obs (texto legado de carpetas viejas) se
// migra automáticamente a la nota #1 la primera vez que se abre para editar.
// La fecha de cada observación se registra sola (fecha en que se agregó la
// nota) — nadie la escribe a mano, así que nunca se puede editar mal.
function _fechaHoyCorta(){
  const h = new Date();
  return String(h.getDate()).padStart(2,'0')+'/'+String(h.getMonth()+1).padStart(2,'0')+'/'+h.getFullYear();
}
function _fechaCorta(iso){
  if(!iso) return '';
  const d = new Date(iso);
  if(isNaN(d.getTime())) return '';
  return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear();
}
let _kObsState = [{ texto:'', fecha:'' }];
function _kObsRender(){
  const cont = document.getElementById('kObsLista');
  if(!cont) return;
  if(!_kObsState.length) _kObsState = [{ texto:'', fecha:'' }];
  cont.innerHTML = _kObsState.map((item, i) => {
    const puedeQuitar = i > 0;
    const txt = (item && item.texto) || '';
    const fecha = (item && item.fecha) || '';
    return '<div style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;">'
      +   '<div style="flex-shrink:0;color:#0e6a7c;font-family:monospace;font-size:0.8rem;font-weight:700;margin-top:9px;">'+(i+1)+'.</div>'
      +   '<div style="flex:1;min-width:0;">'
      +     '<textarea rows="1" data-kobs-i="'+i+'" oninput="_kObsActualizar('+i+',this.value);_kObsAutoGrow(this)" placeholder="'+(i===0?'Nota principal para uso interno del despacho...':'Otra observación...')+'" style="width:100%;border:2px solid #d4b870;border-radius:10px;padding:8px 10px;font-family:sans-serif;font-size:0.85rem;color:#1a1008;background:#fff;outline:none;transition:border-color 0.2s;resize:none;overflow:hidden;box-sizing:border-box;text-align:justify;" onfocus="this.style.borderColor=&#39;#c8952a&#39;" onblur="this.style.borderColor=&#39;#d4b870&#39;">'+txt.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</textarea>'
      +     (fecha ? '<div style="font-size:0.6rem;color:#0e6a7c;margin-top:3px;font-family:monospace;font-weight:600;">📅 Registrada el '+fecha+'</div>' : '')
      +   '</div>'
      +   (puedeQuitar ? '<button type="button" onclick="_kObsQuitar('+i+')" title="Quitar esta observación" style="flex-shrink:0;margin-top:6px;width:24px;height:24px;border-radius:50%;border:1px solid #e0b0b0;background:#fdf0f0;color:#a32d2d;cursor:pointer;font-size:0.72rem;line-height:1;">✕</button>' : '<div style="width:24px;flex-shrink:0;"></div>')
      + '</div>';
  }).join('');
  // Cada textarea crece con su contenido — nunca hay que arrastrar ni
  // hacer scroll para ver el texto completo de una observación.
  cont.querySelectorAll('textarea[data-kobs-i]').forEach(_kObsAutoGrow);
}
function _kObsAutoGrow(el){
  if(!el) return;
  el.style.height = 'auto';
  el.style.height = el.scrollHeight + 'px';
}
function _kObsActualizar(i, val){
  // La fecha NO se fija aquí (mientras se escribe) — se registra sola hasta
  // que la nota realmente se guarda (sube al sistema), en guardarCarpeta().
  if(!_kObsState[i]) _kObsState[i] = { texto:'', fecha:'' };
  _kObsState[i].texto = val;
}
function _kObsAgregar(){
  _kObsState.push({ texto:'', fecha:'' });
  _kObsRender();
  const cont = document.getElementById('kObsLista');
  const nuevas = cont ? cont.querySelectorAll('textarea') : [];
  const last = nuevas[nuevas.length-1];
  if(last) last.focus();
}
function _kObsQuitar(i){
  if(i <= 0) return;
  _kObsState.splice(i,1);
  _kObsRender();
}

function abrirCarpeta(idx){
  // Por defecto, esta apertura NO viene del flujo "crear carpeta al vuelo desde
  // Escritura" — ese flujo activa la bandera explícitamente justo después de
  // esta llamada. Resetearla aquí evita que quede "pegada" en true si el
  // usuario cancela ese flujo y luego crea/edita una carpeta normal.
  window._crearCarpetaOrigenEscritura = false;
  eiK=idx>=0?idx:-1;const c=idx>=0?D.carpetas[idx]:{};
  eiKNum=(idx>=0 && c && c.num)?c.num:null;
  // Mostrar el modal ANTES de calcular el alto automático de los textarea de
  // Observaciones (_kObsRender más abajo): con display:none, scrollHeight da
  // 0 y el auto-grow colapsaba cada textarea a 0px, dejando el texto (y el
  // placeholder) invisible aunque sí estuviera cargado correctamente.
  $('mCarpeta').classList.add('show');
  // Mejora: si es carpeta nueva, sugerir el siguiente número
  if (idx < 0 || idx === undefined) {
    const sugerencia = sugerirNumeroCarpeta();
    $('kNum').value = sugerencia ? String(sugerencia) : '';
  } else {
    // Al editar, mostrar solo el número sin el prefijo (CARP.- o, en carpetas
    // antiguas, ARCH-) y sin ceros a la izquierda
    const numLimpio = (c.num||'').replace('CARP.-','').replace('ARCH-','').trim().replace(/^0+(?=\d)/,'') || '';
    $('kNum').value = numLimpio;
  }
  $('kCliente').value=c.cliente||'';
  // Nueva carpeta: sugerir "ACTIVO" por defecto (queda como "activa" en los
  // contadores y filtros) en vez de dejarlo en blanco — antes una carpeta
  // recién creada sin estatus contaba como activa en la tarjeta de arriba
  // pero no aparecía al hacer clic en la pestaña "Activas" (inconsistencia).
  (function(){
    var _selEst = $('kEstatus');
    var _valEst = c.estatus||(idx<0||idx===undefined?'ACTIVO':'');
    _selEst.value = _valEst;
    // Salvaguarda: si el valor guardado no coincide con ninguna de las 4
    // opciones (ej. texto libre de antes de que este campo fuera un select),
    // no lo borremos en silencio — se agrega como opción temporal para que
    // se siga viendo y no se pierda si el usuario guarda sin tocarlo.
    if (_valEst && _selEst.value !== _valEst) {
      var _yaExiste = Array.prototype.some.call(_selEst.options, function(o){ return o.value===_valEst; });
      if (!_yaExiste) {
        var _optExtra = document.createElement('option');
        _optExtra.value = _valEst; _optExtra.textContent = _valEst + ' (texto libre anterior)';
        _selEst.insertBefore(_optExtra, _selEst.firstChild);
      }
      _selEst.value = _valEst;
    }
  })();
  // Para nueva carpeta, prellenar con fecha actual formateada (DD/MM/AAAA)
  if(idx<0 || idx===undefined){
    const hoy=new Date();
    const dd=String(hoy.getDate()).padStart(2,'0');
    const mm=String(hoy.getMonth()+1).padStart(2,'0');
    const aaaa=hoy.getFullYear();
    $('kIngreso').value=dd+'/'+mm+'/'+aaaa;
  } else {
    // Si la fecha almacenada tiene formato ISO, convertirla a DD/MM/AAAA
    let ingVal=c.ingreso||'';
    if(ingVal && /^\d{4}-\d{2}-\d{2}/.test(ingVal)){
      const parts=ingVal.substring(0,10).split('-');
      ingVal=parts[2]+'/'+parts[1]+'/'+parts[0];
    }
    $('kIngreso').value=ingVal;
  }
  $('kCelebEscritura').value=c.celebEscritura||'';
  // Observaciones: usar la lista guardada; si la carpeta es vieja y solo
  // tiene el texto legado en c.obs (o una lista sin fechas de una versión
  // anterior), migrarlo automáticamente conservando la fecha que se pueda
  // inferir (fecha de creación de la carpeta) o dejándola en blanco.
  let _kObsBase = [];
  if(Array.isArray(c.obsLista) && c.obsLista.length){
    _kObsBase = c.obsLista.map(item => (item && typeof item === 'object')
      ? { texto:String(item.texto||''), fecha:String(item.fecha||'') || _fechaCorta(c.fechaCreacion) }
      : { texto:String(item||''), fecha:_fechaCorta(c.fechaCreacion) });
  } else if(c.obs && String(c.obs).trim()!==''){
    _kObsBase = [{ texto:String(c.obs), fecha:_fechaCorta(c.fechaCreacion) }];
  }
  // La antigua "Descripción/Asunto" (campo suelto de una versión anterior)
  // pasa a ser la nota #1 — adelante de las demás — para que todo viva en
  // un solo lugar. En cuanto se guarde así, guardarCarpeta() limpia
  // c.descripcion para que no se duplique la próxima vez que se edite.
  if(c.descripcion && String(c.descripcion).trim()!==''){
    _kObsBase = [{ texto:String(c.descripcion), fecha:_fechaCorta(c.fechaCreacion) }, ..._kObsBase];
  }
  // Carpeta nueva o sin observaciones aún: deja una nota #1 vacía lista para
  // escribir; su fecha se registra sola hasta que se guarde de verdad
  // (guardarCarpeta), no al abrir el formulario.
  _kObsState = _kObsBase.length ? _kObsBase : [{ texto:'', fecha:'' }];
  _kObsRender();
  $('kReciboOficial').value=c.reciboOficial||'';
  // Tipo de trámite
  $('kTipoTramite').value=c.tipoTramite||'';
  kActualizarSubtipo();
  // Subtipos
  $('kJuicioDesc').value=c.juicioDesc||'';
  $('kEscNotario').value=c.escNotario||'';
  $('kEscVolumen').value=c.escVolumen||'';
  $('kEscInstrumento').value=c.escInstrumento||'';
  $('kEscTipo').value=c.escTipo||'';
  $('kRegCivilTipo').value=c.regCivilTipo||'';
  $('kDocDesc').value=c.docDesc||'';
  $('mKTitulo').textContent=idx>=0?'Editar Carpeta':'Nueva Carpeta';
  $('kNum').readOnly=(idx>=0);
  $('kNum').style.opacity=(idx>=0)?'0.6':'1';
  $('kNumInfo').style.display=(idx>=0)?'block':'none';
  $('kBtnElim').style.display=(idx>=0)?'flex':'none';
}
async function guardarCarpeta(){
  const numRaw=$('kNum').value.trim();
  const cliente=$('kCliente').value.trim();
  if(!numRaw){
    toast('El número de carpeta es obligatorio','err');
    const el=$('kNum'); if(el){el.style.borderColor='var(--rojo)';el.scrollIntoView({behavior:'smooth',block:'center'});el.focus();}
    return;
  }
  if(!cliente){
    toast('El cliente es obligatorio','err');
    const el=$('kCliente'); if(el){el.style.borderColor='var(--rojo)';el.scrollIntoView({behavior:'smooth',block:'center'});el.focus();}
    return;
  }
  // Formato CARP.- 1 (sin ceros a la izquierda, del 1 al infinito)
  const numFormateado = 'CARP.- ' + (parseInt(numRaw)||1);
  // Re-ubicar la carpeta por su número permanente (no por eiK a ciegas): si
  // D.carpetas se reordenó o se reconstruyó (p. ej. sincronización con
  // Supabase) mientras el modal estaba abierto, eiK puede apuntar ahora a
  // OTRA carpeta distinta — guardar ahí encima borraría datos ajenos.
  if(eiK>=0){
    const idxLive = eiKNum!=null ? D.carpetas.findIndex(x=>x.num===eiKNum) : -1;
    if(idxLive<0){
      toast('⚠ No se encontró la carpeta a guardar — vuelve a abrirla e inténtalo de nuevo','err');
      return;
    }
    eiK = idxLive;
    // Guardrail contra pérdida de datos: si el formulario guardaría las
    // Observaciones vacías pero la carpeta YA tenía texto real ahí, es más
    // probable que sea un error (el formulario no cargó bien) que una
    // intención real de borrarlo todo — se pide confirmación explícita.
    const _obsNuevoVacio = !_kObsState.some(o => String((o&&o.texto)||'').trim()!=='');
    const _obsViejo = D.carpetas[eiK] || {};
    const _teniaObsReal =
      (Array.isArray(_obsViejo.obsLista) && _obsViejo.obsLista.some(o => String((o&&typeof o==='object')?o.texto:o||'').trim()!=='')) ||
      (_obsViejo.obs && String(_obsViejo.obs).trim()!=='') ||
      (_obsViejo.descripcion && String(_obsViejo.descripcion).trim()!=='');
    if(_obsNuevoVacio && _teniaObsReal){
      const ok = await confirmarBonito({
        titulo: 'Observaciones vacías',
        mensaje: 'Esta carpeta ya tenía texto en Observaciones/Notas internas y así se guardaría vacío.\n\n¿Seguro que quieres borrar ese contenido?',
        btnSi: 'Sí, guardar vacío',
        btnNo: 'Cancelar',
        peligro: true
      });
      if(!ok) return;
    }
  }
  if(eiK<0){
    const existe=D.carpetas.find(x=>x.num===numFormateado);
    if(existe){toast('⚠ Ya existe la carpeta '+numFormateado,'err');return;}
  }
  const tipoTramite=$('kTipoTramite').value;
  // Descripción/Asunto, Total Pactado, Estado del Archivo y Prioridad se
  // quitaron del formulario (campo Estatus/Trámite ya cubre lo mismo que
  // Estado del Archivo). Para no borrar en silencio esos datos en carpetas
  // ya existentes que sí los tenían, se conservan tal cual venían al editar;
  // una carpeta nueva simplemente no los tiene.
  const c={
    num: eiK>=0?D.carpetas[eiK].num:numFormateado,
    cliente,
    // La antigua "Descripción/Asunto" ya se fusionó como nota #1 dentro de
    // obsLista (ver migración en abrirCarpeta) — se limpia aquí para que no
    // se vuelva a duplicar la próxima vez que se abra esta carpeta.
    descripcion: '',
    estatus:$('kEstatus').value.trim(), ingreso:$('kIngreso').value.trim(),
    celebEscritura:($('kCelebEscritura')||{value:''}).value.trim(),
    obsLista: _kObsState
      .map(o => ({ texto:String((o&&o.texto)||'').trim(), fecha:(o&&o.fecha)||_fechaHoyCorta() }))
      .filter(o => o.texto!==''),
    obs: _kObsState.map(o=>String((o&&o.texto)||'').trim()).filter(t=>t!=='').join('\n\n'),
    reciboOficial:($('kReciboOficial')||{value:''}).value.trim(),
    estadoArchivo: eiK>=0?(D.carpetas[eiK].estadoArchivo||''):'',
    prioridad: eiK>=0?(D.carpetas[eiK].prioridad||''):'',
    totalPactado: eiK>=0?(D.carpetas[eiK].totalPactado||0):0,
    tipoTramite,
    // fechaCreacion se conserva de la carpeta original al editar (o se rellena
    // ahora si nunca se registró); fechaModificacion sí se actualiza en cada
    // guardado — juntas alimentan el contador "Sin actividad >30 días".
    fechaCreacion: (eiK>=0 && D.carpetas[eiK].fechaCreacion) ? D.carpetas[eiK].fechaCreacion : new Date().toISOString(),
    fechaModificacion: new Date().toISOString(),
    juicioDesc: tipoTramite==='juicio'?$('kJuicioDesc').value.trim():'',
    escNotario: tipoTramite==='escritura'?$('kEscNotario').value.trim():'',
    escVolumen: tipoTramite==='escritura'?$('kEscVolumen').value.trim():'',
    escInstrumento: tipoTramite==='escritura'?$('kEscInstrumento').value.trim():'',
    escTipo: tipoTramite==='escritura'?$('kEscTipo').value.trim():'',
    regCivilTipo: tipoTramite==='registro_civil'?$('kRegCivilTipo').value:'',
    docDesc: tipoTramite==='documentos'?$('kDocDesc').value.trim():''
  };
  try {
    if(eiK>=0) D.carpetas[eiK]=c; else D.carpetas.unshift(c);
  } catch(e) {
    console.error('[guardarCarpeta] Error al modificar D.carpetas:', e);
    toast('Error al guardar carpeta: '+e.message,'err');
    return;
  }
  // 1. Cerrar modal inmediatamente — respuesta visual instantánea
  try { cerrar('mCarpeta'); } catch(e){ console.warn('[guardarCarpeta] cerrar:', e); }
  // 2. Re-renderizar la lista al instante
  try { renderCarp(); } catch(e){ console.warn('[guardarCarpeta] renderCarp:', e); }
  // 3. Actualizar badges si existen
  try { if(typeof badges==='function') badges(); } catch(e){ registrarError('catch vacio', e); }
  // 4. Toast de confirmación
  try { toast('Carpeta '+c.num+' guardada ✓'); } catch(e){ registrarError('catch vacio', e); }
  // 4.5 Si esta carpeta se creó desde "＋ Crear carpeta nueva" dentro del modal
  // de Escritura, vincular automáticamente el número recién creado de vuelta
  // al campo de la escritura (que sigue abierta detrás de este modal).
  if (eiK < 0 && window._crearCarpetaOrigenEscritura) {
    window._crearCarpetaOrigenEscritura = false;
    try {
      const inpEsc = document.getElementById('eNum');
      if (inpEsc) { inpEsc.value = c.num; inpEsc.style.borderColor = ''; }
      const listaComp = document.getElementById('eCompradores-list');
      if (listaComp && !listaComp.children.length && typeof escAgregarPersona === 'function') {
        escAgregarPersona('comprador', { nombre: c.cliente });
      }
      if (typeof toast === 'function') toast('📁 Carpeta ' + c.num + ' creada y vinculada a la escritura');
    } catch(e){ console.error('[guardarCarpeta] vínculo con escritura:', e); }
  }
  // 5. Persistir en Supabase de forma asíncrona (no bloquea la UI)
  try {
    save();
  } catch(e){ console.warn('[guardarCarpeta] save:', e); }
  try {
    saveCarpetas();
  } catch(e){ console.warn('[guardarCarpeta] saveCarpetas:', e); }
}
async function eliminarCarpeta(){
  if(eiK<0)return;
  // Re-ubicar por número permanente antes de borrar — mismo motivo que en
  // guardarCarpeta(): eiK puede haber quedado apuntando a otra carpeta si
  // D.carpetas se reconstruyó en segundo plano mientras el modal estaba abierto.
  const idxLive = eiKNum!=null ? D.carpetas.findIndex(x=>x.num===eiKNum) : -1;
  if(idxLive<0){
    toast('⚠ No se encontró la carpeta a eliminar — vuelve a abrirla e inténtalo de nuevo','err');
    return;
  }
  const c=D.carpetas[idxLive];
  const ok = await confirmarBonito({
    titulo: 'Eliminar carpeta',
    mensaje: '¿Eliminar carpeta '+c.num+' — '+c.cliente+'?\n\nEsta acción no se puede deshacer.',
    btnSi: 'Sí, eliminar',
    btnNo: 'Cancelar',
    peligro: true
  });
  if(!ok) return;
  D.carpetas.splice(idxLive,1);
  save();saveCarpetas();renderCarp();cerrar('mCarpeta');toast('Carpeta eliminada — sincronizando...');
}
