// RESUMEN FINANCIERO — helper reutilizable para Juicios y Pendientes
// ══════════════════════════════════════════════════════════════════
function _finResumen(nombreCliente, folioRecibo){
  const allRecibos = ((typeof appData!=='undefined' ? appData.recibos : null) || REC.recibos || []);
  // ── ARREGLO: solo vincular por folio explícito ──
  // El matching por nombre era peligroso: encontraba recibos de OTRAS personas
  // que casualmente comparten el primer nombre. Ahora solo se muestra el recibo
  // si el juicio tiene folioRecibo asignado expresamente por el usuario.
  // Las cantidades se actualizan automáticamente al leer desde appData.recibos
  // (que es la fuente viva, sincronizada con Drive).
  if (!folioRecibo) return '';
  const folioNum = parseInt(folioRecibo);
  if (isNaN(folioNum)) return '';
  const rec = allRecibos.find(r => r.folio === folioNum);
  if (!rec) {
    // Recibo vinculado pero ya no existe en el sistema (posiblemente eliminado)
    return `<div style="margin-top:7px;padding:5px 8px;background:rgba(192,22,26,0.06);border:1px solid rgba(192,22,26,0.18);border-radius:5px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
      <span style="font-family:monospace;font-size:0.58rem;color:#c0161a;">⚠ Recibo #${folioFormato(folioNum)} no encontrado</span>
    </div>`;
  }
  const recVinc = [rec];
  const totalCobrado  = recVinc.reduce((s,r)=>s+(parseFloat(r.anticipo)||0),0);
  const totalPendiente= recVinc.reduce((s,r)=>s+(parseFloat(r.saldoPendiente)||0),0);
  const liquidados    = recVinc.filter(r=>!(parseFloat(r.saldoPendiente)||0)).length;
  const estadoTxt   = totalPendiente > 0
    ? `<span style="color:#c0161a;font-weight:700;">$${fmt(totalPendiente)} pendiente</span>`
    : `<span style="color:var(--verde-d);font-weight:700;">✅ Liquidado</span>`;
  return `<div style="margin-top:7px;padding:5px 8px;background:rgba(26,122,58,0.04);border:1px solid rgba(26,122,58,0.12);border-radius:5px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
    <span style="font-family:monospace;font-size:0.58rem;color:var(--verde-d);">💰 $${fmt(totalCobrado)} cobrado</span>
    ${estadoTxt}
    <span style="font-family:monospace;font-size:0.58rem;color:var(--muted);">📄 1 recibo${liquidados===1?' · liquidado':''}</span>
    <span onclick="event.stopPropagation();abrirPreviaDesdeContab(${rec.folio})" style="font-family:monospace;font-size:0.56rem;color:var(--azul);cursor:pointer;text-decoration:underline;text-underline-offset:2px;">Ver recibo #${folioFormato(rec.folio, rec.anio_folio)}</span>
  </div>`;
}
function _verRecibosCliente(nombre){
  // Navegar a Contabilidad con el nombre pre-filtrado
  ir('contabilidad');
  setTimeout(()=>{
    const el = document.getElementById('cBuscar');
    if(el){ el.value = nombre; renderContab(); }
  }, 150);
}
// ═══ GESTIÓN DE RECIBO VINCULADO A UN JUICIO ═══
// Permite vincular, cambiar o desvincular el recibo de un juicio.
// Resuelve los 2 problemas reales:
//   1. Vincular el recibo correcto cuando hay coincidencias de nombre falsas
//   2. Las cantidades se leen dinámicamente desde appData.recibos, así que
//      cualquier actualización del recibo se refleja al instante en el juicio
let _juicioVincRecIdx = -1;
let _juicioVincBusqueda = '';
// ── Soporte de MÚLTIPLES folios vinculados por expediente (18/ago/2026) ──
// Antes un juicio solo podía tener UN recibo vinculado (j.folioRecibo). Ahora
// se guarda como arreglo (j.foliosRecibo). Se conserva j.folioRecibo = primer
// elemento del arreglo por compatibilidad con lecturas viejas (tag de la
// lista, _finResumen, etc.) que todavía leen el campo singular.
function _juFoliosRecibo(j){
  if (!j) return [];
  const arr = Array.isArray(j.foliosRecibo) ? j.foliosRecibo : (j.folioRecibo ? [j.folioRecibo] : []);
  return arr.map(f => parseInt(f)).filter(f => !isNaN(f));
}
function _juGuardarFoliosRecibo(j, arr){
  const limpio = Array.from(new Set((arr || []).map(f => parseInt(f)).filter(f => !isNaN(f))));
  j.foliosRecibo = limpio;
  j.folioRecibo  = limpio.length ? limpio[0] : null;
}
// Repinta el bloque "FOLIOS VINCULADOS" dentro del modal de vinculación, sin
// tocar el buscador (para poder seguir agregando varios sin que se resetee).
function _jvrRenderActual(j){
  const actualWrap = document.getElementById('jvr-actual-wrap');
  const actualInfo = document.getElementById('jvr-actual-info');
  const foliosVinc = _juFoliosRecibo(j);
  if (foliosVinc.length && actualWrap && actualInfo) {
    const recibos = (typeof appData !== 'undefined' ? appData.recibos : null) || [];
    actualInfo.innerHTML = foliosVinc.map((fol, i) => {
      const recActual = recibos.find(r => r.folio === fol);
      let linea;
      if (recActual) {
        const total = parseFloat(recActual.total) || 0;
        const ant = parseFloat(recActual.anticipo) || 0;
        const saldo = recActual.saldoPendiente !== undefined ? parseFloat(recActual.saldoPendiente) : Math.max(0, total - ant);
        const estadoTxt = recActual.cancelado ? '❌ Cancelado' : (saldo > 0 ? '⚠ Pendiente $' + fmt(saldo) : '✅ Liquidado');
        linea = '<strong>Folio #' + folioFormato(recActual.folio) + '</strong> — ' + esc(recActual.nombre || '—') +
          '<br><span style="font-size:0.7rem;color:var(--muted);">$' + fmt(total) + ' total · $' + fmt(ant) + ' cobrado · ' + estadoTxt + '</span>';
      } else {
        linea = '<span style="color:#c0161a;">⚠ Folio #' + folioFormato(fol) + ' no se encontró en el sistema</span>';
      }
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:6px 0;' + (i ? 'border-top:1px solid rgba(26,122,58,0.15);' : '') + '">' +
        '<div style="font-size:0.82rem;color:var(--ink);flex:1;">' + linea + '</div>' +
        '<button onclick="desvincularReciboDeJuicio(' + fol + ')" style="flex-shrink:0;background:rgba(192,22,26,0.1);border:1px solid rgba(192,22,26,0.3);color:#c0161a;border-radius:4px;padding:4px 9px;font-size:0.65rem;font-family:monospace;cursor:pointer;font-weight:700;">✕ Quitar</button>' +
        '</div>';
    }).join('');
    actualWrap.style.display = '';
  } else if (actualWrap) {
    actualWrap.style.display = 'none';
  }
}
function abrirGestionReciboJuicio(idx) {
  if (idx < 0 || !D.juicios[idx]) return;
  _juicioVincRecIdx = idx;
  _juicioVincBusqueda = '';
  let modal = document.getElementById('modal-juicio-recibo');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'modal-juicio-recibo';
    modal.className = 'modal-ov';
    modal.innerHTML = `<div class="modal" style="max-width:640px;width:95vw;max-height:92vh;display:flex;flex-direction:column;">
      <div class="modal-hdr">
        <h3 style="font-size:0.95rem;">🔗 Vincular Recibos al Juicio</h3>
        <button class="modal-x" onclick="cerrar('modal-juicio-recibo')">✕</button>
      </div>
      <div class="modal-body" style="padding:18px;">
        <div id="jvr-juicio-info" style="background:var(--surface2);padding:10px 14px;border-radius:6px;margin-bottom:14px;border-left:3px solid var(--gold);font-size:0.78rem;"></div>
        <div id="jvr-actual-wrap" style="display:none;margin-bottom:14px;padding:10px 14px;background:rgba(26,122,58,0.06);border:1px solid rgba(26,122,58,0.2);border-radius:6px;">
          <div style="font-family:monospace;font-size:0.6rem;color:var(--verde-d);letter-spacing:0.1em;margin-bottom:6px;">FOLIOS VINCULADOS A ESTE EXPEDIENTE</div>
          <div id="jvr-actual-info" style="display:flex;flex-direction:column;gap:2px;"></div>
        </div>
        <div class="field" style="margin-bottom:12px;">
          <label style="font-size:0.72rem;color:var(--muted);font-family:monospace;letter-spacing:0.05em;">🔍 Buscar recibo por folio o cliente</label>
          <input type="text" id="jvr-buscar" placeholder="Ej: 0106, García, Miguel..." oninput="filtrarRecibosParaJuicio()" style="width:100%;padding:8px 12px;border:1.5px solid var(--border-l);border-radius:5px;font-size:0.85rem;background:var(--surface);color:var(--ink);box-sizing:border-box;">
        </div>
        <div style="font-family:monospace;font-size:0.62rem;color:var(--muted);margin-bottom:8px;letter-spacing:0.05em;">RESULTADOS:</div>
        <div id="jvr-lista" style="max-height:340px;overflow-y:auto;border:1px solid var(--border-l);border-radius:6px;background:var(--surface);"></div>
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
          <button class="btn btn-ghost" onclick="cerrar('modal-juicio-recibo')">Cerrar</button>
        </div>
      </div>
    </div>`;
    document.body.appendChild(modal);
  }
  modal.classList.add('show');
  const j = D.juicios[idx];
  const infoEl = document.getElementById('jvr-juicio-info');
  if (infoEl) {
    infoEl.innerHTML = '<strong>' + esc(j.cliente) + '</strong>' +
      (j.expediente ? ' · Exp. ' + esc(j.expediente) : '') +
      '<br><span style="font-size:0.72rem;color:var(--muted);">' + esc(j.tipo || '') + '</span>';
  }
  // Mostrar todos los folios actualmente vinculados (puede haber más de uno)
  _jvrRenderActual(j);
  // Pre-llenar búsqueda con primer apellido o nombre del cliente para sugerir
  const buscarEl = document.getElementById('jvr-buscar');
  if (buscarEl) {
    // Sugerir el apellido del cliente (palabra más larga)
    const palabras = (j.cliente || '').split(/\s+/).filter(p => p.length > 2);
    const sugerencia = palabras.sort((a,b) => b.length - a.length)[0] || '';
    buscarEl.value = sugerencia;
    _juicioVincBusqueda = sugerencia.toLowerCase();
    setTimeout(() => { buscarEl.focus(); buscarEl.select(); }, 100);
  }
  filtrarRecibosParaJuicio();
}
function filtrarRecibosParaJuicio() {
  const lista = document.getElementById('jvr-lista');
  if (!lista) return;
  const inp = document.getElementById('jvr-buscar');
  const q = (inp ? inp.value : '').toLowerCase().trim();
  _juicioVincBusqueda = q;
  const recibos = (typeof appData !== 'undefined' ? appData.recibos : null) || [];
  if (!recibos.length) {
    lista.innerHTML = '<div style="padding:18px;text-align:center;color:var(--muted);font-size:0.78rem;">Sin recibos en el sistema. Conecta Drive primero.</div>';
    return;
  }
  // Filtrar
  let filtrados;
  if (!q) {
    // Sin búsqueda: mostrar los 30 más recientes
    filtrados = recibos.slice().sort((function(a,b){ var fa=(a.fecha||a.fecha_recibo||'')+'T'+(a.hora||'00:00'); var fb=(b.fecha||b.fecha_recibo||'')+'T'+(b.hora||'00:00'); if(fb!==fa) return fb.localeCompare(fa); if(a.folio!==b.folio) return (b.folio||0)-(a.folio||0); var la=(a.letra||'A'),lb=(b.letra||'A'); return la<lb?-1:la>lb?1:0; })).slice(0, 30);
  } else {
    filtrados = recibos.filter(r => {
      const folioStr = String(r.folio || '');
      const nombre = (r.nombre || '').toLowerCase();
      // Buscar por folio EXACTO o por nombre que contiene la búsqueda
      return folioStr === q || folioStr === folioFormato(parseInt(q)||0) || 
             nombre.includes(q);
    }).sort((function(a,b){ var fa=(a.fecha||a.fecha_recibo||'')+'T'+(a.hora||'00:00'); var fb=(b.fecha||b.fecha_recibo||'')+'T'+(b.hora||'00:00'); if(fb!==fa) return fb.localeCompare(fa); if(a.folio!==b.folio) return (b.folio||0)-(a.folio||0); var la=(a.letra||'A'),lb=(b.letra||'A'); return la<lb?-1:la>lb?1:0; })).slice(0, 50);
  }
  if (!filtrados.length) {
    lista.innerHTML = '<div style="padding:18px;text-align:center;color:var(--muted);font-size:0.78rem;">No se encontraron recibos con esa búsqueda.</div>';
    return;
  }
  // Folios actualmente vinculados para marcarlos como tal (puede ser más de uno)
  const j = D.juicios[_juicioVincRecIdx];
  const foliosActuales = j ? _juFoliosRecibo(j) : [];
  lista.innerHTML = filtrados.map(r => {
    const total = parseFloat(r.total) || 0;
    const ant = parseFloat(r.anticipo) || 0;
    const saldo = r.saldoPendiente !== undefined ? parseFloat(r.saldoPendiente) : Math.max(0, total - ant);
    const folioStr = folioFormato(r.folio, r.anio_folio);
    const esActual = foliosActuales.includes(r.folio);
    let estadoBadge;
    if (r.cancelado) estadoBadge = '<span style="background:rgba(192,22,26,0.1);color:#c0161a;padding:1px 6px;border-radius:3px;font-size:0.55rem;font-weight:700;">CANCELADO</span>';
    else if (saldo > 0) estadoBadge = '<span style="background:rgba(232,156,48,0.1);color:#9a6010;padding:1px 6px;border-radius:3px;font-size:0.55rem;font-weight:700;">PENDIENTE $' + fmt(saldo) + '</span>';
    else estadoBadge = '<span style="background:rgba(26,122,58,0.1);color:var(--verde-d);padding:1px 6px;border-radius:3px;font-size:0.55rem;font-weight:700;">LIQUIDADO</span>';
    return '<div onclick="vincularReciboAJuicio(' + r.folio + ')" style="padding:10px 14px;border-bottom:1px solid var(--border-l);cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:12px;transition:background 0.12s;' + 
      (esActual ? 'background:rgba(200,149,42,0.06);' : '') + '" ' +
      'onmouseover="this.style.background=\'rgba(200,149,42,0.1)\'" ' +
      'onmouseout="this.style.background=\'' + (esActual ? 'rgba(200,149,42,0.06)' : 'transparent') + '\'">' +
      '<div style="flex:1;min-width:0;">' +
      '<div style="font-family:\'JetBrains Mono\',monospace;font-size:0.74rem;font-weight:700;color:var(--gold-d);">#' + folioStr + (esActual ? ' <span style="font-size:0.55rem;color:var(--verde-d);background:rgba(26,122,58,0.1);padding:1px 5px;border-radius:3px;">YA VINCULADO</span>' : '') + '</div>' +
      '<div style="font-size:0.78rem;color:var(--ink);margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + esc(r.nombre || '—') + '</div>' +
      '<div style="font-family:\'JetBrains Mono\',monospace;font-size:0.62rem;color:var(--muted);margin-top:2px;">' + (r.fecha || '—') + ' · $' + fmt(total) + ' total · $' + fmt(ant) + ' cobrado</div>' +
      '</div>' +
      '<div style="text-align:right;">' + estadoBadge + '</div>' +
      '</div>';
  }).join('');
}
async function vincularReciboAJuicio(folio) {
  if (_juicioVincRecIdx < 0 || !D.juicios[_juicioVincRecIdx]) return;
  const j = D.juicios[_juicioVincRecIdx];
  const actuales = _juFoliosRecibo(j);
  if (actuales.includes(folio)) {
    toast('Ese folio ya está vinculado a este expediente', 'ok');
    return;
  }
  // Ya no se "cambia" un recibo por otro — se AGREGA, para poder tener varios
  // folios vinculados al mismo expediente (ej. anticipo y liquidación con
  // folios distintos). El modal se queda abierto para seguir agregando más.
  actuales.push(folio);
  _juGuardarFoliosRecibo(j, actuales);
  saveJuicios();
  _jvrRenderActual(j);
  filtrarRecibosParaJuicio();
  renderJuicios();
  try{ if (window._mexpIdxActual === _juicioVincRecIdx) _juRenderDatosDuros(j, _juicioVincRecIdx); }catch(e){}
  toast('✓ Recibo #' + folioFormato(folio) + ' vinculado al juicio', 'ok');
}
async function desvincularReciboDeJuicio(folio) {
  if (_juicioVincRecIdx < 0 || !D.juicios[_juicioVincRecIdx]) return;
  const j = D.juicios[_juicioVincRecIdx];
  const actuales = _juFoliosRecibo(j);
  if (!actuales.includes(folio)) return;
  const ok = await confirmarBonito({
    titulo: 'Desvincular recibo',
    mensaje: '¿Quitar la vinculación con el recibo #' + folioFormato(folio) + '?\n\nEl recibo NO se elimina, solo se desconecta del juicio.',
    btnSi: 'Sí, desvincular',
    btnNo: 'Cancelar'
  });
  if (!ok) return;
  _juGuardarFoliosRecibo(j, actuales.filter(f => f !== folio));
  saveJuicios();
  _jvrRenderActual(j);
  filtrarRecibosParaJuicio();
  renderJuicios();
  try{ if (window._mexpIdxActual === _juicioVincRecIdx) _juRenderDatosDuros(j, _juicioVincRecIdx); }catch(e){}
  toast('✓ Recibo desvinculado del juicio', 'ok');
}
// ══════════════════════════════════════════════════════════════════════════
// MOTOR DE PLAZOS  ·  Juicios
// ──────────────────────────────────────────────────────────────────────────
// Convierte "me notificaron el día X y tengo N días" en una fecha de
// vencimiento real, descontando sábados, domingos y días inhábiles.
// Todo es aritmética local: no usa IA, no necesita internet y es instantáneo.
// Nada de esto altera los términos ya capturados — t.fecha sigue siendo el
// vencimiento que manda; los campos nuevos solo sirven para calcularlo.
// ══════════════════════════════════════════════════════════════════════════

// Días inhábiles oficiales (art. 74 LFT y suspensión de labores típica).
// Es solo la semilla: la usuaria puede agregar o quitar fechas y se guardan
// en D.diasInhabiles, que viaja con el resto del estado a Supabase.
const _JU_INHABILES_BASE = [
  '01-01', // Año Nuevo
  '02-05', // Constitución
  '03-21', // Natalicio de Juárez
  '05-01', // Día del Trabajo
  '09-16', // Independencia
  '11-02', // Día de Muertos
  '11-20', // Revolución
  '12-12', // Guadalupe
  '12-25'  // Navidad
];

// Catálogo inicial de plazos. Editable desde el sistema; se guarda en
// D.catalogoPlazos. Son los términos más usados en materia civil y familiar.
const _JU_PLAZOS_BASE = [
  { nombre:'Contestar demanda',            dias:9,  habiles:true },
  { nombre:'Contestar vista',              dias:3,  habiles:true },
  { nombre:'Ofrecer pruebas',              dias:10, habiles:true },
  { nombre:'Desahogar prevención',         dias:3,  habiles:true },
  { nombre:'Presentar alegatos',           dias:5,  habiles:true },
  { nombre:'Interponer apelación',         dias:9,  habiles:true },
  { nombre:'Interponer revocación',        dias:3,  habiles:true },
  { nombre:'Amparo indirecto',             dias:15, habiles:true },
  { nombre:'Amparo directo',               dias:15, habiles:true },
  { nombre:'Cumplir requerimiento',        dias:3,  habiles:true },
  { nombre:'Exhibir documentos',           dias:3,  habiles:true },
  { nombre:'Objetar pruebas',              dias:3,  habiles:true },
  { nombre:'Personalizado',                dias:0,  habiles:true }
];

function _juCatalogoPlazos(){
  if(typeof D === 'undefined') return _JU_PLAZOS_BASE;
  if(!Array.isArray(D.catalogoPlazos) || !D.catalogoPlazos.length) D.catalogoPlazos = _JU_PLAZOS_BASE.slice();
  return D.catalogoPlazos;
}
function _juInhabilesExtra(){
  if(typeof D === 'undefined') return [];
  if(!Array.isArray(D.diasInhabiles)) D.diasInhabiles = [];
  return D.diasInhabiles;
}

// ¿Es día hábil? Falso en sábado, domingo, feriado fijo o inhábil capturado.
function _juEsHabil(iso){
  if(!iso) return false;
  const d = new Date(iso + 'T12:00:00');
  if(isNaN(d)) return false;
  const dow = d.getDay();
  if(dow === 0 || dow === 6) return false;                 // domingo / sábado
  if(_JU_INHABILES_BASE.includes(iso.slice(5))) return false; // feriado fijo
  if(_juInhabilesExtra().includes(iso)) return false;      // inhábil capturado
  return true;
}
function _juISO(d){
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}
// Suma días a partir de la notificación y devuelve la fecha de vencimiento.
// En días hábiles el conteo arranca al día hábil SIGUIENTE al de la
// notificación (el acuerdo surte efectos al día siguiente), que es la regla
// general en el procedimiento mexicano.
function _juCalcVencimiento(fechaNotif, dias, habiles){
  const n = parseInt(dias, 10);
  if(!fechaNotif || !n || n < 1) return '';
  const d = new Date(fechaNotif + 'T12:00:00');
  if(isNaN(d)) return '';
  if(!habiles){
    d.setDate(d.getDate() + n);
    return _juISO(d);
  }
  let contados = 0, guarda = 0;
  while(contados < n && guarda < 400){
    d.setDate(d.getDate() + 1);
    guarda++;
    if(_juEsHabil(_juISO(d))) contados++;
  }
  return _juISO(d);
}
// Estado de un término respecto a hoy. Devuelve el color y los días.
function _juEstadoTermino(t){
  if(!t || !t.fecha) return { clave:'sin', dias:null, texto:'Sin fecha', color:'#8a7a5e' };
  if(t.cumplido)     return { clave:'cumplido', dias:null, texto:'Cumplido', color:'#8a7a5e' };
  const hoyISO = (typeof _hoyReal === 'function') ? _hoyReal() : new Date().toISOString().slice(0,10);
  const a = new Date(hoyISO + 'T12:00:00'), b = new Date(t.fecha + 'T12:00:00');
  const dias = Math.round((b - a) / 86400000);
  if(dias < 0)  return { clave:'vencido',  dias, texto:'Venció hace '+Math.abs(dias)+' d', color:'#c0161a' };
  if(dias === 0)return { clave:'hoy',      dias, texto:'Vence HOY',                        color:'#c0161a' };
  if(dias <= 3) return { clave:'porvencer',dias, texto:'En '+dias+' d',                    color:'#b07010' };
  if(dias <= 7) return { clave:'proximo',  dias, texto:'En '+dias+' d',                    color:'#b07010' };
  return          { clave:'entiempo', dias, texto:'En '+dias+' d',                         color:'#1a7a3a' };
}
// Todos los términos abiertos de un expediente, INCLUYENDO el que vive en el
// campo antiguo j.audiencia.
// IMPORTANTE: en los expedientes ya capturados la fecha límite muchas veces no
// está en j.terminos sino en j.audiencia (así se guardaba antes). Si solo
// leyéramos j.terminos, expedientes con término vencido —como el de Cristina
// Bazante— aparecerían como "sin términos", que es justo lo que pasaba.
// El término derivado de j.audiencia se marca con _virtual:true para saber que
// todavía no es un registro propio.
function _juTerminosAbiertos(j){
  if(!j) return [];
  const lista = (j.terminos || []).filter(t => t && !t.cumplido && t.fecha).slice();
  const aud = j.audiencia;
  if(aud && !lista.some(t => t.fecha === aud)){
    lista.push({
      id: '_aud_' + aud,
      tipo: 'Audiencia',
      descripcion: j.movimiento || 'Audiencia / término señalado',
      fecha: aud,
      cumplido: false,
      _virtual: true
    });
  }
  lista.sort((a,b) => String(a.fecha).localeCompare(String(b.fecha)));
  return lista;
}
// ── Responsable de cumplir un término ───────────────────────────────────
// A petición expresa (18/ago/2026): hay términos que le corresponde cumplir
// a la CONTRAPARTE o a una AUTORIDAD (juez/DIF/etc.) — no son una obligación
// nuestra, así que no deben contar como "urgente" ni aparecer en el aviso
// del expediente (que es una lista de pendientes DE NOSOTROS). Los términos
// viejos no tienen este campo — se tratan como "nosotros" por compatibilidad
// (nunca se ocultaba nada antes de esto, así que ocultar por default sería
// un cambio de comportamiento peligroso: mejor pecar de mostrar de más).
function _juEsResponsableNuestro(t){
  return !t || !t.responsable || t.responsable === 'nosotros';
}
// Todos los términos abiertos que nos corresponde cumplir a NOSOTROS (excluye
// contraparte/autoridad), ordenados por urgencia — se usa tanto para la lista
// del aviso (puede mostrar varios a la vez) como para "el más urgente".
function _juTerminosPropiosAbiertos(j){
  return _juTerminosAbiertos(j).filter(_juEsResponsableNuestro);
}
// Término abierto más urgente de un expediente que nos corresponda a
// nosotros (el que ordena la lista principal de Juicios).
function _juTerminoUrgente(j){
  const abiertos = _juTerminosPropiosAbiertos(j);
  return abiertos.length ? abiertos[0] : null;
}
// Etapas por tipo de juicio. Configurable en D.etapasPorTipo; si el tipo no
// está catalogado se usa la secuencia genérica.
const _JU_ETAPAS_BASE = ['Demanda','Emplazamiento','Contestación','Probatoria','Alegatos','Sentencia'];
function _juEtapas(j){
  const mapa = (typeof D !== 'undefined' && D.etapasPorTipo) || {};
  const porTipo = mapa[(j && j.tipo) || ''];
  if(Array.isArray(porTipo) && porTipo.length) return porTipo;
  return _JU_ETAPAS_BASE;
}
function _juEtapaActual(j){
  const etapas = _juEtapas(j);
  const i = etapas.indexOf(j && j.etapa);
  return i >= 0 ? i : 0;
}

// Píldora del estatus del expediente. Al darle clic abre la MISMA ventana que
// se usa para capturar un expediente nuevo (abrirJuicioEdit), donde está el
// campo de estatus — así no hay dos formas distintas de editar lo mismo.
function _juPillEstatus(j, idx){
  const est = (j && j.estatus) || 'proceso';
  const cfg = {
    urgente:   { txt:'🔴 Urgente',    bg:'var(--rojo-l)',     col:'#8a0f12', bd:'#e8a0a0' },
    proceso:   { txt:'🟡 En Proceso', bg:'var(--amarillo-l)', col:'#7a4010', bd:'#e0c07a' },
    estable:   { txt:'🟢 Estable',    bg:'var(--verde-l)',    col:'#0a4020', bd:'#8fd6aa' },
    concluido: { txt:'⚫ Concluido',  bg:'#eee9dd',           col:'#5a5040', bd:'#d8d0bd' },
    inicio:    { txt:'🔵 Inicio',     bg:'var(--azul-l)',     col:'#123a70', bd:'#a8c2e6' }
  }[est] || { txt: est, bg:'#eee9dd', col:'#5a5040', bd:'#d8d0bd' };
  return '<span onclick="event.stopPropagation();abrirJuicioEdit(' + idx + ')"'
    + ' title="Cambiar estatus del expediente"'
    + ' style="display:inline-block;font-family:monospace;font-size:.6rem;font-weight:500;'
    + 'padding:2px 9px;border-radius:11px;white-space:nowrap;cursor:pointer;'
    + 'background:' + cfg.bg + ';color:' + cfg.col + ';border:1px solid ' + cfg.bd + ';">'
    + cfg.txt + '</span>';
}

// ── Lista de expedientes en tabla (Pantalla 1 aprobada) ───────────────────
// Se deja como función aparte y renderJuicios() la invoca solo si existe: si
// algún día hubiera que volver a las tarjetas viejas, basta con quitar esta
// función y el sistema regresa solo al comportamiento anterior.
function _juRenderListaTabla(lista, el){
  if(!el) return;
  const esc2 = (s) => (typeof esc === 'function' ? esc(s == null ? '' : s) : String(s == null ? '' : s));
  const _mes = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  const fCorta = (iso) => {
    if(!iso) return '—';
    const p = String(iso).split('-');
    if(p.length !== 3) return iso;
    return parseInt(p[2],10) + '-' + (_mes[parseInt(p[1],10)-1] || p[1]);
  };

  // Tira de indicadores (Términos vencidos / Vencen en 3 días / Audiencias
  // 7 días / Expedientes activos) eliminada a petición del usuario
  // (18/ago/2026) — la tabla de abajo ya cubre lo mismo con detalle.
  let html = '';

  if(!lista.length){
    el.innerHTML = html + '<div style="color:var(--muted);padding:24px;font-size:0.76rem;text-align:center;">Sin expedientes en este filtro.</div>';
    return;
  }

  // ── Orden: primero lo que más urge (vencido arriba), luego sin término ──
  const conOrden = lista.map(j => {
    const t = _juTerminoUrgente(j);
    const e = t ? _juEstadoTermino(t) : null;
    return { j, t, e, orden: (e && e.dias !== null) ? e.dias : 99999 };
  }).sort((a,b) => a.orden - b.orden);

  html += '<div style="border:1.5px solid var(--border-l);border-radius:10px;overflow:hidden;background:var(--surface);">'
    + '<table style="width:100%;border-collapse:collapse;font-size:.79rem;">'
    + '<thead><tr>'
    + ['','Cliente / Asunto','Expediente','Etapa','Próxima actuación','Vence','Estatus','']
        .map((h,i) => '<th style="background:var(--surface2);font-family:monospace;font-size:.56rem;letter-spacing:.11em;'
          + 'text-transform:uppercase;color:var(--gold-d);text-align:left;padding:9px 10px;'
          + 'border-bottom:1.5px solid var(--border-l);font-weight:500;'
          + (i===0?'width:22px;':'') + (i===7?'width:78px;':'') + '">'+h+'</th>').join('')
    + '</tr></thead><tbody>';

  conOrden.forEach(({ j, t, e }) => {
    const idx = D.juicios.indexOf(j);
    const col = e ? e.color : '#8a7a5e';
    // La columna Etapa toma primero el Flujo del Procedimiento (más preciso,
    // generado por IA con base en la ley y los documentos del expediente) —
    // solo si nadie marcó ahí la etapa actual se usa la lista genérica de 6
    // pasos (Demanda/Emplazamiento/.../Sentencia) que se marca a mano.
    let etapaTxt;
    if(Array.isArray(j.flujoProcedimiento) && j.flujoProcedimiento.length
       && typeof j.flujoEtapaActual === 'number' && j.flujoEtapaActual >= 0
       && j.flujoProcedimiento[j.flujoEtapaActual] && j.flujoProcedimiento[j.flujoEtapaActual].etapa){
      etapaTxt = (j.flujoEtapaActual + 1) + '. ' + j.flujoProcedimiento[j.flujoEtapaActual].etapa;
    } else {
      const etapas = _juEtapas(j);
      etapaTxt = j.etapa || etapas[0] || '—';
    }
    const nAcuerdos = (j.acuerdos || []).length + (j.historial || []).filter(h => h && h.tipo === 'acuerdo').length;

    html += '<tr onclick="abrirDetalle('+idx+')" style="cursor:pointer;border-bottom:1px solid var(--border-l);"'
      + ' onmouseover="this.style.background=\'var(--gold-bg)\'" onmouseout="this.style.background=\'\'">'
      // semáforo
      + '<td style="padding:9px 10px;"><span style="width:9px;height:9px;border-radius:50%;display:inline-block;background:'+col+';"></span></td>'
      // cliente / asunto
      + '<td style="padding:9px 10px;"><div style="font-weight:700;color:var(--ink);">'+esc2(j.cliente||'—')+'</div>'
        + '<div style="font-family:monospace;font-size:.66rem;color:var(--muted);">'+esc2(j.tipo||'')+'</div></td>'
      // expediente / juzgado
      + '<td style="padding:9px 10px;"><div style="font-family:monospace;font-size:.72rem;">'+esc2(j.expediente||'—')+'</div>'
        + '<div style="font-family:monospace;font-size:.6rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:170px;">'+esc2(j.juzgado||'')+'</div></td>'
      // etapa
      + '<td style="padding:9px 10px;"><span style="font-family:monospace;font-size:.6rem;background:var(--gold-bg);color:var(--gold-d);'
        + 'border:1px solid var(--border-l);border-radius:10px;padding:2px 8px;white-space:nowrap;">'+esc2(etapaTxt)+'</span></td>'
      // próxima actuación
      + '<td style="padding:9px 10px;">'+(t ? esc2(t.descripcion || t.tipo || '—')
          : '<span style="color:var(--muted);font-style:italic;">Sin término abierto</span>')+'</td>'
      // vence
      + '<td style="padding:9px 10px;font-family:monospace;font-size:.72rem;color:'+col+';font-weight:600;white-space:nowrap;">'
        + (t ? fCorta(t.fecha) + '<div style="font-size:.6rem;font-weight:400;">'+esc2(e.texto)+'</div>' : '—') + '</td>'
      // estatus (clic para cambiarlo en la misma ventana de captura)
      + '<td style="padding:9px 10px;">' + _juPillEstatus(j, idx) + '</td>'
      // acciones + señales
      + '<td style="padding:9px 10px;white-space:nowrap;">'
        + '<button onclick="event.stopPropagation();abrirJuicioEdit('+idx+')" title="Editar expediente / cambiar estatus"'
        +   ' style="background:none;border:1px solid var(--border-l);border-radius:5px;cursor:pointer;'
        +   'color:var(--muted);font-size:.75rem;padding:3px 7px;margin-right:5px;"'
        +   ' onmouseover="this.style.borderColor=\'var(--gold)\';this.style.color=\'var(--gold-d)\'"'
        +   ' onmouseout="this.style.borderColor=\'var(--border-l)\';this.style.color=\'var(--muted)\'">✏</button>'
        + '<span style="font-size:.62rem;color:var(--muted);" title="'
        +   (j.folioRecibo?'Recibo vinculado. ':'') + (j.driveFolderId?'Carpeta en Drive. ':'') + nAcuerdos + ' acuerdos">'
        +   (j.folioRecibo?'🧾':'') + (j.driveFolderId?'📁':'') + (nAcuerdos?'<span style="font-family:monospace;">'+nAcuerdos+'</span>':'')
        + '</span>'
        + '</td>'
      + '</tr>';
  });

  html += '</tbody></table></div>'
    + '<div style="text-align:center;padding:10px 0 2px;font-family:monospace;font-size:.62rem;color:var(--muted);">'
    + 'Clic en cualquier renglón para abrir el expediente</div>';
  el.innerHTML = html;
}

function renderJuicios(){
  // Total de juicios/expedientes registrados (todos los estatus), mismo
  // formato de caja que el contador de Pendientes.
  const _juTotBox = document.getElementById('juiciosTotalNum');
  if (_juTotBox) _juTotBox.textContent = (D.juicios || []).length;
  const q=($('juicioQ')?.value||'').toLowerCase();
  let l=D.juicios.filter(j=>{
    if(filtroJ!=='todos'&&j.estatus!==filtroJ)return false;
    if(q)return(j.cliente||'').toLowerCase().includes(q)||(j.expediente||'').toLowerCase().includes(q)||(j.tipo||'').toLowerCase().includes(q);
    return true;
  });
  const el=$('listaJuicios');
  // ── VISTA NUEVA: tira de indicadores + tabla comparable ────────────────
  // Sustituye las tarjetas por una tabla con dos columnas que antes no
  // existían y son las que sirven para trabajar: "Próxima actuación" y
  // "Vence". El estatus de urgencia ya NO se escribe a mano: se calcula del
  // término abierto más próximo, así no se desactualiza solo.
  if(typeof _juRenderListaTabla === 'function'){ _juRenderListaTabla(l, el); return; }
  if(!l.length){el.innerHTML='<div style="color:var(--muted);padding:24px;font-size:0.76rem;">Sin expedientes en este filtro.</div>';return;}
  const hoyD=new Date();
  el.innerHTML=l.map(j=>{
    const idx=D.juicios.indexOf(j);
    const tagC={'urgente':'tag-r','proceso':'tag-a','estable':'tag-v','concluido':'tag-m','inicio':'tag-b'}[j.estatus]||'tag-m';
    const tagL={'urgente':'🔴 Urgente','proceso':'🟡 En Proceso','estable':'🟢 Estable','concluido':'⚫ Concluido','inicio':'🔵 Inicio'}[j.estatus]||j.estatus;
    let alerta='';
    // Check próxima audiencia
    const audFecha=j.audiencia||proximaAudienciaDeTerminos(j);
    if(audFecha){
      const diff=Math.ceil((new Date(audFecha+'T12:00:00')-hoyD)/86400000);
      if(diff>=0&&diff<=30)alerta=`<div class="audiencia-alerta">⚠ Audiencia/Término en ${diff} día${diff===1?'':'s'} — ${audFecha}</div>`;
      else if(diff<0)alerta=`<div class="audiencia-alerta">🚨 Término vencido: ${audFecha}</div>`;
    }
    const folioTag=j.folioRecibo?`<span style="font-family:monospace;font-size:0.58rem;color:var(--gold-d);background:var(--gold-bg);border:1px solid var(--border-l);border-radius:10px;padding:1px 8px;">🧾 #${folioFormato(j.folioRecibo)}</span>`:'';
    const driveTag=j.driveFolderId?`<span style="font-size:0.58rem;color:var(--azul);background:var(--azul-l);border:1px solid rgba(26,74,138,0.15);border-radius:10px;padding:1px 8px;font-family:monospace;">📁 Drive</span>`:'';
    // FIX: había expedientes (como el de CRISTINA BAZANTE) cuyos acuerdos se
    // registraron en j.historial (tipo:'acuerdo', vía análisis de documentos)
    // en vez de en j.acuerdos (el formulario manual "Nuevo Acuerdo") — la
    // etiqueta marcaba 0 aunque sí había acuerdos reales. Se cuentan ambas
    // fuentes para reflejar la realidad sin importar por dónde se cargaron.
    const acuerdosCount=(j.acuerdos||[]).length + (j.historial||[]).filter(h=>h&&h.tipo==='acuerdo').length;
    const acuerdosTag=acuerdosCount?`<span style="font-size:0.58rem;color:var(--muted);background:var(--surface2);border:1px solid var(--border-l);border-radius:10px;padding:1px 8px;font-family:monospace;">📄 ${acuerdosCount} acuerdo${acuerdosCount===1?'':'s'}</span>`:'';
    const terminosVivos=(j.terminos||[]).filter(t=>!t.cumplido);
    const terminosTag=terminosVivos.length?`<span style="font-size:0.58rem;color:var(--amarillo);background:var(--amarillo-l);border:1px solid rgba(154,96,16,0.15);border-radius:10px;padding:1px 8px;font-family:monospace;">⏱ ${terminosVivos.length} término${terminosVivos.length===1?'':'s'}</span>`:'';
    return `<div class="juicio ${j.estatus}" onclick="abrirDetalle(${idx})">
      <div class="juicio-top">
        <div><div class="juicio-nombre">${esc(j.cliente)}</div><div class="juicio-tipo">${esc(j.tipo)}</div></div>
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
          <span class="tag ${tagC}">${tagL}</span>
          <span class="mono" style="font-size:0.62rem;color:var(--muted)">${esc(j.expediente)}</span>
        </div>
      </div>
      <div class="juicio-info">
        <div class="jdato"><strong>Juzgado:</strong> ${esc(j.juzgado)}</div>
        <div class="jdato"><strong>Ingreso:</strong> ${j.fechaIngreso||'—'}</div>
        ${j.tel?`<div class="jdato"><strong>Tel:</strong> ${esc(j.tel)}</div>`:''}
      </div>
      <div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:7px;align-items:center;">
        ${folioTag}${driveTag}${acuerdosTag}${terminosTag}
        <button class="juicio-btn-vincular" onclick="event.stopPropagation();abrirGestionReciboJuicio(${idx})" title="${j.folioRecibo?'Cambiar / Desvincular recibo':'Vincular un recibo'}">
          ${j.folioRecibo?'✏️ Cambiar recibo':'🔗 Vincular recibo'}
        </button>
      </div>
      ${_finResumen(j.cliente, j.folioRecibo)}
      ${j.movimiento?`<div style="font-size:0.72rem;color:var(--gold-d);margin-top:6px;font-style:italic;">→ ${esc(j.movimiento)}</div>`:''}
      ${alerta}
    </div>`;
  }).join('');
}
function proximaAudienciaDeTerminos(j){
  if(!j.terminos||!j.terminos.length)return null;
  const hoy2=hoy();
  const futuros=j.terminos.filter(t=>!t.cumplido&&t.fecha>=hoy2).sort((a,b)=>a.fecha.localeCompare(b.fecha));
  return futuros.length?futuros[0].fecha:null;
}
// ─── Detalle de Juicio (LEGACY — ya NO es la versión activa) ───────
// FIX (18/ago/2026): había TRES funciones llamadas "abrirDetalle" en el
// archivo (esta, otra en ~línea 56575, y la vigente en ~línea 66237, con
// pestañas/notas/documentos/aviso de término). Al haber más de una definición
// con el mismo nombre global, cuál "gana" en tiempo de ejecución depende del
// orden de hoisting/reasignación — frágil y confuso, y probablemente la causa
// de que ediciones recientes al modal de expediente no se reflejaran de forma
// consistente. Se renombra esta (obsoleta: usa #juicio-detalle/.jdet-tab, un
// sistema de pestañas viejo que ya no existe en el HTML actual) para que ya
// no compita por el nombre "abrirDetalle" — deja de ejecutarse nunca.
function _abrirDetalleLegacyV1_NoUsar(idx){
  jdetIdx=idx;
  const j=D.juicios[idx];
  $('juicios-lista-view').style.display='none';
  const det=$('juicio-detalle');
  det.classList.add('visible');
  // Header
  $('jdet-nombre').textContent=j.cliente||'—';
  $('jdet-tipo').textContent=(j.tipo||'')+(j.expediente?' · Exp. '+j.expediente:'');
  // Estatus tag
  const tagC={'urgente':'tag-r','proceso':'tag-a','estable':'tag-v','concluido':'tag-m','inicio':'tag-b'}[j.estatus]||'tag-m';
  const tagL={'urgente':'🔴 Urgente','proceso':'🟡 En Proceso','estable':'🟢 Estable','concluido':'⚫ Concluido','inicio':'🔵 Inicio'}[j.estatus]||j.estatus;
  $('jdet-estatus-tag').className='tag '+tagC;
  $('jdet-estatus-tag').textContent=tagL;
  $('jdet-exp-badge').textContent=j.expediente?'Exp. '+j.expediente:'';
  // Folio
  if(j.folioRecibo){
    $('jdet-folio-badge').style.display='';
    $('jdet-folio-badge').textContent='🧾 Folio #'+folioFormato(j.folioRecibo);
  } else {
    $('jdet-folio-badge').style.display='none';
  }
  // Drive badge
  if(j.driveFolderId){
    $('jdet-drive-label').textContent='📂 '+j.driveFolderName;
    $('jdet-drive-badge').title='Abrir carpeta en Drive';
    $('jdet-drive-badge').onclick=()=>{
      // Solo abrir Drive si el ID es un ID real de Google Drive (empieza con 1 y tiene ~33 chars)
      const fid = j.driveFolderId || '';
      const esIdReal = fid.length > 25 && !fid.startsWith('juicio-');
      if(esIdReal){
        window.open('https://drive.google.com/drive/folders/'+fid,'_blank');
      } else {
        abrirVinculacionDrive();
      }
    };
  } else {
    $('jdet-drive-label').textContent='Vincular juicio';
    $('jdet-drive-badge').onclick=()=>abrirVinculacionDrive();
  }
  // Tab datos
  $('jd-expediente').textContent = j.expediente || '— Sin asignar —';
  // Control interno: si existe, mostrar; si no, mostrar botón para asignar
  const ciEl = $('jd-control-interno');
  if (ciEl) {
    if (j.controlInterno) {
      ciEl.innerHTML = '<span style="font-weight:700;color:var(--ink);">' + esc(j.controlInterno) + '</span>' +
        '<button onclick="editarControlInterno()" title="Editar" style="background:rgba(200,149,42,0.1);border:1px solid rgba(200,149,42,0.25);color:var(--gold-d);border-radius:3px;padding:2px 8px;font-size:0.58rem;cursor:pointer;font-family:\'JetBrains Mono\',monospace;font-weight:600;">✏️</button>';
    } else {
      ciEl.innerHTML = '<button onclick="editarControlInterno()" style="background:rgba(26,74,138,0.08);border:1px dashed rgba(26,74,138,0.3);color:var(--azul);border-radius:4px;padding:4px 10px;font-size:0.65rem;cursor:pointer;font-family:\'JetBrains Mono\',monospace;font-weight:600;letter-spacing:0.05em;">+ Asignar control interno</button>';
    }
  }
  $('jd-juzgado').textContent=j.juzgado||'—';
  $('jd-ingreso').textContent=j.fechaIngreso||'—';
  $('jd-audiencia').textContent=j.audiencia||proximaAudienciaDeTerminos(j)||'Sin audiencia programada';
  $('jd-tel').textContent=j.tel||'—';
  $('jd-movimiento').textContent=j.movimiento||'Sin movimientos registrados';
  $('jd-obs').textContent=j.obs||'';
  // Carpeta Drive: mostrar enlace clickeable o botón para vincular
  const driveEl = $('jd-drive-carpeta');
  if (driveEl) {
    if (j.driveFolderId) {
      const url = 'https://drive.google.com/drive/folders/' + j.driveFolderId;
      driveEl.innerHTML = '<a href="' + url + '" target="_blank" style="display:inline-flex;align-items:center;gap:6px;background:rgba(26,74,138,0.08);border:1px solid rgba(26,74,138,0.25);color:var(--azul);border-radius:4px;padding:6px 12px;text-decoration:none;font-family:\'JetBrains Mono\',monospace;font-size:0.7rem;font-weight:600;transition:all 0.15s;">📁 Abrir carpeta en Drive ↗</a>' +
        '<button onclick="abrirVinculacionDrive()" title="Cambiar carpeta vinculada" style="margin-left:6px;background:none;border:1px solid var(--border-l);color:var(--muted);border-radius:3px;padding:4px 8px;font-size:0.58rem;cursor:pointer;font-family:\'JetBrains Mono\',monospace;">✏️</button>' +
        '<button onclick="desvincularCarpetaDrive()" title="Desvincular carpeta" style="margin-left:4px;background:none;border:1px solid var(--rojo-l);color:var(--rojo);border-radius:3px;padding:4px 8px;font-size:0.58rem;cursor:pointer;font-family:\'JetBrains Mono\',monospace;">✕</button>';
    } else {
      driveEl.innerHTML = '<button onclick="abrirVinculacionDrive()" style="background:rgba(26,74,138,0.08);border:1px dashed rgba(26,74,138,0.3);color:var(--azul);border-radius:4px;padding:6px 12px;font-family:\'JetBrains Mono\',monospace;font-size:0.7rem;cursor:pointer;font-weight:600;letter-spacing:0.05em;">📁 Vincular carpeta de Drive</button>';
    }
  }
  renderFolioReciboDetalle(j);
  // Ir a tab datos
  switchJTab('datos',document.querySelector('.jdet-tab'));
  renderAcuerdos();
  renderTerminos();
}
function cerrarDetalle(){
  cerrarModalExpediente();
  cerrarVisorPDF();
}
function confirmarEliminarJuicio(idx){
  const j = D.juicios[idx];
  if(!j) return;
  const nombre = j.cliente || j.nombre || 'este expediente';
  const exp = j.expediente || j.num || '';
  const msg = '¿Eliminar el juicio de ' + nombre + (exp ? ' (Exp. '+exp+')' : '') + '?\n\nEsta acción no se puede deshacer.';
  if(!confirm(msg)) return;

  // Eliminar resúmenes de R2 y caché local antes de borrar el juicio
  const jId = j.id || idx;
  const lsKey = 'lex_acuerdos_' + jId;
  try {
    const acuerdos = JSON.parse(localStorage.getItem(lsKey) || '[]');
    acuerdos.forEach(ac => {
      if (ac.driveFileId && typeof _r2ResumenPath === 'function') {
        window.borrarR2(_r2ResumenPath(ac.driveFileId), 'expedientes')
          .catch(e => console.warn('[EliminarJuicio] R2:', e));
      }
    });
    localStorage.removeItem(lsKey);
  } catch(e) { console.warn('[EliminarJuicio] limpieza:', e); }

  _marcarJuicioEliminadoLocal(j.id);
  D.juicios.splice(idx, 1);
  try { backupLocal('D', D); } catch(e){ registrarError('catch vacio', e); }
  saveJuicios();
  cerrarDetalle();
  renderJuicios();
  badges();
  toast('Juicio eliminado', 'ok');
}
function switchJTab(tab,el){
  document.querySelectorAll('.jdet-tab').forEach(t=>t.classList.remove('active'));
  document.querySelectorAll('.jdet-panel').forEach(p=>p.classList.remove('active'));
  if(el)el.classList.add('active');
  $('jtab-'+tab).classList.add('active');
}
function abrirJuicioEdit(idx){
  const j=idx>=0?D.juicios[idx]:{};
  $('jCli').value=j.cliente||''; const jTipoEl=$('jTipo'); if(jTipoEl){ jTipoEl.value=j.tipo||''; if(!jTipoEl.value && j.tipo) jTipoEl.setAttribute('value',j.tipo||''); }
  if($('jCalidad')) $('jCalidad').value = j.calidadCliente || '';
  $('jExp').value=j.expediente||'';$('jJuz').value=j.juzgado||'Juzgado Mixto Juxtlahuaca';
  $('jFIng').value=j.fechaIngreso||'';$('jAud').value=j.audiencia||'';
  $('jEst').value=j.estatus||'proceso';$('jTel').value=j.tel||'';
  $('jMov').value=j.movimiento||'';$('jObs').value=j.obs||'';
  // Control interno (campo nuevo)
  if($('jCtrlInt')) $('jCtrlInt').value = j.controlInterno || '';
  $('mJTitulo').textContent=idx>=0?'Editar Expediente':'Nuevo Expediente';
  eiJ=idx;
  try{ _mJuActualizarVinculaciones(idx>=0?j:null, idx); }catch(e){ registrarError('mJuicio · vinculaciones', e); }
  $('mJuicio').classList.add('show');
}
// ─── Vincular carpeta/recibo desde el modal Nuevo/Editar Expediente ───
// Reusa los flujos ya existentes (abrirVinculacionDrive / abrirVinculacionFolio),
// que operan sobre jdetIdx — por eso lo apuntamos al mismo expediente (eiJ)
// antes de invocarlos. Solo disponible si el expediente ya existe (eiJ>=0):
// no tiene sentido vincular carpeta/recibo a un juicio que aún no se ha guardado.
function _mJuActualizarVinculaciones(j, idx){
  const info=$('jVincInfo'), btnC=$('jBtnVincCarpeta'), btnR=$('jBtnVincRecibo');
  if(!info||!btnC||!btnR) return;
  if(idx<0){
    info.innerHTML='⚠ Guarda el expediente primero para poder vincular su carpeta o su recibo.';
    btnC.disabled=true; btnR.disabled=true;
    return;
  }
  btnC.disabled=false; btnR.disabled=false;
  const carpetaTxt=(j&&j.driveFolderName)?('📁 '+esc(j.driveFolderName)):'📁 Sin carpeta vinculada';
  const recTxt=(j&&j.folioRecibo)?('🔗 Folio #'+folioFormato(j.folioRecibo)):'🔗 Sin recibo vinculado';
  info.innerHTML=carpetaTxt+'  ·  '+recTxt;
}
function _mJuVincularCarpeta(){
  if(eiJ<0||!D.juicios[eiJ]){ toast('Guarda el expediente primero','err'); return; }
  jdetIdx=eiJ;
  cerrar('mJuicio');
  abrirVinculacionDrive();
}
function _mJuVincularRecibo(){
  if(eiJ<0||!D.juicios[eiJ]){ toast('Guarda el expediente primero','err'); return; }
  jdetIdx=eiJ;
  cerrar('mJuicio');
  abrirVinculacionFolio();
}
function abrirJuicio(idx){
  // Compatibilidad: si se llama sin idx desde la lista (nuevo), o con idx (editar)
  if(idx===undefined)idx=-1;
  abrirJuicioEdit(idx);
}
function guardarJuicio(){
  try {
    const j = D.juicios[eiJ] || {};
    const ctrlInt = ($('jCtrlInt') ? $('jCtrlInt').value.trim() : '');
    const upd = {
      // Identificador único y marca de tiempo — necesarios para que
      // sincronizarFolio() pueda fusionar por id en vez de sobreescribir
      // todo D.juicios con la copia de Supabase (mismo fix que ya se aplicó
      // a carpetas/escrituras/citas/pendientes).
      id:         j.id || ('JUI-'+Date.now()),
      updatedAt:  Date.now(),
      cliente:    $('jCli').value.trim(),
      calidadCliente: $('jCalidad') ? $('jCalidad').value : (j.calidadCliente || ''),
      tipo:       $('jTipo').value,
      expediente: $('jExp').value.trim(),
      juzgado:    $('jJuz').value.trim(),
      fechaIngreso: $('jFIng').value,
      audiencia:  $('jAud').value,
      estatus:    $('jEst').value,
      tel:        $('jTel').value.trim(),
      movimiento: $('jMov').value.trim(),
      obs:        $('jObs').value.trim(),
      // Preservar campos que no están en el formulario
      driveFolderId:   j.driveFolderId   || null,
      driveFolderName: j.driveFolderName || null,
      folioRecibo:     j.folioRecibo     || null,
      foliosRecibo:    j.foliosRecibo    || (j.folioRecibo ? [j.folioRecibo] : []),
      carpetaFisica:   j.carpetaFisica   || null,
      acuerdos:        j.acuerdos        || [],
      terminos:        j.terminos        || [],
      historial:       j.historial       || [],
      controlInterno:  ctrlInt || j.controlInterno || null,
      expedienteNum:   j.expedienteNum   || null,
    };
    if (!upd.cliente) { toast('El cliente es obligatorio', 'err'); return; }
    if (eiJ >= 0) {
      D.juicios[eiJ] = upd;
    } else {
      D.juicios.unshift(upd);
    }
    // Guardar en localStorage inmediatamente (sin esperar a Supabase)
    try { backupLocal('D', D); } catch(e){ registrarError('catch vacio', e); }
    // Sincronizar con Supabase (async, no bloquea el cierre del modal)
    saveJuicios();
    // Actualizar UI
    renderJuicios();
    badges();
    cerrar('mJuicio');
    toast('Expediente guardado ✓', 'ok');
    // Si el detalle estaba abierto, refrescarlo
    if (jdetIdx >= 0 && eiJ === jdetIdx) abrirDetalle(jdetIdx);
  } catch(e) {
    console.error('[guardarJuicio]', e);
    toast('Error al guardar: ' + e.message, 'err');
  }
}
// ─── Acuerdos ─────────────────────────────────────────────────────
function renderAcuerdos(){
  const j=D.juicios[jdetIdx];
  if(!j)return;
  const acuerdos=(j.acuerdos||[]).slice().sort((a,b)=>b.fecha.localeCompare(a.fecha));
  const el=$('lista-acuerdos');
  const ultiEl=$('jdet-ultimo-acuerdo');
  if(!acuerdos.length){
    el.innerHTML='<div style="color:var(--muted);padding:24px;font-size:0.76rem;text-align:center;">Sin acuerdos registrados.<br>Agrega el primer acuerdo del juzgado.</div>';
    ultiEl.style.display='none';return;
  }
  // Mostrar último acuerdo destacado
  const ultimo=acuerdos[0];
  ultiEl.style.display='';
  $('jdet-ultimo-body').innerHTML=`
    <div style="display:flex;gap:12px;align-items:flex-start;">
      <span class="acuerdo-tipo-tag" style="background:var(--gold-bg);color:var(--gold-d);">${esc(ultimo.tipo)}</span>
      <span style="font-family:monospace;font-size:0.65rem;color:var(--muted);">${ultimo.fecha}</span>
    </div>
    <div style="font-size:0.85rem;margin-top:8px;line-height:1.6;color:var(--ink);">${esc(ultimo.descripcion)}</div>
    ${ultimo.resumenIA?`<div class="acuerdo-resumen"><span class="acuerdo-resumen-label">✨ Resumen IA</span>${esc(ultimo.resumenIA)}</div>`:''}
    ${ultimo.driveFileId?`<a class="acuerdo-pdf-btn" onclick="verPDFAcuerdo('${ultimo.driveFileId}','${esc(ultimo.driveFileName||'acuerdo.pdf')}')">📄 Ver PDF</a>`:''}
  `;
  // Lista completa
  el.innerHTML=acuerdos.map((a,i)=>{
    const d=new Date(a.fecha+'T12:00:00');
    const dia=String(d.getDate()).padStart(2,'0');
    const mes=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][d.getMonth()];
    const yr=d.getFullYear();
    const tipoColors={'Acuerdo':'background:var(--azul-l);color:var(--azul);','Sentencia':'background:#f3e8ff;color:#7c3aed;','Notificación':'background:var(--amarillo-l);color:var(--amarillo);','Requerimiento':'background:var(--rojo-l);color:var(--rojo);','Exhorto':'background:var(--verde-l);color:var(--verde-d);'}[a.tipo]||'background:var(--surface2);color:var(--muted);';
    return `<div class="acuerdo-item">
      <div class="acuerdo-fecha-col">
        <div class="acuerdo-fecha-dia">${dia}</div>
        <div class="acuerdo-fecha-mes">${mes}</div>
        <div class="acuerdo-fecha-yr">${yr}</div>
      </div>
      <div class="acuerdo-body">
        <span class="acuerdo-tipo-tag" style="${tipoColors}">${esc(a.tipo)}</span>
        <div class="acuerdo-desc">${esc(a.descripcion)}</div>
        ${a.resumenIA?`<div class="acuerdo-resumen"><span class="acuerdo-resumen-label">✨ Resumen IA</span>${esc(a.resumenIA)}</div>`:''}
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px;">
          ${a.driveFileId?`<a class="acuerdo-pdf-btn" onclick="verPDFAcuerdo('${a.driveFileId}','${esc(a.driveFileName||'acuerdo.pdf')}')">📄 Ver PDF</a>`:''}
          <a class="acuerdo-pdf-btn" style="background:var(--rojo-l);color:var(--rojo);border-color:rgba(192,22,26,0.2);" onclick="eliminarAcuerdo(${i})">🗑</a>
        </div>
      </div>
    </div>`;
  }).join('');
}
