let _carpetaVinculadaActual = null;
function abrirVincularArchivo() {
  const folioActual = $('folio-display')?.textContent;
  const folioNum = parseInt(folioActual) || null;
  const folioStr = folioNum ? folioFormato(folioNum) : null;
  const carpetaExistente = folioStr
    ? D.carpetas.find(c => String(c.reciboOficial||'').replace('#','').trim() === folioStr)
    : null;
  _carpetaVinculadaActual = carpetaExistente || null;
  const wrapActual = document.getElementById('mVA-actual');
  if (carpetaExistente) {
    wrapActual.style.display = 'block';
    document.getElementById('mVA-actual-info').textContent =
      'Carpeta #' + carpetaExistente.num + ' — ' + (carpetaExistente.cliente || '');
    document.getElementById('mVA-actual-estado').textContent = _getInfoPagoCarpeta(carpetaExistente);
  } else {
    wrapActual.style.display = 'none';
  }
  document.getElementById('mVA-buscar').value = '';
  mVAFiltrar();
  document.getElementById('mVincularArchivo').classList.add('show');
  setTimeout(()=>document.getElementById('mVA-buscar')?.focus(), 120);
}
function mVAFiltrar() {
  const q = (document.getElementById('mVA-buscar')?.value || '').toLowerCase().trim();
  const lista = document.getElementById('mVA-lista');
  if (!lista) return;
  // Sin query → mostrar mensaje invitando a buscar
  if(!q){
    lista.innerHTML = '<div style="padding:28px;text-align:center;color:var(--muted);font-size:0.75rem;line-height:1.8;">🔍 Escribe el número, nombre o trámite<br>para buscar una carpeta</div>';
    return;
  }
  const carpetas = D.carpetas || [];
  const filtradas = carpetas.filter(c =>
    String(c.num||'').includes(q) ||
    (c.cliente||'').toLowerCase().includes(q) ||
    (c.descripcion||'').toLowerCase().includes(q)
  ).slice(0, 20);
  if (!filtradas.length) {
    lista.innerHTML = '<div style="padding:20px;text-align:center;color:var(--muted);font-size:0.75rem;">Sin carpetas encontradas para <strong>"'+esc(q)+'"</strong></div>';
    return;
  }
  const raw = parseInt($('folio-display')?.textContent||'0')||0;
  const folioDisplay = folioFormato(raw);
  lista.innerHTML = filtradas.map(c => {
    const estadoColor = {ACTIVO:'var(--verde)',ARCHIVADO:'var(--muted)',CANCELADO:'var(--rojo)'}[c.estadoArchivo]||'var(--muted)';
    const estadoIcon  = {ACTIVO:'✅',ARCHIVADO:'📦',CANCELADO:'❌'}[c.estadoArchivo]||'📂';
    const priIcon     = {URGENTE:'🔴',BUEN_TIEMPO:'🟢',REZAGADO:'🟡'}[c.prioridad]||'';
    const saldoInfo   = _getInfoPagoCarpeta(c);
    const yaVinculada = String(c.reciboOficial||'').replace('#','').trim() === folioDisplay;
    const bColor = yaVinculada ? 'var(--verde)' : 'var(--border-l)';
    const bBg    = yaVinculada ? 'var(--verde-l)' : 'var(--surface)';
    return '<div onclick="seleccionarCarpetaArchivo(\''+c.num+'\')"'
      +' style="display:flex;align-items:center;gap:12px;padding:10px 12px;border:1.5px solid '+bColor+';border-radius:7px;margin-bottom:6px;cursor:pointer;background:'+bBg+';transition:all 0.15s;"'
      +' onmouseover="this.style.borderColor=\'var(--gold)\';this.style.background=\'var(--gold-pale)\'"'
      +' onmouseout="this.style.borderColor=\''+bColor+'\';this.style.background=\''+bBg+'\'">'
      +'<div style="font-family:\'JetBrains Mono\',monospace;font-size:1.3rem;font-weight:800;color:var(--gold-d);min-width:44px;text-align:center;">#'+c.num+'</div>'
      +'<div style="flex:1;min-width:0;">'
      +'<div style="font-weight:600;font-size:0.84rem;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+esc(c.cliente||'—')+'</div>'
      +'<div style="font-size:0.67rem;color:var(--muted);margin-top:2px;">'+esc(c.descripcion||'')+' '+priIcon+'</div>'
      +'<div style="font-size:0.63rem;margin-top:3px;color:'+estadoColor+';font-family:\'JetBrains Mono\',monospace;">'+estadoIcon+' '+(c.estadoArchivo||'Sin estado')+' · '+saldoInfo+'</div>'
      +'</div>'
      +(yaVinculada?'<span style="font-size:0.58rem;font-family:\'JetBrains Mono\',monospace;color:var(--verde-d);font-weight:700;flex-shrink:0;">✓ VINCULADA</span>':'')
      +'</div>';
  }).join('');
}
function _getInfoPagoCarpeta(c) {
  const recibos = (typeof appData!=='undefined'?appData.recibos:REC.recibos)||[];
  const folioStr = String(c.reciboOficial||'').replace('#','').trim();
  let rec = null;
  if (folioStr) rec = recibos.find(r=>r.folio===parseInt(folioStr));
  if (!rec) rec = recibos.find(r=>String(r.carpeta||'')===String(c.num));
  if (!rec) return 'Sin recibo vinculado';
  const saldo = rec.saldoPendiente!=null?rec.saldoPendiente:Math.max(0,(rec.total||0)-parseFloat(rec.anticipo||0));
  if (rec.cancelado) return '🚫 Cancelado';
  if (saldo<=0) return '✅ Liquidado';
  return '⚠ Saldo: $'+fmt(saldo);
}
function seleccionarCarpetaArchivo(numCarpeta) {
  const c = D.carpetas.find(x=>x.num===numCarpeta);
  if (!c) return;
  const raw = parseInt($('folio-display')?.textContent||'0')||0;
  const folioStr = folioFormato(raw);
  c.reciboOficial = folioStr;
  save(); saveCarpetas();
  if (typeof appData!=='undefined'&&appData.recibos) {
    const rec = appData.recibos.find(r=>r.folio===raw);
    if (rec) { rec._carpetaInterna=numCarpeta; save(); }
  }
  _actualizarBadgeArchivoVinculado(c);
  _carpetaVinculadaActual = c;
  cerrarVincularArchivo();
  toast('🗂️ Recibo vinculado a Carpeta #'+numCarpeta+' — '+c.cliente,'ok');
}
function desvincularArchivo() {
  if (!_carpetaVinculadaActual) return;
  const c = D.carpetas.find(x=>x.num===_carpetaVinculadaActual.num);
  if (c) { c.reciboOficial=''; save(); saveCarpetas(); }
  _carpetaVinculadaActual=null;
  _actualizarBadgeArchivoVinculado(null);
  cerrarVincularArchivo();
  toast('Vinculación eliminada');
}
// Cierra el modal de Vincular Archivo y, si se abrió desde la Ficha del Folio
// (botón "Exp. Digital" en folios no vehiculares, que cierra la ficha antes de
// abrir este modal), la reabre — mismo patrón que cerrarExpDigital/cerrarContabPDF.
function cerrarVincularArchivo() {
  cerrar('mVincularArchivo');
  if (window._fichaAbiertaAntes) {
    window._fichaAbiertaAntes = false;
    setTimeout(function(){ if (reciboEnConsulta) abrirFichaFolio(); }, 400);
  }
}
function _actualizarBadgeArchivoVinculado(c) {
  const badge=document.getElementById('badge-archivo-vinculado');
  const btn=document.getElementById('btn-vincular-archivo');
  if(!badge||!btn)return;
  if(c){
    badge.style.display='block';
    btn.style.borderColor='#1a7a3a'; btn.style.color='#1a7a3a';
    btn.title='Carpeta #'+c.num+' — '+c.cliente+' (vinculada)';
  }else{
    badge.style.display='none';
    btn.style.borderColor='#1a4a8a'; btn.style.color='#1a4a8a';
    btn.title='Vincular con Carpetas (solo interno)';
  }
}
function actualizarBadgeArchivoDesdeRecibo(folioNum) {
  const c = (D.carpetas||[]).find(c=>{
    const f=String(c.reciboOficial||'').replace('#','').trim();
    return f&&parseInt(f)===folioNum;
  });
  _actualizarBadgeArchivoVinculado(c||null);
  _carpetaVinculadaActual=c||null;
}
function saveJuicios(){
  // Estampar updatedAt en el/los juicio(s) recién modificado(s) — este es el
  // único punto por el que pasan TODAS las mutaciones de juicios (formulario
  // principal vía eiJ, y términos/acuerdos/control interno/vínculo Drive vía
  // jdetIdx), así que estampar aquí cubre todos los flujos sin tener que
  // repetirlo en cada función individual. Necesario para que el merge de
  // sincronizarFolio() sepa que esta versión es más reciente que la que ya
  // tenga Supabase (mismo patrón que carpetas/escrituras/citas/pendientes).
  [eiJ, jdetIdx].forEach(function(_idx){
    if(_idx >= 0 && D.juicios[_idx]) D.juicios[_idx].updatedAt = Date.now();
  });
  // Registrar timestamp de modificación local (cubre también eliminaciones)
  // para que sincronizarFolio() no restaure datos viejos de Supabase.
  D._juiciosModTs = Date.now();
  _ultimoSyncPropio = Date.now();
  console.log('[saveJuicios] Guardando', (D.juicios||[]).length, 'juicios en Supabase...');
  syncEstadoSupabase()
    .then(function(){ console.log('[saveJuicios] ✅ Guardado exitoso — juicios:', (D.juicios||[]).length); })
    .catch(function(e){ console.error('[saveJuicios] ❌ ERROR al guardar:', e); });
}
// ═══ PENDIENTES ═══
function setPF(f,el){
  // Filter locked to 'activos' — filter bar removed
  filtroP = 'activos';
  renderPend();
}
function verPendResueltos(){
  const btn = $('pendBtnResueltos');
  const btnVaciar = $('pendBtnVaciarResueltos');
  if(filtroP === 'resuelto'){
    filtroP = 'activos';
    if(btn){ btn.textContent = '✓ Resueltos'; btn.style.background='var(--surface)'; btn.style.color='var(--muted)'; }
    if(btnVaciar) btnVaciar.style.display = 'none';
  } else {
    filtroP = 'resuelto';
    if(btn){ btn.textContent = '← Activos'; btn.style.background='var(--gold-d)'; btn.style.color='#fff'; }
    if(btnVaciar) btnVaciar.style.display = '';
  }
  renderPend();
}
// Borra para siempre TODOS los pendientes resueltos actuales, sin esperar
// los 35 días — pensado para limpiar pruebas o vaciar el respaldo a mano.
// Los números de ficha de los borrados NO se reutilizan (política normal:
// un número nunca se vuelve a asignar, salvo excepción manual expresa).
async function vaciarResueltosDefinitivo(){
  const resueltos = (D.pendientes||[]).filter(p=>p && p.resuelto);
  if(!resueltos.length){ toast('No hay pendientes resueltos que borrar.'); return; }
  const auth = await pedirAutorizacion();
  if(auth === null) return;
  const ok = await confirmarBonito({
    titulo: 'Vaciar Resueltos',
    mensaje: 'Se borrarán para siempre '+resueltos.length+' pendiente(s) resuelto(s), sin esperar los 35 días.\n\nEsta acción no se puede deshacer.',
    btnSi: 'Sí, borrar todo', btnNo: 'Cancelar', peligro: true
  });
  if(!ok) return;
  resueltos.forEach(function(p){ _marcarPendEliminadoLocal(p.id); });
  const idsBorrar = new Set(resueltos.map(function(p){ return p.id; }));
  D.pendientes = (D.pendientes||[]).filter(function(p){ return !(p && idsBorrar.has(p.id)); });
  filtroP = 'activos';
  const btn = $('pendBtnResueltos'); const btnVaciar = $('pendBtnVaciarResueltos');
  if(btn){ btn.textContent = '✓ Resueltos'; btn.style.background='var(--surface)'; btn.style.color='var(--muted)'; }
  if(btnVaciar) btnVaciar.style.display = 'none';
  save();renderPend();badges();syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
  toast('🗑 '+resueltos.length+' resuelto(s) borrado(s) para siempre — autorizó '+auth.nombre);
}
// ── Inferir sección a partir de categoría legacy (para pendientes sin seccion explícita)
function _inferirSeccion(categoria){
  if(!categoria) return 'otros';
  const c=String(categoria).toLowerCase();
  if(c==='placas'||c.includes('placa')||c.includes('tenencia')) return 'placas';
  if(c==='escritura'||c.includes('escritura')) return 'escrituras';
  if(c==='juicio'||c.includes('juicio')||c.includes('amparo')) return 'juicios';
  return 'otros';
}
// ── Resolver la sección efectiva de un pendiente (con fallback)
function _seccionDe(p){
  return p.seccion || _inferirSeccion(p.categoria);
}
// ── Cambiar de sección (panel principal)
function setPSec(sec, el){
  filtroSeccion = sec;
  document.querySelectorAll('#panel-pendientes .pend-sec-btn').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('#pend-todas-btn').forEach(b=>b.classList.remove('active'));
  if (sec === 'todas') {
    const btn = document.getElementById('pend-todas-btn');
    if (btn) btn.classList.add('active');
  } else {
    const btn = document.querySelector('#panel-pendientes .pend-sec-btn[data-sec="'+sec+'"]');
    if (btn) btn.classList.add('active');
  }
  // Mostrar botones de estado solo en sección Placas
  const estadoBtns = document.getElementById('placas-estado-btns');
  if (estadoBtns) estadoBtns.style.display = (sec === 'placas') ? 'flex' : 'none';
  // Los pendientes de Placas ya NO se crean a mano — se generan solos al
  // registrar un recibo de trámite vehicular (sincronizarPendientesPlacas) y
  // desaparecen solos al liquidarse o cancelarse. Se oculta "+ Nuevo" aquí.
  const btnNuevo = document.getElementById('pendBtnNuevo');
  if (btnNuevo) btnNuevo.style.display = (sec === 'placas') ? 'none' : '';
  // "Resueltos" (y su botón de vaciar) es propio de Pendientes generales —
  // Placas se identifica por folio de recibo, no aplica el concepto de
  // "resuelto" manual, así que se ocultan en esa sección.
  const btnResueltos = document.getElementById('pendBtnResueltos');
  if (btnResueltos) btnResueltos.style.display = (sec === 'placas') ? 'none' : '';
  if (sec === 'placas') {
    const btnVaciar = document.getElementById('pendBtnVaciarResueltos');
    if (btnVaciar) btnVaciar.style.display = 'none';
    if (filtroP === 'resuelto') filtroP = 'activos';
  }
  // Caja grande con el total de pendientes de la sección activa. Antes solo
  // se mostraba en Placas ("N PENDIENTES"); a Pendientes generales le
  // faltaba el mismo total — ahora se muestra en ambas.
  const countBox = document.getElementById('pendPlacasCountBox');
  if (countBox) countBox.style.display = 'flex';
  renderPend();
}
// ── Estatus automático por antigüedad (días desde el alta del pendiente) ──
// Reemplaza la necesidad de marcar prioridad a mano: la tarjeta escala sola
// mientras más tiempo lleve sin resolverse, así ningún pendiente viejo queda
// "oculto" con un estatus verde/normal solo porque nadie lo actualizó.
// Escala pedida por la Lic. Nahúm:
//   PENDIENTE  (amarillo #FFFF00): 0-29 días  (menos de 1 mes)
//   URGENTE    (naranja #FFA500): 30-59 días (1 a 2 meses)
//   CRÍTICO    (rojo    #FF0000): 60-89 días (2 a 3 meses)
//   ABANDONADO (negro   #000000): 90+ días   (más de 3 meses)
function _pendDiasAbierto(p, hoyStr){
  if(!p || !p.fechaCreacion) return 0;
  const f = String(p.fechaCreacion).slice(0,10);
  const t1 = new Date(f+'T00:00:00').getTime();
  const t2 = new Date(String(hoyStr).slice(0,10)+'T00:00:00').getTime();
  if(isNaN(t1) || isNaN(t2)) return 0;
  return Math.max(0, Math.floor((t2-t1)/86400000));
}
// Mismo estilo que los botones de estado por entidad (Oaxaca/Edo.Méx/CDMX/
// Michoacán): el efecto de esos botones se logra con un fondo OSCURO y
// saturado del color (como si el color puro se viera encima de una capa
// negra), borde de un tono más claro del mismo color, y texto en un tono
// brillante del mismo color — nada de fondo plano brillante ni de badge
// pálido, que es justo lo que se perdía en la tarjeta antes.
// Mapa único reutilizado tanto para el cálculo automático por antigüedad
// como para la selección manual desde el botón "🔄 Estatus".
const _PEND_ESTADOS = {
  pendiente:  { key:'pendiente',  label:'PENDIENTE',  rango:'0-29 días',   icon:'📋', bg:'#5a4a08', border:'#9a8420', fg:'#f5dc70' },
  urgente:    { key:'urgente',    label:'URGENTE',    rango:'30-59 días',  icon:'⚠️', bg:'#5a3a0a', border:'#a8621a', fg:'#f5a855' },
  critico:    { key:'critico',    label:'CRÍTICO',    rango:'60-89 días',  icon:'🔴', bg:'#5a1a1a', border:'#aa2a2a', fg:'#f07a7a' },
  abandonado: { key:'abandonado', label:'ABANDONADO', rango:'90+ días',    icon:'🚫', bg:'#1c1c1c', border:'#4a4a4a', fg:'#d8d8d8' }
};
function _pendEstadoPorClave(key){
  return _PEND_ESTADOS[key] || _PEND_ESTADOS.pendiente;
}
function _pendEstadoPorEdad(dias){
  if(dias >= 90) return _PEND_ESTADOS.abandonado;
  if(dias >= 60) return _PEND_ESTADOS.critico;
  if(dias >= 30) return _PEND_ESTADOS.urgente;
  return _PEND_ESTADOS.pendiente;
}
// Botón "✈ Enviar" en las tarjetas de Pendientes de Placas: solo el
// administrador puede presionarlo; en cuanto lo hace, TODOS (empleadas
// incluidas) ven "✈ Enviado" en su lugar en esa misma tarjeta.
function _pendEsAdminGlobal(){
  return typeof empleadoActual!=='undefined' && empleadoActual
    && typeof ADMIN_EMAIL!=='undefined'
    && (empleadoActual.email||'').toLowerCase()===ADMIN_EMAIL.toLowerCase();
}
function _pendMarcarEnviado(idx){
  const p = D.pendientes[idx];
  if(!p) return;
  p.enviado = true;
  p.enviadoFecha = (typeof hoy==='function') ? hoy() : new Date().toISOString().slice(0,10);
  p.enviadoPor = (typeof empleadoActual!=='undefined' && empleadoActual) ? (empleadoActual.nombre||empleadoActual.email) : '';
  save();
  if(typeof syncEstadoSupabaseDebounced==='function') syncEstadoSupabaseDebounced().catch(()=>{});
  // Se reproduce la animación del avión de papel SOBRE la tarjeta (sin mover
  // ni recolorear nada de lo que ya había) y, al terminar, se vuelve a
  // renderizar para dejar fijo el ícono de "✈ Enviado" — ese sí se queda
  // estable para que cualquiera que abra la tarjeta vea que ya se envió.
  _pendAnimarEnvio(idx, function(){
    renderPend();
    if(typeof toast==='function') toast('✈ Marcado como enviado');
  });
}
// Estilos de la animación de envío — se inyectan una sola vez.
let _pendEstiloEnvioListo = false;
function _pendInyectarEstiloEnvio(){
  if(_pendEstiloEnvioListo) return;
  _pendEstiloEnvioListo = true;
  const css = '@keyframes _pendEnvioTrazo{to{stroke-dashoffset:0;}}'
    + '@keyframes _pendEnvioVuelo{0%{left:4%;top:62%;transform:rotate(-6deg);}100%{left:52%;top:16%;transform:rotate(8deg);}}'
    + '@keyframes _pendEnvioTexto{0%{opacity:0;transform:translateX(-6px);}25%{opacity:1;transform:translateX(0);}82%{opacity:1;}100%{opacity:0;}}'
    + '@keyframes _pendEnvioFade{0%{opacity:1;}80%{opacity:1;}100%{opacity:0;}}'
    + '._pend-envio-overlay{position:absolute;inset:0;background:rgba(253,250,244,0.96);pointer-events:none;overflow:hidden;z-index:6;animation:_pendEnvioFade 1.9s ease forwards;}'
    + '._pend-envio-trail{position:absolute;left:5%;top:6%;width:42%;height:80%;}'
    + '._pend-envio-trail path{fill:none;stroke:#26265c;stroke-width:2.5;stroke-dasharray:7 8;stroke-dashoffset:400;stroke-linecap:round;animation:_pendEnvioTrazo 1.15s ease forwards;}'
    + '._pend-envio-avion{position:absolute;width:26px;height:26px;animation:_pendEnvioVuelo 1.15s ease forwards;}'
    + '._pend-envio-texto{position:absolute;left:56%;top:34%;font-family:serif;font-style:italic;font-weight:700;font-size:14px;color:#c8951a;opacity:0;animation:_pendEnvioTexto 1.7s ease 0.35s forwards;white-space:nowrap;}';
  const styleEl = document.createElement('style');
  styleEl.textContent = css;
  document.head.appendChild(styleEl);
}
// Dibuja la animación del avión de papel (mismo ícono que queda fijo en
// "✈ Enviado") volando sobre una estela punteada azul marino, encima de la
// tarjeta del pendiente — sin desplazar ni recolorear ningún elemento ya
// existente. Al terminar (≈1.9s) llama cb() para refrescar la tarjeta con
// el estado final "Enviado" ya fijo.
function _pendAnimarEnvio(idx, cb){
  _pendInyectarEstiloEnvio();
  const card = document.querySelector('[data-pend-idx="'+idx+'"]');
  if(!card){ if(cb) cb(); return; }
  card.style.position = 'relative';
  const overlay = document.createElement('div');
  overlay.className = '_pend-envio-overlay';
  overlay.innerHTML =
    '<svg class="_pend-envio-trail" viewBox="0 0 400 90" preserveAspectRatio="none"><path d="M10,70 Q120,10 300,35"/></svg>'
    + '<svg class="_pend-envio-avion" viewBox="0 0 24 24"><defs><linearGradient id="_pendPlaneGrad" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#ffd166"/><stop offset="100%" stop-color="#f2994a"/></linearGradient></defs><path d="M2 12L22 2L14 22L11 14L2 12Z" fill="url(#_pendPlaneGrad)"/></svg>'
    + '<span class="_pend-envio-texto">Trámite enviado...</span>';
  card.appendChild(overlay);
  setTimeout(function(){ overlay.remove(); if(cb) cb(); }, 1900);
}
function renderPend(){
  if(typeof _pendPurgarResueltosViejos==='function') _pendPurgarResueltosViejos();
  const q=($('pendQ')?.value||'').toLowerCase();
  const hoy2=hoy();
  const _esAdminPend = _pendEsAdminGlobal();
  // ── Contadores por sección (sobre pendientes ACTIVOS, para badges visuales)
  const cntSec = { placas:0, escrituras:0, juicios:0, otros:0 };
  (D.pendientes||[]).filter(p=>!p.resuelto).forEach(p=>{
    const s = _seccionDe(p);
    if (cntSec[s] !== undefined) cntSec[s]++;
  });
  const setTxt=(id,v)=>{ const e=document.getElementById(id); if(e) e.textContent = v+' activo'+(v===1?'':'s'); };
  setTxt('pend-cnt-placas',     cntSec.placas);
  setTxt('pend-cnt-escrituras', cntSec.escrituras);
  setTxt('pend-cnt-juicios',    cntSec.juicios);
  setTxt('pend-cnt-otros',      cntSec.otros);
  setTxt('pend-cnt-todas', cntSec.placas + cntSec.escrituras + cntSec.juicios + cntSec.otros);
  // ── Aplicar filtro de sección
  const baseList = (D.pendientes||[]).filter(p=>{
    if (filtroSeccion === 'todas') return true;
    // 'manual' = todo excepto placas (pendientes agregados manualmente: juicios, escrituras, otros)
    if (filtroSeccion === 'manual') return _seccionDe(p) !== 'placas';
    return _seccionDe(p) === filtroSeccion;
  });
  // Stats (respetan la sección activa)
  const total=baseList.filter(p=>!p.resuelto).length;
  const urgentes=baseList.filter(p=>!p.resuelto&&p.prioridad==='urgente').length;
  const vencidos=baseList.filter(p=>!p.resuelto&&p.fechaLimite&&p.fechaLimite<hoy2).length;
  const resueltos=baseList.filter(p=>p.resuelto).length;
  // FIX: el cuadro de total (antes solo visible/actualizado en la sección
  // Placas, mostrando "N PENDIENTES") ahora también se muestra y actualiza
  // en Pendientes generales — usa "total" (activos de la sección
  // actualmente seleccionada: Placas o Pendientes manuales) en vez de
  // fijarse siempre en cntSec.placas.
  const _badgePlacasTot = document.getElementById('pendPlacasTotalNum');
  if (_badgePlacasTot) _badgePlacasTot.textContent = total;
  // Stats row removed — always show activos only
  // Filtro de prioridad/estado
  let l=baseList.filter(p=>{
    if(filtroP==='activos')return!p.resuelto;
    if(filtroP==='resuelto')return p.resuelto;
    if(filtroP==='urgente')return!p.resuelto&&p.prioridad==='urgente';
    if(filtroP==='medio')return!p.resuelto&&p.prioridad==='medio';
    if(filtroP==='normal')return!p.resuelto&&p.prioridad==='normal';
    if(filtroP==='vencidos')return!p.resuelto&&p.fechaLimite&&p.fechaLimite<hoy2;
    return true;
  }).filter(p=>!q||(p.texto||'').toLowerCase().includes(q)||(p.obs||'').toLowerCase().includes(q)||(p.carpeta||'').includes(q)||(p.persona||'').toLowerCase().includes(q)||(p.placasNumero||'').toLowerCase().includes(q));
  const el=$('listaPend');
  if(!l.length){
    const msgSec = filtroSeccion!=='todas' ? ' en la sección "'+filtroSeccion.charAt(0).toUpperCase()+filtroSeccion.slice(1)+'"' : '';
    el.innerHTML='<div style="color:var(--muted);padding:32px;text-align:center;font-size:0.76rem;">✓ Sin pendientes en este filtro'+msgSec+'</div>';
    return;
  }
  const priColor={'urgente':'#c0161a','medio':'#b07010','normal':'#1a7a3a'};
  const priBg={'urgente':'rgba(192,22,26,0.08)','medio':'rgba(176,112,16,0.09)','normal':'rgba(26,122,58,0.08)'};
  const priDot={'urgente':'#c0161a','medio':'#d4900a','normal':'#1a9a4a'};
  // Numeración DINÁMICA de Activos (18/ago/2026, a petición del usuario —
  // reemplaza la "ficha fija" del 15-17/ago). Ya NO se guarda para siempre:
  // se recalcula en cada render como la posición por antigüedad entre los
  // pendientes ACTIVOS (no resueltos, sin contar Placas). Al resolver uno,
  // los demás se recorren solos y el hueco se cierra. Un pendiente nuevo, o
  // uno restablecido desde "Resueltos", usa como clave de orden su
  // fechaReactivacion (si existe) en vez de fechaCreacion, así que siempre
  // cae al final — el número más alto.
  const _pendNumMapa = (function(){
    const activos = (D.pendientes || []).filter(pp => pp && !pp.resuelto && !(pp.seccion==='placas'||pp.reciboVinculadoFolio));
    const orden = activos
      .map((pp,i)=>({pp,i,k: pp.fechaReactivacion || pp.fechaCreacion || ''}))
      .sort((a,b)=> a.k<b.k?-1:a.k>b.k?1:a.i-b.i);
    const mapa = new Map();
    orden.forEach((x,pos)=>{ mapa.set(x.pp, pos+1); });
    return mapa;
  })();
  // Orden de pantalla: en Activos, número descendente (el más reciente
  // arriba). En Resueltos ya no hay número — se ordenan por la fecha en que
  // se marcaron resueltos, más reciente primero.
  if (filtroP === 'resuelto') {
    l = l.slice().sort((a,b) => String(b.fechaResuelto||'').localeCompare(String(a.fechaResuelto||'')));
  } else {
    l = l.slice().sort((a,b) => (_pendNumMapa.get(b)||0) - (_pendNumMapa.get(a)||0));
  }
  el.innerHTML=l.map(p=>{
    const idx=D.pendientes.indexOf(p);
    // En Placas no se muestra: esas tarjetas ya se identifican por su folio
    // de recibo (folioBadgeHtml, más abajo). En Resueltos tampoco se muestra
    // ningún número.
    const _numAntig=(p.seccion==='placas'||p.reciboVinculadoFolio||p.resuelto) ? '' : (_pendNumMapa.get(p)||'');
    const priLabel={'urgente':'Urgente','medio':'Medio','normal':'Normal'}[p.prioridad]||p.prioridad;
    const col=priColor[p.prioridad]||'var(--muted)';
    const bg=priBg[p.prioridad]||'transparent';
    const dot=priDot[p.prioridad]||'#888';
    // Estatus por antigüedad — automático (_pendEstadoPorEdad) salvo que se
    // haya fijado a mano desde el botón "🔄 Estatus" (p.estadoManual), en
    // cuyo caso ese valor manda hasta que se regrese a "Automático".
    const _diasAbierto = _pendDiasAbierto(p, hoy2);
    const _edad = p.estadoManual ? _pendEstadoPorClave(p.estadoManual) : _pendEstadoPorEdad(_diasAbierto);
    const edadBadgeHtml = `<div title="${_diasAbierto} día${_diasAbierto===1?'':'s'} en pendiente${p.fechaCreacion?' (alta: '+esc(p.fechaCreacion)+')':''}${p.estadoManual?' · fijado a mano':''}" style="display:inline-flex;align-items:center;gap:6px;background:${_edad.bg};border:1px solid ${_edad.border};border-radius:7px;padding:6px 13px;">
      <span style="font-size:12px;">${_edad.icon}</span>
      <span style="font-size:11px;font-weight:800;color:${_edad.fg};letter-spacing:0.03em;font-family:monospace;">${_edad.label} · ${_diasAbierto}d</span>
    </div>`;
    // Botón "Enviar" (solo Placas): mientras NO se ha enviado, el admin ve
    // el botón azul con el avión para presionarlo. En cuanto se envía, ese
    // botón azul desaparece para siempre — lo que se queda fijo y visible
    // para todos es solo el dibujo del avión (sin fondo azul, sin botón),
    // igual que se ve al final de la animación.
    const _pendAvionMiniSvg = `<svg width="15" height="15" viewBox="0 0 24 24" style="flex-shrink:0;"><defs><linearGradient id="_pendPlaneGradEnv${idx}" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#ffd166"/><stop offset="100%" stop-color="#f2994a"/></linearGradient></defs><path d="M2 12L22 2L14 22L11 14L2 12Z" fill="url(#_pendPlaneGradEnv${idx})"/></svg>`;
    let enviarBtnHtml = '';
    let enviadoImgHtml = '';
    let enviadoFechaHtml = '';
    if(p.seccion==='placas' || p.reciboVinculadoFolio){
      if(p.enviado){
        enviadoImgHtml = `<img src="data:image/png;base64," alt="Trámite enviado" title="${p.enviadoPor?'Enviado por '+esc(p.enviadoPor):'Enviado'}${p.enviadoFecha?' · '+esc(p.enviadoFecha):''}" style="height:100%;max-height:64px;width:auto;max-width:190px;object-fit:contain;display:block;">`;
        if(p.enviadoFecha){
          const _pendMesesEnv = ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
          const _pendFEnv = String(p.enviadoFecha).split('-');
          if(_pendFEnv.length===3){
            enviadoFechaHtml = _pendFEnv[2]+'-'+(_pendMesesEnv[parseInt(_pendFEnv[1],10)-1]||'')+'-'+_pendFEnv[0];
          }
        }
      } else if(_esAdminPend){
        enviarBtnHtml = `<span onclick="event.stopPropagation();_pendMarcarEnviado(${idx})" title="Marcar como enviado (lo verán todos)" style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;padding:6px 13px;border-radius:20px;background:#0c447c;color:#fff;cursor:pointer;">✈ Enviar</span>`;
      }
    }
    let fechaHtml='';
    if(p.fechaLimite){
      let vencida=p.fechaLimite<hoy2, hoyF=p.fechaLimite===hoy2;
      let fclr=vencida?'#c0161a':hoyF?'#b07010':'var(--muted)';
      let ficon=vencida?'⚠':'📅'; let flbl=vencida?('Vencido '+p.fechaLimite):hoyF?'Hoy':p.fechaLimite;
      fechaHtml=`<span style="font-size:0.65rem;color:${fclr};font-family:monospace;">${ficon} ${flbl}</span>`;
    }
    const altaHtml=p.fechaCreacion?`<span style="font-size:0.63rem;color:var(--muted);font-family:monospace;">Alta: ${p.fechaCreacion}</span>`:'';
    const carpHtml=p.carpeta?`<span style="font-size:0.63rem;background:rgba(200,149,42,0.1);color:var(--gold-d);border-radius:3px;padding:1px 5px;">🗂 #${esc(p.carpeta)}</span>`:'';
    const catHtml=p.categoria?`<span style="font-size:0.63rem;background:rgba(100,100,200,0.08);color:#446;border-radius:3px;padding:1px 5px;">${esc(p.categoria)}</span>`:'';
    // ── Ficha grande y clicable del folio vinculado (solo pendientes de Placas) ──
    // Reemplaza el pill de prioridad + los botones Estatus/Consultar recibo:
    // un solo badge grande con el folio real (folio+letra) que al hacer clic
    // abre directo la ficha correspondiente.
    let folioBadgeHtml = '';
    if (p.reciboVinculadoFolio) {
      const _recVinc = (typeof appData!=='undefined' && Array.isArray(appData.recibos))
        ? appData.recibos.find(function(r){ return r && Number(r.folio)===Number(p.reciboVinculadoFolio); })
        : null;
      const _letraVinc = (_recVinc && _recVinc.letra) || 'A';
      const _strVinc = (typeof folioConLetra==='function')
        ? folioConLetra(p.reciboVinculadoFolio, _recVinc && _recVinc.anio_folio, _letraVinc)
        : (p.reciboVinculadoFolio + _letraVinc);
      folioBadgeHtml = `<div onclick="event.stopPropagation();abrirFichaDesdeContab(${p.reciboVinculadoFolio})" title="Abrir ficha del folio" style="cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;background:transparent;padding:2px 6px;transition:opacity 0.15s;" onmouseover="this.style.opacity='0.7'" onmouseout="this.style.opacity='1'">
        <span style="font-size:8px;font-weight:700;color:#8c6518;letter-spacing:0.12em;">FOLIO</span>
        <span style="font-size:1.2rem;font-weight:800;color:#1a4a8a;line-height:1.15;font-family:monospace;">${esc(_strVinc)}</span>
      </div>`;
    }
    // Sección — solo se muestra el chip cuando estamos en vista "todas" (en otras vistas la sección ya es la del filtro)
    const _secInfo = { placas:{ico:'🚗',lbl:'Placas',c:'#1a4a8a',bg:'rgba(26,74,138,0.1)'}, escrituras:{ico:'📄',lbl:'Escrituras',c:'#7a4a00',bg:'rgba(122,74,0,0.08)'}, juicios:{ico:'⚖️',lbl:'Juicios',c:'#5a1a6a',bg:'rgba(90,26,106,0.1)'}, otros:{ico:'🗂',lbl:'Otros',c:'#555',bg:'rgba(0,0,0,0.05)'} };
    const _secAct = _seccionDe(p);
    const secHtml = (filtroSeccion === 'todas' && _secInfo[_secAct]) ? `<span style="font-size:0.63rem;background:${_secInfo[_secAct].bg};color:${_secInfo[_secAct].c};border-radius:3px;padding:1px 6px;font-weight:700;">${_secInfo[_secAct].ico} ${_secInfo[_secAct].lbl}</span>` : '';
    // ── INFO ESPECÍFICA DE PLACAS ─────────────────────────────────
    let placasInfoHtml = '';
    if (_secAct === 'placas') {
      const _tipoLbl = {
        'alta':               'Alta',
        'baja':               'Baja',
        'cambio_propietario': 'Cambio prop.',
        'tarjeta_circulacion':'Tarjeta circ.',
        'reemplacamiento':    'Reemplacamiento'
      };
      const chips = [];
      if (_tipoLbl[p.tipoVehicular]) chips.push(`<span style="font-size:9.5px;background:rgba(26,74,138,0.1);color:#0c447c;border-radius:3px;padding:1px 6px;font-family:monospace;font-weight:700;">🚗 ${_tipoLbl[p.tipoVehicular]}</span>`);
      if (p.placasEstado)     chips.push(`<span style="font-size:9.5px;background:#f1efe8;color:#444441;border-radius:3px;padding:1px 6px;font-family:monospace;">📍 ${esc(p.placasEstado)}</span>`);
      if (p.placasNumero)     chips.push(`<span style="font-size:9.5px;background:#faeeda;color:#633806;border-radius:3px;padding:1px 6px;font-family:monospace;font-weight:700;"># ${esc(p.placasNumero)}</span>`);
      if (p.reciboVinculadoFolio) chips.push(`<span style="font-size:9.5px;background:rgba(26,122,58,0.08);color:#27500a;border-radius:3px;padding:1px 6px;font-family:monospace;cursor:pointer;" onclick="event.stopPropagation();_irAReciboVinculado('${esc(String(p.reciboVinculadoFolio))}')" title="Abrir recibo">🧾 #${esc(folioFormato(p.reciboVinculadoFolio))}</span>`);
      if (p.vehMarca||p.vehClase) chips.push(`<span style="font-size:9.5px;background:#f1efe8;color:#444441;border-radius:3px;padding:1px 6px;font-family:monospace;">${esc(((p.vehMarca||'')+' '+(p.vehClase||'')).trim())}</span>`);
      // Badge estatus de carpeta vinculada en Drive (expediente digital) —
      // igual que en _expDigRenderStatus, si ya hay algún documento con
      // driveFileId (subido antes de que existiera el marcado automático),
      // se considera vinculado de facto aunque estatusGestion no lo diga.
      const docsArr = p.documentos||[];
      const _yaVinculado = p.estatusGestion === 'vinculado' || p.estatusGestion === 'enviado' || docsArr.some(d=>d&&d.driveFileId);
      if (_yaVinculado) {
        chips.push(`<span style="font-size:9.5px;background:#d4f5e0;border:1px solid #2a9a50;color:#0a4020;border-radius:10px;padding:2px 8px;font-family:monospace;font-weight:700;">✅ CARPETA VINCULADA${p.expDigitalFechaEnvio?' · '+p.expDigitalFechaEnvio:''}</span>`);
      } else {
        chips.push(`<span style="font-size:9.5px;background:#fff3e0;border:1px solid #c8952a;color:#7a4010;border-radius:10px;padding:2px 8px;font-family:monospace;font-weight:700;">⏳ SIN VINCULAR</span>`);
      }
      const docsHtml = docsArr.map((d,di)=>{
        const nm=d.nombre||d||'doc'; const lbl=nm.length>18?nm.substring(0,18)+'…':nm;
        const st=_docEstilo(nm, d && d.tipo);
        return `<span style="font-size:9.5px;background:${st.bg};border:1px solid ${st.borde};border-radius:4px;padding:2px 7px;color:${st.texto};cursor:pointer;display:inline-flex;align-items:center;gap:3px;" onclick="event.stopPropagation();_placasVerDocFromCard(${idx},${di})" title="${esc(nm)}">${st.icono} ${esc(lbl)}</span>`;
      }).join('');
      const adjuntarBtn = `<span id="placas-adj-btn-${idx}" style="font-size:11px;border:1.5px solid #a07848;border-radius:4px;padding:3px 10px;color:#fff;background:#c4955a;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-weight:600;" onclick="event.stopPropagation();_placasAdjuntarDoc(${idx})">+ Adjuntar</span>`;
      placasInfoHtml = `<div style="margin-top:6px;">${chips.length?`<div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:5px;">${chips.join('')}</div>`:''}<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;align-items:center;"><span style="font-size:9px;font-family:monospace;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8c6518;margin-right:2px;">Docs:</span>${docsHtml}${adjuntarBtn}</div></div>`;
    }
    // ── INFO ESPECÍFICA DE ESCRITURAS ─────────────────────────────
    let escInfoHtml = '';
    if (_secAct === 'escrituras' && (p.escComprador || p.escEtapa || (p.escDocumentos||[]).length)) {
      const _etapaLbl = {
        'firma_libro_notario':       { ico:'📝', txt:'Firma libro Notario' },
        'tramite_catastro':          { ico:'🏛', txt:'Trámite catastro'   },
        'pago_traslado_municipal':   { ico:'💰', txt:'Pago traslado mun.' },
        'pago_isr':                  { ico:'📋', txt:'Pago ISR'           },
        'registro_publico_propiedad':{ ico:'🏠', txt:'Registro propiedad' },
        'en_notaria':                { ico:'🔏', txt:'En Notaría'         },
        'esperando_cedula':          { ico:'📄', txt:'Esperando cédula'   },
        'listo_para_entregar':       { ico:'✅', txt:'Listo para entregar' }
      };
      const e = _etapaLbl[p.escEtapa];
      const etapaChip = e ? `<span style="font-size:0.63rem;background:rgba(122,74,0,0.12);color:#7a4a00;border-radius:3px;padding:2px 7px;font-weight:700;">${e.ico} ${e.txt}</span>` : '';
      const compradorChip = p.escComprador ? `<span style="font-size:0.63rem;background:rgba(122,74,0,0.06);color:#7a4a00;border-radius:3px;padding:2px 6px;">🛒 ${esc(p.escComprador)}</span>` : '';
      const vendedorChip  = p.escVendedor ? `<span style="font-size:0.63rem;background:rgba(122,74,0,0.06);color:#7a4a00;border-radius:3px;padding:2px 6px;">📤 ${esc(p.escVendedor)}</span>` : '';
      const archivoChip = p.escArchivoFisico ? `<span style="font-size:0.63rem;background:rgba(0,0,0,0.05);color:var(--ink);border-radius:3px;padding:2px 6px;font-family:monospace;">📁 ${esc(p.escArchivoFisico)}</span>` : '';
      const folioChip = p.escFolio ? `<span style="font-size:0.63rem;background:rgba(200,149,42,0.13);color:#8c6518;border-radius:3px;padding:2px 6px;font-family:monospace;font-weight:700;">🔖 ${esc(p.escFolio)}</span>` : '';
      const volInsChip = (p.escVolumen || p.escInstrumento) ? `<span style="font-size:0.63rem;background:rgba(0,0,0,0.05);color:var(--ink);border-radius:3px;padding:2px 6px;font-family:monospace;">📚 V${esc(p.escVolumen||'—')} · I${esc(p.escInstrumento||'—')}</span>` : '';
      const notariaChip = p.escNotaria ? `<span style="font-size:0.63rem;background:rgba(0,0,0,0.04);color:var(--muted);border-radius:3px;padding:2px 6px;">🔏 ${esc(p.escNotaria.length>30 ? p.escNotaria.substring(0,30)+'…' : p.escNotaria)}</span>` : '';
      const docsChip = (p.escDocumentos||[]).length ? `<span style="font-size:0.63rem;background:rgba(122,74,0,0.08);color:#7a4a00;border-radius:3px;padding:2px 6px;cursor:pointer;" onclick="event.stopPropagation();abrirPendiente(${idx})" title="Ver documentos">📎 ${(p.escDocumentos||[]).length} archivo${(p.escDocumentos||[]).length===1?'':'s'}</span>` : '';
      // Financiero
      const costo = parseFloat(p.escCosto)||0;
      const cobrado = parseFloat(p.escCobrado)||0;
      const resto = costo > 0 ? (costo - cobrado) : null;
      let finRow = '';
      if (costo > 0) {
        const restoColor = resto <= 0 ? '#1a7a3a' : '#c0161a';
        const restoTxt = resto <= 0 ? '✅ LIQUIDADO' : `$${resto.toFixed(2)}`;
        finRow = `<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:5px;align-items:center;">
          <span style="font-size:0.63rem;background:rgba(26,122,58,0.08);color:#1a7a3a;border-radius:3px;padding:2px 7px;">💵 Total: $${costo.toFixed(2)}</span>
          <span style="font-size:0.63rem;background:rgba(26,122,58,0.06);color:#1a7a3a;border-radius:3px;padding:2px 6px;">✅ Cobrado: $${cobrado.toFixed(2)}</span>
          <span style="font-size:0.63rem;background:rgba(192,22,26,0.07);color:${restoColor};border-radius:3px;padding:2px 6px;font-weight:700;">⏳ Resta: ${restoTxt}</span>
          ${p.escServiciosComp ? `<span style="font-size:0.63rem;background:rgba(0,0,0,0.04);color:var(--muted);border-radius:3px;padding:2px 6px;">🔧 ${esc(p.escServiciosComp)}</span>` : ''}
        </div>`;
      }
      const descripcionLine = p.escDescripcion ? `<div style="font-size:0.74rem;color:var(--ink);margin-top:5px;line-height:1.45;">${esc(p.escDescripcion)}</div>` : '';
      const siguientePasoLine = p.escSiguientePaso ? `<div style="font-size:0.73rem;margin-top:6px;padding:6px 9px;background:rgba(200,149,42,0.08);border-left:3px solid var(--gold);border-radius:0 5px 5px 0;line-height:1.45;color:#6a4a00;"><strong style="font-size:0.6rem;letter-spacing:0.1em;text-transform:uppercase;font-family:monospace;color:#8c6518;">🧭 Siguiente paso:</strong><br>${esc(p.escSiguientePaso)}</div>` : '';
      escInfoHtml = `<div style="background:rgba(122,74,0,0.04);border:1px solid rgba(122,74,0,0.12);border-radius:6px;padding:8px 10px;margin-top:7px;">
        <div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center;">${etapaChip}${compradorChip}${vendedorChip}${archivoChip}${folioChip}${volInsChip}${notariaChip}${docsChip}</div>
        ${finRow}
        ${descripcionLine}
        ${siguientePasoLine}
      </div>`;
    }
    // ── INFO ESPECÍFICA DE JUICIOS ────────────────────────────────
    let juiInfoHtml = '';
    if (_secAct === 'juicios' && (p.juiCliente || p.juiExpediente || p.juiEtapa)) {
      const expChip = p.juiExpediente ? `<span style="font-size:0.63rem;background:rgba(90,26,106,0.12);color:#5a1a6a;border-radius:3px;padding:2px 7px;font-weight:700;font-family:monospace;">⚖️ ${esc(p.juiExpediente)}</span>` : '';
      const tipoChip = p.juiTipo ? `<span style="font-size:0.63rem;background:rgba(90,26,106,0.06);color:#5a1a6a;border-radius:3px;padding:2px 6px;">${esc(p.juiTipo)}</span>` : '';
      const etapaChip = p.juiEtapa ? `<span style="font-size:0.63rem;background:rgba(0,0,0,0.05);color:var(--ink);border-radius:3px;padding:2px 6px;">📊 ${esc(p.juiEtapa)}</span>` : '';
      const terminoChip = p.juiTermino ? `<span style="font-size:0.63rem;background:rgba(192,22,26,0.08);color:var(--rojo);border-radius:3px;padding:2px 6px;">⏰ ${esc(p.juiTermino)}</span>` : '';
      let audChip = '';
      if (p.juiAudiencia) {
        const audDate = String(p.juiAudiencia).replace('T',' ').substring(0,16);
        audChip = `<span style="font-size:0.63rem;background:rgba(176,112,16,0.08);color:#b07010;border-radius:3px;padding:2px 6px;font-family:monospace;">📅 ${esc(audDate)}</span>`;
      }
      const vincChip = (typeof p.juicioVinculadoIdx === 'number' && p.juicioVinculadoIdx >= 0) ? `<span style="font-size:0.63rem;background:rgba(26,122,58,0.08);color:var(--verde-d);border-radius:3px;padding:2px 6px;cursor:pointer;font-weight:700;" onclick="event.stopPropagation();_irAJuicio(${p.juicioVinculadoIdx})" title="Abrir en Juicios">🔗 Juicios</span>` : '';
      const descripcionLine = p.juiDescripcion ? `<div style="font-size:0.74rem;color:var(--ink);margin-top:4px;line-height:1.45;">${esc(p.juiDescripcion)}</div>` : '';
      juiInfoHtml = `<div style="background:rgba(90,26,106,0.04);border:1px solid rgba(90,26,106,0.12);border-radius:6px;padding:7px 10px;margin-top:7px;">
        <div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center;">${expChip}${tipoChip}${etapaChip}${terminoChip}${audChip}${vincChip}</div>
        ${descripcionLine}
      </div>`;
    }
    return `<div data-pend-idx="${idx}" style="position:relative;display:flex;align-items:stretch;background:var(--surface,#fdfaf4);border:1.5px solid var(--border-l,#d4b870);border-radius:8px;margin-bottom:8px;overflow:visible;opacity:${p.resuelto?'0.5':'1'};${p.resuelto?'filter:grayscale(0.3);':''}transition:box-shadow 0.15s,border-color 0.15s;">
      <div style="width:5px;background:${col};flex-shrink:0;border-radius:8px 0 0 8px;"></div>
      <div style="padding:10px 5px 10px 8px;display:flex;align-items:flex-start;padding-top:12px;flex-shrink:0;">
        ${(p.seccion==='placas'||p.reciboVinculadoFolio)?'':`<div onclick="event.stopPropagation();toggleP(${idx})" title="${p.resuelto?'Reabrir':'Marcar resuelto'}" style="width:18px;height:18px;border-radius:50%;border:2px solid ${p.resuelto?'#1a7a3a':col};background:${p.resuelto?'#1a7a3a':'transparent'};display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;color:#fff;font-size:0.65rem;transition:all 0.15s;">${p.resuelto?'✓':''}</div>`}
      </div>
      <div style="flex:1;min-width:0;padding:10px 6px 10px 4px;">
        ${(_numAntig||p.persona)?`<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px;">
          ${_numAntig?`<div title="N° de ficha — posición entre los pendientes activos, se recalcula solo" style="display:flex;flex-direction:column;align-items:center;line-height:1.05;flex-shrink:0;">
            <span style="color:#a8987a;font-size:6.5px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;">Pendiente</span>
            <span style="color:#8c6518;font-family:'JetBrains Mono',monospace;font-size:15px;font-weight:900;">${_numAntig}</span>
          </div>`:''}
          ${p.persona?`<div style="font-size:${(p.seccion==='placas'||p.reciboVinculadoFolio)?'14.5px':'13.5px'};font-weight:600;color:${col};font-family:'Outfit',sans-serif;letter-spacing:0.025em;text-transform:uppercase;opacity:0.92;">👤 ${esc(p.persona)}</div>`:''}
        </div>`:''}
        <div style="font-size:12.5px;font-weight:600;color:var(--ink,#1a1008);line-height:1.4;margin-bottom:5px;${p.resuelto?'text-decoration:line-through;':''}">${esc(p.texto)}</div>
        ${placasInfoHtml}
        ${escInfoHtml}
        ${juiInfoHtml}
        <div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:5px;align-items:center;">
          ${secHtml}${fechaHtml}${carpHtml}${catHtml}
        </div>
        ${p.obs?`<div style="font-size:10px;color:#7a4a10;font-style:italic;margin-top:4px;padding:4px 8px;background:rgba(200,149,42,0.07);border-radius:4px;line-height:1.4;">${esc(p.obs)}</div>`:''}
        ${p.creadoPor?`<div style="font-size:8.5px;color:#9a8a6a;margin-top:5px;padding-top:4px;border-top:1px dashed rgba(0,0,0,0.08);">📤 Subido por: <strong style="color:#6a5a3a;">${esc(p.creadoPor)}</strong>${p.fechaCreacion?` · ${esc(p.fechaCreacion)}`:''}</div>`:''}
        ${p.persona?_finResumen(p.persona, null):''}
      </div>
      ${enviadoImgHtml ? `<div style="display:flex;align-items:center;justify-content:center;padding:6px 8px;flex-shrink:0;align-self:stretch;"><div style="position:relative;display:inline-flex;">${enviadoImgHtml}${enviadoFechaHtml ? `<div style="position:absolute;top:74%;left:35%;font-family:monospace;font-size:0.58rem;font-weight:700;color:#8c6518;letter-spacing:0.03em;white-space:nowrap;">${enviadoFechaHtml}</div>` : ''}</div></div>` : ''}
      <div style="display:flex;flex-direction:column;align-items:flex-end;justify-content:space-between;padding:10px 10px 10px 4px;flex-shrink:0;gap:5px;">
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;">
          ${(p.seccion==='placas'||p.reciboVinculadoFolio) ? folioBadgeHtml : ''}
          <div style="display:flex;align-items:center;gap:6px;">
            ${enviarBtnHtml}
            ${edadBadgeHtml}
          </div>
        </div>
        <div style="display:flex;gap:4px;">
          ${(p.resuelto&&!(p.seccion==='placas'||p.reciboVinculadoFolio))?`<button onclick="event.stopPropagation();toggleP(${idx})" style="display:flex;align-items:center;gap:3px;background:rgba(26,122,58,0.08);border:1px solid #1a7a3a;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:9.5px;font-weight:700;color:#1a7a3a;transition:background 0.15s;" onmouseover="this.style.background='rgba(26,122,58,0.16)'" onmouseout="this.style.background='rgba(26,122,58,0.08)'" title="Regresar a Activos">↩️ Restablecer</button>`:''}
          ${(p.seccion==='placas'||p.reciboVinculadoFolio)?'':`<button onclick="event.stopPropagation();_pendEstatus(${idx},this)" style="display:flex;align-items:center;gap:3px;background:transparent;border:1px solid #b5d4f4;border-radius:5px;padding:3px 7px;cursor:pointer;font-size:9.5px;color:#1a4a8a;transition:background 0.15s;" onmouseover="this.style.background='#e6f1fb'" onmouseout="this.style.background='transparent'" title="Cambiar estatus">🔄 Estatus</button>
          <button onclick="event.stopPropagation();abrirPendiente(${idx})" style="display:flex;align-items:center;justify-content:center;background:transparent;border:1px solid var(--border-l,#d4b870);border-radius:5px;padding:3px 7px;cursor:pointer;font-size:9.5px;color:var(--muted);transition:all 0.15s;" onmouseover="this.style.borderColor='var(--gold)';this.style.color='var(--gold)'" onmouseout="this.style.borderColor='var(--border-l,#d4b870)';this.style.color='var(--muted)'" title="Editar">✏</button>`}
        </div>
      </div>
    </div>`;
  }).join('');
  // Espejo hacia la pestaña "Notas y Recordatorios" del expediente abierto en
  // Juicios (si está abierto) — mismo dato, dos vistas.
  try{
    if(typeof _juRenderNotas === 'function' && document.getElementById('mexp-notas-lista') && window._mexpIdxActual >= 0){
      _juRenderNotas(window._mexpIdxActual);
    }
  }catch(e){}
}
// Botón "🔄 Estatus" en la tarjeta de Pendientes (solo en Pendientes
// generales — en Placas este botón no existe, ver template de la tarjeta).
// Antes controlaba un campo (estatusTramite) que no se mostraba en ningún
// lado; ahora permite fijar A MANO el estatus por antigüedad (Pendiente/
// Urgente/Crítico/Abandonado) que se ve en el badge de la tarjeta, por si
// se necesita forzarlo antes de que cumpla los días correspondientes (o
// bajarlo). "🔄 Automático" regresa al cálculo por días.
function _pendEstatus(idx, btn){
  const p = D.pendientes[idx];
  if(!p) return;
  // Eliminar menú previo si existe
  const prev = document.getElementById('_pend-estatus-menu');
  if(prev){ prev.remove(); if(prev._idx===idx) return; }
  const menu = document.createElement('div');
  menu.id = '_pend-estatus-menu';
  menu._idx = idx;
  menu.style.cssText = 'position:fixed;z-index:9999;background:#fdfaf4;border:1.5px solid #d4b870;border-radius:9px;padding:8px;display:flex;flex-direction:column;gap:5px;box-shadow:0 6px 20px rgba(0,0,0,0.18);width:200px;';
  const encabezado = document.createElement('div');
  encabezado.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 0 3px;';
  const titulo = document.createElement('span');
  titulo.textContent = 'ESTATUS DE LA TARJETA';
  titulo.style.cssText = 'font-size:9px;font-weight:800;color:var(--muted);letter-spacing:0.08em;';
  const btnCerrar = document.createElement('span');
  btnCerrar.textContent = '✕';
  btnCerrar.title = 'Cerrar';
  btnCerrar.style.cssText = 'cursor:pointer;font-size:11px;font-weight:800;color:var(--muted);line-height:1;padding:2px 4px;border-radius:4px;';
  btnCerrar.onmouseover = ()=>{ btnCerrar.style.color = 'var(--rojo,#c0161a)'; };
  btnCerrar.onmouseout  = ()=>{ btnCerrar.style.color = 'var(--muted)'; };
  btnCerrar.onclick = ()=>{ menu.remove(); document.removeEventListener('click', close); };
  encabezado.appendChild(titulo);
  encabezado.appendChild(btnCerrar);
  menu.appendChild(encabezado);
  ['pendiente','urgente','critico','abandonado'].forEach(function(key){
    const o = _pendEstadoPorClave(key);
    const activo = p.estadoManual === key;
    const s = document.createElement('span');
    s.innerHTML = '<span style="display:flex;align-items:center;gap:7px;">' + o.icon + ' ' + o.label + '</span>'
      + '<span style="font-size:8.5px;font-weight:600;opacity:0.75;letter-spacing:0.03em;">' + o.rango + '</span>';
    s.style.cssText = `display:flex;align-items:center;justify-content:space-between;gap:7px;font-size:10.5px;padding:6px 10px;border-radius:7px;cursor:pointer;font-weight:800;font-family:monospace;background:${o.bg};color:${o.fg};border:1.5px solid ${activo?o.fg:o.border};`;
    s.onclick = ()=>{ p.estadoManual=key; save(); syncEstadoSupabaseDebounced().catch(()=>{}); renderPend(); menu.remove(); toast('Estatus fijado a '+o.label); };
    menu.appendChild(s);
  });
  const auto = document.createElement('span');
  auto.textContent = '🔄 Automático (por antigüedad)';
  auto.style.cssText = 'font-size:9.5px;padding:6px 10px;border-radius:7px;cursor:pointer;font-weight:700;font-family:monospace;background:transparent;border:1.5px dashed var(--border-l,#d4b870);color:var(--muted);text-align:center;margin-top:2px;';
  auto.onclick = ()=>{ delete p.estadoManual; save(); syncEstadoSupabaseDebounced().catch(()=>{}); renderPend(); menu.remove(); toast('Estatus vuelve a calcularse por antigüedad'); };
  menu.appendChild(auto);
  document.body.appendChild(menu);
  const r = btn.getBoundingClientRect();
  menu.style.top  = (r.bottom+6)+'px';
  menu.style.right = (window.innerWidth-r.right)+'px';
  const close = (e)=>{ if(!menu.contains(e.target)&&e.target!==btn){ menu.remove(); document.removeEventListener('click',close); } };
  setTimeout(()=>document.addEventListener('click',close),50);
}
function _placasVerDocFromCard(pendIdx, docIdx){
  const docs = (D.pendientes[pendIdx]||{}).documentos;
  const d = docs?.[docIdx];
  if(d) _pVerDoc(d, pendIdx, docIdx, docs);
}
// Caché en memoria de carpetas de Drive ya resueltas (root "Placas" y una
// por cliente) — evita repetir 2 búsquedas/creaciones en Drive cada vez que
// se adjunta un archivo más para el mismo cliente dentro de la misma sesión.
window._driveFolderCache = window._driveFolderCache || {};

function _placasAdjBtnEstado(idx, estado){
  // estado: 'normal' | 'subiendo'
  const btn = document.getElementById('placas-adj-btn-'+idx);
  if(!btn) return;
  if(estado==='subiendo'){
    btn.textContent = '⏳ Subiendo…';
    btn.style.opacity = '0.6';
    btn.style.pointerEvents = 'none';
    btn.style.cursor = 'default';
  } else {
    btn.textContent = '+ Adjuntar';
    btn.style.opacity = '';
    btn.style.pointerEvents = '';
    btn.style.cursor = 'pointer';
  }
}

// ── Nombre del archivo en Drive ───────────────────────────────────────────
// FIX (a petición expresa, 11-ago-2026): antes se anteponía
// `Date.now()+'_'+azar+'_'` al nombre, así que en Drive se veía
// "1786303656857_b0e4_TRAMITE_DE_PLACAS.pdf". Ese sello garantizaba que dos
// archivos NUNCA se llamaran igual, lo que volvía imposible detectar que ya
// habías subido el mismo documento: se guardaban las dos copias en silencio.
// Ahora se conserva el nombre real (solo se limpian caracteres problemáticos)
// y la duplicidad se resuelve preguntando, no inventando nombres distintos.
function _placasNombreLimpio(nombre){
  return String(nombre || 'archivo')
    .replace(/[\\/:*?"<>|]/g, '_')   // caracteres inválidos para un nombre de archivo
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 120) || 'archivo';
}
// Busca en la carpeta del cliente un archivo con exactamente ese nombre.
// Devuelve {id, name} si existe, o null. Ante cualquier fallo devuelve null
// (nunca bloquea la subida por un problema de consulta).
async function _placasBuscarEnDrive(nombreArchivo, token, carpetaCliente){
  try{
    const q = "name = '" + nombreArchivo.replace(/'/g, "\\'") + "' and '" + carpetaCliente + "' in parents and trashed = false";
    const url = 'https://www.googleapis.com/drive/v3/files?q=' + encodeURIComponent(q) + '&fields=files(id,name)&pageSize=1';
    const resp = await _sbConTimeout(fetch(url, { headers:{ Authorization:'Bearer '+token } }), 10000, 'Drive buscar '+nombreArchivo);
    if(!resp.ok) return null;
    const data = await resp.json();
    return (data.files && data.files.length) ? data.files[0] : null;
  }catch(e){
    console.warn('[Drive placas] no se pudo verificar duplicado de '+nombreArchivo+':', e && e.message);
    return null;
  }
}
// Nombre libre del tipo "documento (2).pdf", "documento (3).pdf"… para cuando
// el usuario decide conservar AMBOS archivos.
async function _placasNombreCopiaLibre(nombreArchivo, token, carpetaCliente){
  const punto = nombreArchivo.lastIndexOf('.');
  const base = punto > 0 ? nombreArchivo.slice(0, punto) : nombreArchivo;
  const ext  = punto > 0 ? nombreArchivo.slice(punto)   : '';
  for(let n = 2; n <= 50; n++){
    const cand = base + ' (' + n + ')' + ext;
    if(!(await _placasBuscarEnDrive(cand, token, carpetaCliente))) return cand;
  }
  return base + ' (' + Date.now() + ')' + ext;
}
// Sube UN archivo a Drive con timeout + 1 reintento acotado (no infinito) —
// si el primer intento falla o tarda, se reintenta una sola vez antes de
// rendirse y caer al respaldo base64. Devuelve {id, nombreArchivo} o null.
// `reemplazarId` (opcional): actualiza el contenido de ese archivo existente
// en vez de crear uno nuevo, conservando su nombre, su id y su enlace.
// Umbral a partir del cual hay que usar subida RESUMIBLE. La subida directa
// (multipart) de la API de Drive solo está soportada para cargas pequeñas
// (~5 MB); con archivos grandes falla o se corta. Por eso un PDF de 30 MB
// nunca podía llegar a Drive con el método anterior.
const _DRIVE_UMBRAL_RESUMIBLE = 4 * 1024 * 1024;

// PUT del contenido con XMLHttpRequest para poder reportar el porcentaje real
// de avance (fetch no expone progreso de subida).
function _placasPutConProgreso(sessionUri, file, onProgreso, timeoutMs){
  return new Promise(function(resolve, reject){
    const xhr = new XMLHttpRequest();
    xhr.open('PUT', sessionUri, true);
    xhr.setRequestHeader('Content-Type', file.type || 'application/octet-stream');
    xhr.timeout = timeoutMs;
    xhr.upload.onprogress = function(ev){
      if(ev.lengthComputable && typeof onProgreso === 'function'){
        onProgreso(Math.round(ev.loaded / ev.total * 100));
      }
    };
    xhr.onload = function(){
      if(xhr.status >= 200 && xhr.status < 300){
        let data = {};
        try{ data = JSON.parse(xhr.responseText || '{}'); }catch(e){}
        resolve(data);
      } else {
        reject(new Error('HTTP ' + xhr.status + ' ' + String(xhr.responseText||'').slice(0,200)));
      }
    };
    xhr.onerror   = function(){ reject(new Error('Error de red durante la subida')); };
    xhr.ontimeout = function(){ reject(new Error('La subida tardó demasiado')); };
    xhr.send(file);
  });
}

// Subida resumible: primero se abre una "sesión" (solo metadatos) y Google
// devuelve una URL temporal; el contenido se manda después a esa URL.
async function _placasSubirResumibleDrive(file, token, carpetaCliente, nombreArchivo, reemplazarId, onProgreso){
  const esReemplazo = !!reemplazarId;
  const url = esReemplazo
    ? 'https://www.googleapis.com/upload/drive/v3/files/'+reemplazarId+'?uploadType=resumable&fields=id'
    : 'https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id';
  const meta = esReemplazo ? {} : { name: nombreArchivo, parents: [carpetaCliente] };
  const inicio = await _sbConTimeout(fetch(url, {
    method: esReemplazo ? 'PATCH' : 'POST',
    headers: {
      Authorization: 'Bearer ' + token,
      'Content-Type': 'application/json; charset=UTF-8',
      'X-Upload-Content-Type':   file.type || 'application/octet-stream',
      'X-Upload-Content-Length': String(file.size)
    },
    body: JSON.stringify(meta)
  }), 20000, 'Drive iniciar subida '+nombreArchivo);
  if(!inicio.ok){
    throw new Error('No se pudo iniciar la subida (HTTP ' + inicio.status + ')');
  }
  const sessionUri = inicio.headers.get('Location') || inicio.headers.get('location');
  if(!sessionUri) throw new Error('Drive no devolvió la URL de subida');
  // Tiempo máximo proporcional al tamaño (base 60s + 15s por MB, tope 15 min),
  // porque un archivo de decenas de MB no cabe en el límite fijo de 20s.
  const mb = file.size / (1024*1024);
  const timeoutMs = Math.min(15*60*1000, Math.round(60000 + mb * 15000));
  const data = await _placasPutConProgreso(sessionUri, file, onProgreso, timeoutMs);
  return { id: data.id || reemplazarId, nombreArchivo };
}

async function _placasSubirArchivoDrive(file, token, carpetaCliente, nombreForzado, reemplazarId, onProgreso){
  const nombreArchivo = nombreForzado || _placasNombreLimpio(file.name);
  // Se guarda el detalle del último fallo para poder REGISTRARLO. Antes solo se
  // hacía console.warn, así que el panel "Errores del Sistema" de SCANSYS PRO
  // salía en cero aunque la subida hubiera fallado.
  let _ultimoDetalle = 'motivo desconocido';
  for(let intento=1; intento<=2; intento++){
    try{
      // Archivos grandes → subida resumible (la directa no los soporta).
      if(file.size > _DRIVE_UMBRAL_RESUMIBLE){
        return await _placasSubirResumibleDrive(file, token, carpetaCliente, nombreArchivo, reemplazarId, onProgreso);
      }
      let resp;
      if(reemplazarId){
        // Reemplazo: solo se sustituye el contenido del archivo ya existente.
        resp = await _sbConTimeout(fetch('https://www.googleapis.com/upload/drive/v3/files/'+reemplazarId+'?uploadType=media&fields=id',{
          method:'PATCH', headers:{ Authorization:'Bearer '+token, 'Content-Type': file.type || 'application/octet-stream' }, body:file
        }), 20000, 'Drive reemplazo '+file.name);
      } else {
        const form = new FormData();
        form.append('metadata', new Blob([JSON.stringify({name:nombreArchivo,parents:[carpetaCliente]})],{type:'application/json'}));
        form.append('file', file);
        resp = await _sbConTimeout(fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink',{
          method:'POST', headers:{Authorization:'Bearer '+token}, body:form
        }), 20000, 'Drive subida '+file.name);
      }
      if(resp.ok){
        const data = await resp.json();
        return { id: data.id || reemplazarId, nombreArchivo };
      }
      const _cuerpo = await resp.text().catch(function(){ return ''; });
      _ultimoDetalle = 'HTTP ' + resp.status + (resp.statusText ? ' ' + resp.statusText : '') + (_cuerpo ? ' — ' + _cuerpo.slice(0,300) : '');
      // 401 = token vencido a media subida: no tiene caso reintentar igual
      if(resp.status === 401){
        if(typeof registrarError === 'function') registrarError('Placas · subida a Drive',
          new Error('Token de Drive rechazado (401) al subir "'+nombreArchivo+'"'),
          { archivo:nombreArchivo, bytes:file.size, tipo:file.type||'', detalle:_ultimoDetalle });
        return null;
      }
    }catch(e){
      _ultimoDetalle = (e && e.message) || String(e);
      console.warn('[Drive placas] intento '+intento+'/2 falló para '+file.name+':', _ultimoDetalle);
    }
  }
  // Se agotaron los intentos: ahora SÍ queda asentado en "Errores del Sistema".
  if(typeof registrarError === 'function') registrarError('Placas · subida a Drive',
    new Error('No se pudo subir "'+nombreArchivo+'" tras 2 intentos: '+_ultimoDetalle),
    { archivo:nombreArchivo, bytes:file.size, mb:(file.size/1024/1024).toFixed(1)+' MB', tipo:file.type||'', reemplazo:!!reemplazarId, detalle:_ultimoDetalle });
  return null;
}
// Diálogo de duplicado — 3 opciones reales (confirm() solo permite 2).
// Devuelve 'reemplazar' | 'copia' | 'cancelar'.
function _placasPreguntarDuplicado(nombreArchivo, nombreCliente){
  return new Promise(function(resolve){
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(10,6,2,0.72);display:flex;align-items:center;justify-content:center;padding:20px;';
    const card = document.createElement('div');
    card.style.cssText = 'background:#fdfaf3;border:2px solid #c8952a;border-radius:12px;max-width:520px;width:100%;padding:22px;font-family:monospace;box-shadow:0 18px 50px rgba(0,0,0,0.5);';
    card.innerHTML =
      '<div style="font-size:0.95rem;font-weight:700;color:#8c6518;margin-bottom:10px;">Este archivo ya existe en Drive</div>'
      + '<div style="font-size:0.78rem;color:#3a2a10;line-height:1.6;margin-bottom:6px;">En la carpeta de <strong>' + escHTML(nombreCliente) + '</strong> ya hay un archivo llamado:</div>'
      + '<div style="font-size:0.8rem;color:#1a1008;background:#f3ead6;border:1px solid #e0cfa8;border-radius:6px;padding:8px 10px;margin-bottom:14px;word-break:break-all;">' + escHTML(nombreArchivo) + '</div>'
      + '<div style="font-size:0.72rem;color:#6a5230;line-height:1.6;margin-bottom:16px;">¿Qué quieres hacer?</div>'
      + '<div style="display:flex;flex-direction:column;gap:8px;">'
      + '<button data-op="reemplazar" style="padding:11px;border-radius:7px;border:1.5px solid #a0560a;background:#a0560a;color:#fff;font-family:inherit;font-size:0.76rem;font-weight:700;cursor:pointer;">Reemplazar el que ya está</button>'
      + '<button data-op="copia" style="padding:11px;border-radius:7px;border:1.5px solid #c8952a;background:#fff;color:#8c6518;font-family:inherit;font-size:0.76rem;font-weight:700;cursor:pointer;">Guardar los dos (se renombra como copia)</button>'
      + '<button data-op="cancelar" style="padding:11px;border-radius:7px;border:1.5px solid #bbb;background:#fff;color:#666;font-family:inherit;font-size:0.76rem;cursor:pointer;">No subir este archivo</button>'
      + '</div>';
    ov.appendChild(card);
    document.body.appendChild(ov);
    card.addEventListener('click', function(ev){
      const op = ev.target && ev.target.getAttribute && ev.target.getAttribute('data-op');
      if(!op) return;
      try{ ov.remove(); }catch(e){}
      resolve(op);
    });
  });
}

function _placasLeerBase64(file){
  return new Promise(function(resolve,reject){
    const reader=new FileReader();
    reader.onloadend=function(){ resolve(reader.result); };
    reader.onerror=reject;
    reader.readAsDataURL(file);
  });
}

// Marca el folio como "carpeta vinculada en Drive" automáticamente en cuanto
// se sube EXITOSAMENTE al menos un archivo a esa carpeta — ya no hace falta
// un clic aparte en "Vincular Carpeta en Drive": si la carpeta ya existe y
// tiene contenido, ya está vinculada de facto. El botón manual de Expediente
// Digital solo queda para el caso de crear una carpeta vacía de antemano,
// antes de adjuntar el primer archivo.
function _marcarExpDigitalVinculado(folio, carpetaId){
  if(!folio || !carpetaId || typeof appData==='undefined' || !Array.isArray(appData.recibos)) return;
  const fecha = new Date().toLocaleDateString('es-MX',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).split('/').reverse().join('-');
  const url = 'https://drive.google.com/drive/folders/' + carpetaId;
  appData.recibos.forEach(function(rv){
    if(Number(rv.folio) === Number(folio)){
      if(!rv.expDigital) rv.expDigital = {};
      rv.expDigital.estatus = 'vinculado';
      rv.expDigital.driveFolderId = carpetaId;
      rv.expDigital.driveFolderUrl = url;
      rv.expDigital.fecha = fecha;
    }
  });
}

// Vuelve a localizar el pendiente SIEMPRE de forma fresca dentro de
// D.pendientes. Es indispensable porque entre que el usuario da clic en
// "+ Adjuntar" y termina de elegir el archivo en el explorador pueden pasar
// muchos segundos, y en ese lapso una sincronización de fondo REEMPLAZA el
// arreglo D.pendientes completo. La referencia vieja queda huérfana: se le
// empujaban los documentos a un objeto que ya no forma parte de los datos, y
// al guardar no se persistía nada (síntoma: "elijo el archivo y no pasa nada").
function _placasResolverPend(pendId, idxOrig){
  if(typeof D === 'undefined' || !Array.isArray(D.pendientes)) return null;
  if(pendId){
    const porId = D.pendientes.find(function(x){ return x && x.id === pendId; });
    if(porId) return porId;
  }
  return D.pendientes[idxOrig] || null;
}
// Aviso fijo de progreso (el toast normal se esconde solo a los 3.2s, muy poco
// para una subida). Se llama con null para quitarlo.
function _placasProgreso(texto){
  let el = document.getElementById('_placasProgresoBox');
  if(texto === null || texto === undefined || texto === false){ if(el) el.remove(); return; }
  if(!el){
    el = document.createElement('div');
    el.id = '_placasProgresoBox';
    el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:100001;background:#1a1008;border:1.5px solid #c8952a;color:#f7e9cb;border-radius:10px;padding:11px 22px;font-family:monospace;font-size:0.8rem;font-weight:700;box-shadow:0 12px 34px rgba(0,0,0,0.5);letter-spacing:0.02em;';
    document.body.appendChild(el);
  }
  el.textContent = texto;
}
function _placasAdjuntarDoc(idx){
  let p=D.pendientes[idx];if(!p)return;
  const pendId = p.id || null;
  // FIX: los fetch a Drive (token, carpeta, subida) no tenían timeout — si
  // el Worker o Google tardaban en responder, el botón se quedaba "colgado"
  // indefinidamente y el usuario terminaba dando clic varias veces
  // (apilando intentos concurrentes) sin que nada terminara. Ahora cada
  // llamada de red tiene límite de tiempo, hay 1 reintento por archivo antes
  // de rendirse, las carpetas de Drive se cachean en memoria (no se buscan
  // de nuevo en cada adjunto), los archivos se suben en paralelo, y el botón
  // muestra en vivo que está trabajando (y no se puede volver a pulsar).
  const claveSub = pendId || ('idx:'+idx);
  if(window._placasSubiendo && window._placasSubiendo[claveSub]){
    toast('Ya se está subiendo un archivo para este pendiente, espera a que termine.','err');
    return;
  }
  const inp=document.createElement('input');
  inp.type='file';inp.accept='.pdf,.jpg,.jpeg,.png,.webp,.doc,.docx';inp.multiple=true;
  // FIX CRÍTICO: el input NO estaba insertado en el documento. Un <input
  // type="file"> suelto puede ser recolectado por el navegador mientras el
  // explorador de archivos sigue abierto, y entonces su evento "change" NUNCA
  // se dispara: el usuario elige el archivo y, literalmente, no ocurre nada
  // (ni mensaje, ni subida). Insertándolo oculto en el DOM el evento siempre
  // llega; se retira al terminar.
  inp.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;opacity:0;';
  document.body.appendChild(inp);
  const _quitarInput = function(){ try{ inp.remove(); }catch(e){} };
  // Si el usuario cancela el explorador, "change" no se dispara — se limpia el
  // input igualmente para no dejar basura acumulada en el documento.
  window.addEventListener('focus', function _limpiar(){
    setTimeout(function(){
      if(!inp.files || !inp.files.length) _quitarInput();
      window.removeEventListener('focus', _limpiar);
    }, 800);
  });
  inp.onchange=async function(){
    if(!inp.files||!inp.files.length){ _quitarInput(); return; }
    // Reubicar el pendiente AHORA (ver comentario de _placasResolverPend).
    p = _placasResolverPend(pendId, idx) || p;
    if(!p){
      toast('No se encontró el pendiente (¿se actualizó la lista?). Vuelve a intentar.','err');
      _quitarInput(); return;
    }
    if(!p.documentos)p.documentos=[];
    if(!window._placasSubiendo) window._placasSubiendo={};
    window._placasSubiendo[claveSub]=true;
    _placasAdjBtnEstado(idx,'subiendo');
    // Tope real de Drive para este flujo. Antes eran 10 MB fijos, lo que
    // rechazaba documentos normales de trámite (un PDF escaneado pasa de 30 MB
    // sin problema). Con subida resumible sí se pueden mandar completos.
    const MAX_BYTES = 200 * 1024 * 1024;
    // Sin Drive el archivo se guarda como respaldo local dentro del estado
    // sincronizado; ahí sí hay que ser estrictos o se infla la base de datos.
    const MAX_BYTES_LOCAL = 8 * 1024 * 1024;
    const _mb = function(b){ return (b/1024/1024).toFixed(1)+' MB'; };
    const TIPOS_VALIDOS = ['image/png','image/jpeg','image/jpg','image/webp','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
    const EXT_VALIDAS = ['.pdf','.jpg','.jpeg','.png','.webp','.doc','.docx'];
    const _extValida = function(nombre){
      const n = (nombre||'').toLowerCase();
      return EXT_VALIDAS.some(function(ext){ return n.endsWith(ext); });
    };
    const todos = Array.from(inp.files);
    // Validar tamaño/tipo ANTES de tocar la red — así los rechazos se saben
    // al instante, sin esperar a que termine ningún intento de subida.
    const archivos = [], rechazadosInicio = [];
    todos.forEach(function(file){
      if(file.size > MAX_BYTES){ rechazadosInicio.push(file.name+' ('+_mb(file.size)+', máximo 200 MB)'); return; }
      if(!TIPOS_VALIDOS.includes(file.type) && !_extValida(file.name)){ rechazadosInicio.push(file.name+' (tipo no válido)'); return; }
      archivos.push(file);
    });
    if(!archivos.length){
      toast('Ningún archivo válido: '+rechazadosInicio.join(', '), 'err');
      window._placasSubiendo[claveSub]=false; _placasAdjBtnEstado(idx,'normal');
      _quitarInput();
      return;
    }
    toast('Subiendo '+archivos.length+' archivo(s)...','ok');
    _placasProgreso('⏳ Subiendo '+archivos.length+' archivo(s)… no cierres esta ventana');
    try{
      // Resolver token y carpeta de Drive UNA sola vez para todo el lote,
      // reutilizando la carpeta del cliente si ya se resolvió antes en esta
      // sesión (caché en memoria). Cada paso con timeout de 10s.
      let token = '', carpetaCliente = '';
      const nombreCliente = (p.persona||p.nombre||'cliente').replace(/[^a-zA-Z0-9_\- ]/g,'_').substring(0,50);
      const cacheKey = 'Placas/'+nombreCliente;
      try{
        token = typeof driveGetAccessToken==='function' ? await _sbConTimeout(driveGetAccessToken(), 10000, 'Drive token') : '';
        if(token){
          if(window._driveFolderCache[cacheKey]){
            carpetaCliente = window._driveFolderCache[cacheKey];
          } else {
            const DRIVE_ROOT = '1TtVVL0Jbw6BFkwLw8Wo1LZfxLN0I_ndU';
            const carpetaPlacas = window._driveFolderCache['Placas'] ||
              await _sbConTimeout(driveObtenerOCrearCarpeta(token,'Placas',DRIVE_ROOT), 10000, 'Drive carpeta Placas');
            window._driveFolderCache['Placas'] = carpetaPlacas;
            carpetaCliente = await _sbConTimeout(driveObtenerOCrearCarpeta(token, nombreCliente, carpetaPlacas), 10000, 'Drive carpeta cliente');
            window._driveFolderCache[cacheKey] = carpetaCliente;
          }
        }
      }catch(e){
        console.warn('[Drive placas] preparación de carpeta falló o tardó demasiado, se usará respaldo base64:', e);
        if(typeof registrarError === 'function') registrarError('Placas · carpeta de Drive', e,
          { cliente:nombreCliente, paso:'obtener token / crear carpeta' });
        token=''; carpetaCliente='';
      }
      // Si Drive no está disponible se avisa EXPLÍCITAMENTE: antes el archivo
      // se guardaba solo en el respaldo local y el usuario lo daba por subido
      // a Drive ("no queda en Drive en ningún lugar").
      if(!token || !carpetaCliente){
        console.warn('[Drive placas] sin acceso a Drive — token:', !!token, 'carpeta:', !!carpetaCliente);
        if(typeof registrarError === 'function') registrarError('Placas · Drive no disponible',
          new Error('Se adjuntará solo como respaldo local: '+(!token ? 'no se obtuvo el token de Drive' : 'no se pudo resolver la carpeta del cliente')),
          { cliente:nombreCliente, token:!!token, carpeta:!!carpetaCliente });
        _placasProgreso('⚠️ Sin conexión con Drive — guardando respaldo local…');
      }

      // ── PASO 1: revisar duplicados y decidir, ANTES de subir nada ─────────
      // Se hace en secuencia (no en paralelo) porque cada duplicado abre un
      // diálogo y no tiene sentido apilar varios al mismo tiempo en pantalla.
      const plan = [];
      let cancelados = [];
      for(const file of archivos){
        const nombreLimpio = _placasNombreLimpio(file.name);
        let decision = { file, nombre: nombreLimpio, reemplazarId: null };
        if(token && carpetaCliente){
          const existente = await _placasBuscarEnDrive(nombreLimpio, token, carpetaCliente);
          if(existente){
            const op = await _placasPreguntarDuplicado(nombreLimpio, nombreCliente);
            if(op === 'cancelar'){ cancelados.push(nombreLimpio); continue; }
            if(op === 'reemplazar') decision.reemplazarId = existente.id;
            else decision.nombre = await _placasNombreCopiaLibre(nombreLimpio, token, carpetaCliente);
          }
        }
        plan.push(decision);
      }
      if(!plan.length){
        toast(cancelados.length ? 'No se subió nada — cancelaste ' + cancelados.length + ' archivo(s) duplicado(s)' : 'No hay archivos que subir', 'ok');
        return;
      }
      // ── PASO 2: subir EN PARALELO lo que quedó aprobado ───────────────────
      let _hechos = 0;
      const _totalPlan = plan.length;
      const _etiquetaLote = function(){ return _totalPlan>1 ? ' ('+_hechos+' de '+_totalPlan+' listos)' : ''; };
      const resultados = await Promise.all(plan.map(async function(d){
        const file = d.file;
        let _res = null;
        if(token && carpetaCliente){
          const _nomCorto = (d.nombre||file.name).length > 28 ? (d.nombre||file.name).slice(0,28)+'…' : (d.nombre||file.name);
          const r = await _placasSubirArchivoDrive(file, token, carpetaCliente, d.nombre, d.reemplazarId, function(pct){
            _placasProgreso('⏳ Subiendo '+_nomCorto+' — '+pct+'%'+_etiquetaLote());
          });
          if(r) _res = { file, ok:true, drive:true, driveFileId:r.id, nombreArchivo:r.nombreArchivo, reemplazo:!!d.reemplazarId };
        }
        if(!_res){
          // Respaldo base64 solo si el archivo es razonablemente chico: meter
          // decenas de MB en el estado sincronizado rompería la base de datos.
          if(file.size > MAX_BYTES_LOCAL){
            console.error('[Placas] Drive falló y el archivo es demasiado grande para respaldo local:', file.name, file.size);
            _res = { file, ok:false, motivo:'Drive no aceptó el archivo y pesa demasiado ('+_mb(file.size)+') para guardarlo localmente' };
          } else {
            try{
              const dataURL = await _placasLeerBase64(file);
              _res = { file, ok:true, drive:false, base64:dataURL, nombreArchivo:d.nombre };
            }catch(e){
              console.error('[Placas] fallo total al adjuntar '+file.name+':', e);
              _res = { file, ok:false };
            }
          }
        }
        _hechos++;
        return _res;
      }));
      _placasProgreso('💾 Guardando…');

      // Reubicar el pendiente OTRA VEZ justo antes de escribir: la subida pudo
      // durar varios segundos y una sincronización de fondo pudo reemplazar
      // D.pendientes en ese lapso (si se escribiera sobre la referencia vieja,
      // los documentos se perderían al guardar).
      const _pFresco = _placasResolverPend(pendId, idx);
      if(_pFresco && _pFresco !== p){
        if(!_pFresco.documentos) _pFresco.documentos = [];
        p = _pFresco;
      }

      let agregados=0, drive=0, base64=0, reemplazos=0;
      resultados.forEach(function(r){
        if(!r.ok) return;
        if(r.drive){
          // Si fue un REEMPLAZO, no se agrega otro renglón a la lista de
          // documentos: se actualiza el que ya estaba (mismo archivo en Drive).
          if(r.reemplazo){
            const yaEsta = (p.documentos||[]).find(function(d){
              return d && (d.driveFileId === r.driveFileId ||
                (d.drivePath||'').endsWith('/'+r.nombreArchivo));
            });
            if(yaEsta){
              yaEsta.nombre = r.nombreArchivo;
              yaEsta.tipo = r.file.type;
              yaEsta.driveFileId = r.driveFileId;
              yaEsta.drivePath = 'Placas/'+nombreCliente+'/'+r.nombreArchivo;
              reemplazos++; agregados++; drive++;
              return;
            }
          }
          // Se guarda el tamaño (bytes) para que el visor pueda mostrar el
          // porcentaje de carga sin tener que preguntárselo a Drive cada vez.
          p.documentos.push({nombre:r.nombreArchivo,tipo:r.file.type,bytes:r.file.size,driveFileId:r.driveFileId,drivePath:'Placas/'+nombreCliente+'/'+r.nombreArchivo});
          drive++;
        } else {
          p.documentos.push({nombre:r.nombreArchivo||r.file.name,tipo:r.file.type,base64:r.base64});
          base64++;
        }
        agregados++;
      });
      const fallidos = resultados.filter(function(r){ return !r.ok; }).map(function(r){
        return r.file.name + (r.motivo ? ' — ' + r.motivo : '');
      });

      if(drive>0 && p.reciboVinculadoFolio) _marcarExpDigitalVinculado(p.reciboVinculadoFolio, carpetaCliente);
      if(agregados>0){
        p.fechaMod = new Date().toISOString();
        save();renderPend();syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
      }
      const rechazados = rechazadosInicio.length + fallidos.length;
      const detalleFuente = drive && base64 ? ' ('+drive+' Drive, '+base64+' local)' : drive ? ' (Drive)' : base64 ? ' (local)' : '';
      const detalleDup = (reemplazos ? ', '+reemplazos+' reemplazado(s)' : '') + (cancelados.length ? ', '+cancelados.length+' omitido(s) por duplicado' : '');
      if(rechazados===0) toast(agregados+' archivo(s) adjuntado(s)'+detalleFuente+detalleDup+' ✓','ok');
      else toast(agregados+' adjuntado(s)'+detalleFuente+detalleDup+', '+rechazados+' rechazado(s): '+rechazadosInicio.concat(fallidos).join(', '), agregados>0?'ok':'err');
      if(base64>0 && drive===0){
        toast('⚠️ No se pudo subir a Google Drive: quedó solo el respaldo local. Revisa la conexión de Drive en Panel de Control.','err');
      }
    } catch(errAdj) {
      // FIX IMPORTANTE: este try NO tenía catch (solo finally). Cualquier error
      // aquí adentro se convertía en una promesa rechazada sin manejar: la
      // subida moría en silencio, sin mensaje y sin guardar nada — exactamente
      // el síntoma reportado. Ahora el error se ve y queda en la consola.
      console.error('[Placas] error al adjuntar:', errAdj);
      if(typeof registrarError === 'function') registrarError('Placas · adjuntar documento', errAdj,
        { pendiente: pendId || ('idx '+idx), cliente: (p && (p.persona||p.nombre)) || '' });
      toast('❌ Error al adjuntar: ' + ((errAdj && errAdj.message) || errAdj), 'err');
    } finally {
      _placasProgreso(null);
      _quitarInput();
      window._placasSubiendo[claveSub]=false;
      _placasAdjBtnEstado(idx,'normal');
      // Si el modal de Expediente Digital está abierto mostrando este mismo
      // pendiente (el adjunto se pudo haber iniciado desde ahí, ya que reusa
      // esta misma función), refrescar su lista de chips también — comparten
      // el mismo arreglo p.documentos, no hace falta recargar nada más. Se
      // compara por folio (no por referencia) porque D.pendientes puede
      // haberse reemplazado por una sincronización de fondo mientras tanto.
      if (typeof _expDigState !== 'undefined' && _expDigState.recibo && p
          && p.seccion === 'placas' && Number(p.reciboVinculadoFolio) === Number(_expDigState.recibo.folio)) {
        if (typeof _expDigRenderArchivos === 'function') _expDigRenderArchivos();
        if (typeof _expDigRenderStatus === 'function') _expDigRenderStatus();
      }
    }
  };
  inp.click();
}
async function toggleP(idx){
  const p=D.pendientes[idx];
  // Blindaje: un pendiente de Placas vinculado a un recibo no se marca
  // resuelto a mano — solo desaparece solo cuando el recibo se liquida o
  // se cancela (ver sincronizarPendientesPlacas).
  if(p && (p.seccion === 'placas' || p.reciboVinculadoFolio)){
    toast('Este pendiente se sincroniza con el recibo — no se marca resuelto a mano.');
    return;
  }
  // Restablecer: si ya estaba resuelto (viendo "🗑 Resueltos"), regresa a
  // Activos. fechaReactivacion queda como su nueva clave de orden, así que
  // en la numeración dinámica cae al final (número más alto), como si fuera
  // nuevo — no vuelve a su posición histórica original.
  if(p && p.resuelto){
    const auth2 = await pedirAutorizacion();
    if(auth2 === null) return;
    p.resuelto = false;
    p.fechaResuelto = null;
    p.fechaReactivacion = new Date().toISOString();
    p.fechaMod = new Date().toISOString();
    save();renderPend();badges();syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
    toast('↩️ Restablecido — autorizó '+auth2.nombre);
    return;
  }
  // Marcar como resuelto ya NO borra de inmediato (17/ago/2026, a petición
  // del usuario): se conserva 10 días en "🗑 Resueltos" por si hace falta
  // consultarlo, y de ahí se purga solo (ver _pendPurgarResueltosViejos).
  const auth = await pedirAutorizacion();
  if(auth === null) return;
  const ok = await confirmarBonito({
    titulo: 'Marcar como resuelto',
    mensaje: '"'+p.texto+'"\n\nSe quitará de la lista de activos. Se conserva 10 días en "Resueltos" y después se borra para siempre.',
    btnSi: 'Sí, marcar resuelto', btnNo: 'Cancelar', peligro: false
  });
  if(!ok) return;
  p.resuelto = true;
  p.fechaResuelto = hoy();
  p.fechaMod = new Date().toISOString();
  save();renderPend();badges();syncEstadoSupabaseDebounced().catch((e)=>{ registrarError('Promise catch vacio', e); });
  toast('✅ Resuelto — autorizó '+auth.nombre);
}
// ── Purga definitiva de pendientes resueltos con más de 10 días ────────────
// Complementa toggleP(): resolver ya no borra al instante, solo oculta de
// "Activos" y guarda fechaResuelto. Esta función corre en cada renderPend()
// y borra para siempre (ya sin marcha atrás) los que llevan >10 días
// resueltos — así "Resueltos" no crece sin límite.
function _pendPurgarResueltosViejos(){
  const lista = D.pendientes || [];
  const hoyMs = Date.parse(hoy() + 'T12:00:00');
  const _VENTANA_RETENCION_DIAS = 10;
  const aBorrar = lista.filter(function(p){
    if(!p || !p.resuelto || !p.fechaResuelto) return false;
    const fMs = Date.parse(p.fechaResuelto + 'T12:00:00');
    if(isNaN(fMs)) return false;
    const dias = Math.floor((hoyMs - fMs) / 86400000);
    return dias > _VENTANA_RETENCION_DIAS;
  });
  if(!aBorrar.length) return;
  aBorrar.forEach(function(p){ _marcarPendEliminadoLocal(p.id); });
  const idsBorrar = new Set(aBorrar.map(function(p){ return p.id; }));
  D.pendientes = lista.filter(function(p){ return !(p && idsBorrar.has(p.id)); });
  console.warn('[Pendientes] 🗑 Purgados '+aBorrar.length+' resuelto(s) con más de '+_VENTANA_RETENCION_DIAS+' días');
  save();
}
// ─── ABRIR MODAL PENDIENTE (nuevo o editar) ─────────────────────────────────
function abrirPendiente(idx){
  eiP = (idx !== undefined && idx >= 0) ? idx : -1;
  const p = eiP >= 0 ? D.pendientes[eiP] : null;
  const titulo = document.getElementById('mPendTitulo');
  const btnElim = document.getElementById('pBtnElim');
  if(titulo) titulo.textContent = p ? '✏ Editar Pendiente' : '📌 Nuevo Pendiente';
  // Los pendientes de Placas vinculados a un recibo YA NO se pueden eliminar
  // a mano — se sincronizan solos con sincronizarPendientesPlacas(): el
  // pendiente desaparece automáticamente en cuanto el recibo se liquida
  // (saldo en $0) o se cancela. Se oculta el botón "Eliminar" en ese caso.
  const _esPlacasVinculado = !!(p && (p.seccion === 'placas' || p.reciboVinculadoFolio));
  if(btnElim) btnElim.style.display = (p && !_esPlacasVinculado) ? 'inline-flex' : 'none';
  // La opción "🚗 Placas" del selector de sección solo debe quedar disponible
  // cuando se está viendo un pendiente de placas YA EXISTENTE (vinculado a un
  // recibo) — nunca al crear uno nuevo ni al editar uno de otra sección, para
  // que nadie pueda crear a mano un pendiente de placas "huérfano" que el
  // sincronizador nunca podría resolver ni eliminar automáticamente.
  const _opcionPlacas = document.getElementById('pSecOpcionPlacas');
  if(_opcionPlacas) _opcionPlacas.disabled = !_esPlacasVinculado;
  const _avisoSyncId = 'pAvisoSyncPlacas';
  document.getElementById(_avisoSyncId)?.remove();
  if(_esPlacasVinculado){
    const _ftr = document.querySelector('#mPendienteInner .modal-ftr');
    if(_ftr && _ftr.parentNode){
      const aviso = document.createElement('div');
      aviso.id = _avisoSyncId;
      aviso.style.cssText = 'font-size:0.68rem;color:#7a6840;background:rgba(200,149,42,0.08);border:1px solid rgba(200,149,42,0.25);border-radius:6px;padding:7px 12px;margin:0 18px 10px;line-height:1.4;';
      aviso.textContent = '🔒 Este pendiente se sincroniza con el recibo — desaparecerá solo cuando se liquide o se cancele.';
      _ftr.parentNode.insertBefore(aviso, _ftr);
    }
  }
  // Cerrar overlay de detalle si estuviera abierto
  document.getElementById('_det-pend-ov')?.remove();
  // Determinar sección — priorizar campo seccion guardado
  const secEl = document.getElementById('pSec');
  let sec = 'otros';
  if(p){
    if(p.seccion && ['placas','escrituras','juicios','otros'].includes(p.seccion)) sec = p.seccion;
    else if(p.tipoVehicular || p.placasEstado || p.placasNumero || p.descripcionPlacas) sec = 'placas';
    else if(p.escComprador || p.escEtapa) sec = 'escrituras';
    else if(p.juiExpediente || p.juiEtapa) sec = 'juicios';
  }
  if(secEl){ secEl.value = sec; pSecCambio(); }
  if(p){
    if(sec === 'placas') _pPlacasCargar(p);
    else if(sec === 'escrituras') _pEscCargar(p);
    else if(sec === 'juicios') _pJuiCargar(p);
    else {
      const _s=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v||'';};
      _s('pOtrosNombre',p.persona);_s('pOtrosDesc',p.obs||p.texto);
    }
    const priEl=document.getElementById('pPri');if(priEl)priEl.value=p.prioridad||'normal';
    const reEl=document.getElementById('pRe');if(reEl)reEl.value=p.resp||'Antonieta';
    const fEl=document.getElementById('pFecha');if(fEl)fEl.value=p.fechaLimite||'';
    const cEl=document.getElementById('pCarpeta');if(cEl)cEl.value=p.carpeta||'';
  } else {
    _pPlacasLimpiar();
    _pEscCargar(null);
    _pJuiCargar(null);
    ['pPri','pRe','pFecha','pCarpeta','pOtrosNombre','pOtrosDesc'].forEach(id=>{
      const e=document.getElementById(id);if(e)e.value = id==='pPri'?'normal':id==='pRe'?'Antonieta':'';
    });
  }
  const modal = document.getElementById('mPendiente');
  if(modal) modal.classList.add('show');
}
function guardarPend(){
  const sec = document.getElementById('pSec')?.value || 'otros';
  let especifico = {};
  if(sec === 'placas'){
    const d = _pPlacasRecopilar();
    if(!d.nombre){ toast('El nombre es obligatorio','err'); return; }
    if(!d.tipoVehicular){ toast('Selecciona el tipo de trámite','err'); return; }
    const _tipoTexto = {'alta':'Alta de placas','baja':'Baja de placas','cambio_propietario':'Cambio de propietario','tarjeta_circulacion':'Tarjeta de circulación','reemplacamiento':'Reemplacamiento'}[d.tipoVehicular]||'Trámite vehicular';
    especifico = {
      id: (eiP>=0 && D.pendientes[eiP]?.id) || ('P-'+Date.now()),
      texto: _tipoTexto + ' — ' + d.nombre.toUpperCase(),
      persona: d.nombre, seccion:'placas',
      tipoVehicular: d.tipoVehicular, placasEstado: d.placasEstado,
      placasNumero: d.placasNumero, descripcionPlacas: d.descripcionPlacas,
      reciboVinculadoFolio: d.reciboVinculadoFolio, documentos: d.documentos,
      prioridad: document.getElementById('pPri')?.value||'normal',
      resp: document.getElementById('pRe')?.value||'Antonieta',
      fechaLimite: document.getElementById('pFecha')?.value||'',
      carpeta: document.getElementById('pCarpeta')?.value.trim()||''
    };
  } else if(sec === 'escrituras'){
    const d = _pEscRecopilar();
    if(!d.escDescripcion){ toast('La descripción es obligatoria','err'); return; }
    especifico = Object.assign({
      id: (eiP>=0 && D.pendientes[eiP]?.id) || ('P-'+Date.now()),
      texto: d.escDescripcion,
      persona: d.escComprador || d.escVendedor || '',
      seccion: 'escrituras',
      prioridad: document.getElementById('pPri')?.value||'normal',
      resp: document.getElementById('pRe')?.value||'Antonieta',
      fechaLimite: document.getElementById('pFecha')?.value||'',
      carpeta: document.getElementById('pCarpeta')?.value.trim()||''
    }, d);
  } else if(sec === 'juicios'){
    const d = _pJuiRecopilar();
    if(!d.juiDescripcion){ toast('La descripción es obligatoria','err'); return; }
    especifico = Object.assign({
      id: (eiP>=0 && D.pendientes[eiP]?.id) || ('P-'+Date.now()),
      texto: d.juiDescripcion,
      persona: d.juiCliente || '',
      seccion: 'juicios',
      prioridad: document.getElementById('pPri')?.value||'normal',
      resp: document.getElementById('pRe')?.value||'Antonieta',
      fechaLimite: document.getElementById('pFecha')?.value||'',
      carpeta: document.getElementById('pCarpeta')?.value.trim()||''
    }, d);
  } else {
    const nombre = document.getElementById('pOtrosNombre')?.value.trim()||document.getElementById('pPersona')?.value.trim()||'';
    const desc   = document.getElementById('pOtrosDesc')?.value.trim()||document.getElementById('pTxt')?.value.trim()||'';
    if(!desc){ toast('La descripción es obligatoria','err'); return; }
    especifico = {
      id: (eiP>=0 && D.pendientes[eiP]?.id) || ('P-'+Date.now()),
      texto: desc, persona: nombre, seccion: sec,
      prioridad: document.getElementById('pPri')?.value||'normal',
      resp: document.getElementById('pRe')?.value||'Antonieta',
      fechaLimite: document.getElementById('pFecha')?.value||'',
      carpeta: document.getElementById('pCarpeta')?.value.trim()||'',
      obs: document.getElementById('pOb')?.value.trim()||''
    };
  }
  const prevP = eiP >= 0 ? D.pendientes[eiP] : null;
  const p = _construirPendienteBase(prevP, especifico);
  _persistirPendiente(p, sec==='placas'?'Pendiente de placas guardado ✓':'Pendiente guardado ✓');
}
