// HELPERS COMPARTIDOS para adjuntar/ver documentos
// ═══════════════════════════════════════════════════════════════
function _pAdjuntarArchivos(event, lista, renderFn){
  const files = event.target.files;
  if (!files || !files.length) return;
  const MAX_BYTES = 5 * 1024 * 1024;
  let agregados = 0, rechazados = 0;
  let pendientes = files.length;
  Array.from(files).forEach(file => {
    if (file.size > MAX_BYTES) {
      rechazados++; pendientes--;
      if (pendientes === 0) _pPlacasMostrarResultadoSubida(agregados, rechazados);
      return;
    }
    const tiposValidos = ['image/png','image/jpeg','image/jpg','application/pdf'];
    if (!tiposValidos.includes(file.type)) {
      rechazados++; pendientes--;
      if (pendientes === 0) _pPlacasMostrarResultadoSubida(agregados, rechazados);
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      lista.push({
        nombre: file.name, tipo: file.type, tamano: file.size,
        fechaSubida: hoy(), dataURL: e.target.result
      });
      agregados++; pendientes--;
      if (renderFn) renderFn();
      if (pendientes === 0) _pPlacasMostrarResultadoSubida(agregados, rechazados);
    };
    reader.onerror = () => {
      rechazados++; pendientes--;
      if (pendientes === 0) _pPlacasMostrarResultadoSubida(agregados, rechazados);
    };
    reader.readAsDataURL(file);
  });
  event.target.value = '';
}
// Contexto actual del visor de documentos
window._docPreviewCtx = null;
window._docZoomLevel  = 1;
const _DOC_ZOOM_STEPS = [0.25, 0.5, 0.75, 1, 1.25, 1.5, 2, 2.5, 3];
// Abre el modal con soporte de navegación entre documentos del mismo grupo
// lista: array de documentos (opcional). Si se pasa, se activan las flechas.
function _pVerDoc(d, pendienteIdx, docIdx, lista){
  if (!d) return;
  // Resolver lista de docs según contexto
  let docList = lista || null;
  if (!docList && pendienteIdx !== undefined) {
    const p = (typeof D !== 'undefined' && D.pendientes) ? D.pendientes[pendienteIdx] : null;
    if (p && p.documentos && p.documentos.length > 1) docList = p.documentos;
  }
  window._docPreviewCtx = { d, pendienteIdx, docIdx, lista: docList };
  window._docZoomLevel  = 1;
  window._docPanOffset  = { x:0, y:0 };
  _pVerDocRender();
  document.getElementById('mDocPreview').classList.add('show');
}
function _pVerDocRender(){
  const ctx  = window._docPreviewCtx;
  if (!ctx || !ctx.d) return;
  const d    = ctx.d;
  const titulo = document.getElementById('docPreviewTitulo');
  const cont   = document.getElementById('docPreviewContenido');
  const btnDl  = document.getElementById('docPreviewBtnDescargar');
  const btnEl  = document.getElementById('docPreviewBtnEliminar');
  const counter= document.getElementById('docPreviewCounter');
  const btnPrev= document.getElementById('docPrevBtnPrev');
  const btnNext= document.getElementById('docPrevBtnNext');
  const zoomBar= document.getElementById('docZoomBar');
  const esPDF = d.tipo === 'application/pdf';
  if (titulo) titulo.textContent = (esPDF ? '📄 ' : '🖼 ') + d.nombre;
  if (btnDl) btnDl.style.display = 'inline-flex';
  if (btnEl) btnEl.style.display = ctx.pendienteIdx !== undefined ? 'inline-flex' : 'none';
  // Zoom: solo para imágenes
  if (zoomBar) zoomBar.style.display = esPDF ? 'none' : 'flex';
  window._docZoomLevel = 1;
  _docZoomUpdateLabel();
  // Contador y flechas
  const lista = ctx.lista;
  const idx   = ctx.docIdx;
  if (lista && lista.length > 1 && idx !== undefined) {
    if (counter) { counter.style.display = 'inline-block'; counter.textContent = (idx+1) + ' / ' + lista.length; }
    if (btnPrev) { btnPrev.style.display = 'flex'; btnPrev.disabled = idx <= 0; }
    if (btnNext) { btnNext.style.display = 'flex'; btnNext.disabled = idx >= lista.length - 1; }
  } else {
    if (counter) counter.style.display = 'none';
    if (btnPrev) btnPrev.style.display = 'none';
    if (btnNext) btnNext.style.display = 'none';
  }
  // Renderizar contenido
  if (cont) cont.innerHTML = '<div style="text-align:center;padding:40px;color:var(--muted);">Cargando…</div>';
  const src = d.dataURL || d.base64;
  function mostrarContenido(url){
    if (!cont) return;
    if (esPDF) {
      cont.innerHTML = '<iframe src="'+url+'#toolbar=1&navpanes=1&scrollbar=1" title="'+escHTML(d.nombre||'')+'" allowfullscreen></iframe>';
    } else {
      cont.innerHTML = '<img src="'+url+'" id="docPreviewImg" alt="'+escHTML(d.nombre||'')+'" style="max-width:100%;max-height:65vh;border-radius:4px;display:block;margin:0 auto;transform-origin:center center;">';
      // Wheel zoom
      cont.onwheel = function(e){ e.preventDefault(); _docZoom(e.deltaY < 0 ? 1 : -1); };
      // Pan / drag
      _docPanInit(cont);
    }
  }
  if (d.r2path && typeof window.descargarR2 === 'function') {
    window.descargarR2(d.r2path, d.bucket || 'placas').then(blob => {
      if (!blob) {
        if(cont) cont.innerHTML = '<p style="color:#c0161a;padding:20px;text-align:center;">No se pudo cargar el archivo.<br><small>Verifica tu conexión.</small></p>';
        return;
      }
      mostrarContenido(URL.createObjectURL(blob));
    }).catch(e => {
      if(cont) cont.innerHTML = '<p style="color:#c0161a;padding:20px;text-align:center;">Error al cargar desde R2.</p>';
      console.error('_pVerDoc R2:', e);
    });
  } else if (d.driveFileId) {
    // El archivo se descarga COMPLETO antes de poder mostrarse (un iframe no
    // puede ir mostrando un PDF a medias). Con documentos de decenas de MB eso
    // tarda, y antes solo se veía "Cargando…" sin saber si avanzaba o se había
    // trabado. Ahora se muestra el porcentaje real y un atajo para abrirlo
    // directo en Google Drive, que sí lo va mostrando mientras carga.
    const _urlDrive = 'https://drive.google.com/file/d/' + d.driveFileId + '/view';
    if (cont) cont.innerHTML =
        '<div style="text-align:center;padding:38px 20px;color:var(--muted);">'
      +   '<div id="docPrevProgTxt" style="font-family:monospace;font-size:0.8rem;">Cargando…</div>'
      +   '<div style="margin:12px auto 0;max-width:320px;height:7px;background:rgba(0,0,0,0.10);border-radius:4px;overflow:hidden;">'
      +     '<div id="docPrevProgBar" style="height:100%;width:0%;background:#c8952a;transition:width .12s linear;"></div>'
      +   '</div>'
      +   '<div style="margin-top:16px;font-size:0.72rem;line-height:1.6;">Los archivos grandes tardan porque se descargan completos.<br>'
      +     '<a href="' + _urlDrive + '" target="_blank" rel="noopener" style="color:#1a4a8a;font-weight:700;text-decoration:underline;">Abrirlo directamente en Google Drive ↗</a>'
      +   '</div>'
      + '</div>';
    // Tamaño del archivo: hace falta para calcular el porcentaje. La cabecera
    // Content-Length de la descarga NO es legible desde JavaScript (Google no la
    // expone por CORS), por eso antes el porcentaje nunca aparecía. Se pide
    // aparte a la API de Drive, que sí lo devuelve; es una consulta mínima.
    // Si el documento ya trae el tamaño guardado (d.bytes), se usa ese y ni
    // siquiera se hace la consulta.
    window._docPrevTotal = Number(d.bytes) || 0;
    driveGetAccessToken().then(function(token){
      if (!token) { if(cont) cont.innerHTML = '<p style="color:#c0161a;padding:20px;text-align:center;">Drive no conectado. Reconecta en Panel Admin.</p>'; return; }
      const _pedirTamano = window._docPrevTotal
        ? Promise.resolve(window._docPrevTotal)
        : fetch('https://www.googleapis.com/drive/v3/files/'+d.driveFileId+'?fields=size',{headers:{Authorization:'Bearer '+token}})
            .then(function(r){ return r.ok ? r.json() : null; })
            .then(function(j){ return (j && j.size) ? Number(j.size) : 0; })
            .catch(function(){ return 0; });
      return _pedirTamano.then(function(tam){
        window._docPrevTotal = tam || 0;
        return fetch('https://www.googleapis.com/drive/v3/files/'+d.driveFileId+'?alt=media',{headers:{Authorization:'Bearer '+token}});
      }).then(function(resp){
        // Un 401/403 aquí (a pesar de que driveGetAccessToken() sí devolvió
        // un token) significa que ese token es el viejo de respaldo y ya no
        // sirve — es la misma situación de "hay que reconectar Drive", solo
        // que se detectó en este punto en vez del refresh. Se avisa igual.
        if (resp && (resp.status === 401 || resp.status === 403) && typeof _driveMarcarDesconectado === 'function') {
          _driveMarcarDesconectado('Drive API respondió ' + resp.status);
        }
        return resp;
      });
    }).then(async function(resp){
      if (!resp || !resp.ok) throw new Error('No se pudo descargar de Drive');
      // Tamaño: primero el que se consultó a la API; si no, la cabecera (que casi
      // nunca es legible); si tampoco, se avanza mostrando solo los MB bajados.
      const total = window._docPrevTotal || parseInt(resp.headers.get('Content-Length') || '0', 10) || 0;
      if (!resp.body || typeof resp.body.getReader !== 'function') return resp.blob();
      const reader = resp.body.getReader();
      const partes = [];
      let recibido = 0;
      const elTxt = document.getElementById('docPrevProgTxt');
      const elBar = document.getElementById('docPrevProgBar');
      const _fmtMb = function(b){ return (b/1024/1024).toFixed(1); };
      for(;;){
        const paso = await reader.read();
        if (paso.done) break;
        partes.push(paso.value);
        recibido += paso.value.length;
        if (total){
          const pct = Math.min(100, Math.round(recibido / total * 100));
          if (elTxt) elTxt.textContent = 'Cargando… ' + pct + '%  (' + _fmtMb(recibido) + ' de ' + _fmtMb(total) + ' MB)';
          if (elBar) elBar.style.width = pct + '%';
        } else {
          // Sin tamaño conocido: se informa lo descargado y la barra avanza de
          // forma aproximada, sin llegar nunca al 100% hasta terminar de verdad.
          if (elTxt) elTxt.textContent = 'Cargando… ' + _fmtMb(recibido) + ' MB descargados';
          if (elBar) elBar.style.width = Math.min(92, Math.round(recibido / (recibido + 6*1024*1024) * 100)) + '%';
        }
      }
      if (elBar) elBar.style.width = '100%';
      if (elTxt) elTxt.textContent = 'Abriendo el documento…';
      return new Blob(partes, { type: d.tipo || 'application/octet-stream' });
    }).then(function(blob){
      mostrarContenido(URL.createObjectURL(blob));
    }).catch(function(e){
      const msg = window._driveNecesitaReconexion
        ? 'Google Drive necesita reconectarse (pide a un administrador que lo haga desde Panel de Control).'
        : 'Error al cargar desde Drive.';
      if(cont) cont.innerHTML = '<p style="color:#c0161a;padding:20px;text-align:center;">'+msg+'</p>';
      console.error('_pVerDoc Drive:', e);
    });
  } else if (src) {
    mostrarContenido(src);
  } else {
    if(cont) cont.innerHTML = '<p style="color:#c0161a;padding:20px;text-align:center;">Sin fuente de datos.</p>';
  }
}
// ── Zoom + Pan ────────────────────────────────────────────────
window._docPanOffset = { x:0, y:0 };
function _docZoom(dir){
  const steps = _DOC_ZOOM_STEPS;
  let i = steps.indexOf(window._docZoomLevel);
  if (i === -1) i = steps.indexOf(1);
  i = Math.max(0, Math.min(steps.length - 1, i + dir));
  window._docZoomLevel = steps[i];
  // Reset pan cuando vuelve a 100%
  if (window._docZoomLevel === 1) window._docPanOffset = { x:0, y:0 };
  _docZoomApply();
}
function _docZoomReset(){
  window._docZoomLevel  = 1;
  window._docPanOffset  = { x:0, y:0 };
  _docZoomApply();
}
function _docZoomApply(){
  const img  = document.getElementById('docPreviewImg');
  const cont = document.getElementById('docPreviewContenido');
  const z    = window._docZoomLevel;
  const { x, y } = window._docPanOffset;
  if (img) {
    img.style.transform  = 'translate('+x+'px,'+y+'px) scale('+z+')';
    img.style.maxWidth   = z > 1 ? 'none' : '100%';
    img.style.maxHeight  = z > 1 ? 'none' : '65vh';
    img.style.transition = 'transform 0.15s ease';
  }
  // Cursor: manita cuando hay zoom, normal cuando es 1:1
  if (cont) cont.style.cursor = z > 1 ? 'grab' : 'default';
  _docZoomUpdateLabel();
}
function _docZoomUpdateLabel(){
  const lbl = document.getElementById('docZoomLabel');
  if (lbl) lbl.textContent = Math.round(window._docZoomLevel * 100) + '%';
}
// ── Pan (arrastrar imagen con zoom) ──────────────────────────
function _docPanInit(cont){
  let dragging = false, startX, startY, originX, originY;
  cont.addEventListener('mousedown', function(e){
    if (window._docZoomLevel <= 1) return;
    dragging = true;
    startX = e.clientX; startY = e.clientY;
    originX = window._docPanOffset.x; originY = window._docPanOffset.y;
    cont.style.cursor = 'grabbing';
    e.preventDefault();
  });
  window.addEventListener('mousemove', function(e){
    if (!dragging) return;
    window._docPanOffset.x = originX + (e.clientX - startX);
    window._docPanOffset.y = originY + (e.clientY - startY);
    const img = document.getElementById('docPreviewImg');
    if (img) {
      const z = window._docZoomLevel;
      img.style.transition = 'none';
      img.style.transform  = 'translate('+window._docPanOffset.x+'px,'+window._docPanOffset.y+'px) scale('+z+')';
    }
  });
  window.addEventListener('mouseup', function(){
    if (!dragging) return;
    dragging = false;
    const cont2 = document.getElementById('docPreviewContenido');
    if (cont2) cont2.style.cursor = window._docZoomLevel > 1 ? 'grab' : 'default';
  });
  // Touch (móvil)
  let touchStart = null, touchOrigin = null;
  cont.addEventListener('touchstart', function(e){
    if (window._docZoomLevel <= 1 || e.touches.length !== 1) return;
    touchStart  = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    touchOrigin = { x: window._docPanOffset.x, y: window._docPanOffset.y };
  }, { passive:true });
  cont.addEventListener('touchmove', function(e){
    if (!touchStart || e.touches.length !== 1) return;
    window._docPanOffset.x = touchOrigin.x + (e.touches[0].clientX - touchStart.x);
    window._docPanOffset.y = touchOrigin.y + (e.touches[0].clientY - touchStart.y);
    const img = document.getElementById('docPreviewImg');
    const z   = window._docZoomLevel;
    if (img) { img.style.transition='none'; img.style.transform='translate('+window._docPanOffset.x+'px,'+window._docPanOffset.y+'px) scale('+z+')'; }
    e.preventDefault();
  }, { passive:false });
  cont.addEventListener('touchend', function(){ touchStart = null; });
}
// Navegación ◀ ▶
function _pVerDocNav(dir){
  const ctx = window._docPreviewCtx;
  if (!ctx || !ctx.lista) return;
  const newIdx = (ctx.docIdx || 0) + dir;
  if (newIdx < 0 || newIdx >= ctx.lista.length) return;
  ctx.docIdx = newIdx;
  ctx.d = ctx.lista[newIdx];
  window._docZoomLevel = 1;
  window._docPanOffset = { x:0, y:0 };
  _pVerDocRender();
}
// Teclado: flechas, +/-, Escape
document.addEventListener('keydown', function(e){
  const m = document.getElementById('mDocPreview');
  if (!m || !m.classList.contains('show')) return;
  if (e.key === 'ArrowLeft')  _pVerDocNav(-1);
  if (e.key === 'ArrowRight') _pVerDocNav(1);
  if (e.key === '+'||e.key==='=') _docZoom(1);
  if (e.key === '-')           _docZoom(-1);
  if (e.key === '0')           _docZoomReset();
  if (e.key === 'Escape')      cerrar('mDocPreview');
});
async function _pVerDocDescargar(){
  const ctx = window._docPreviewCtx;
  if (!ctx || !ctx.d) return;
  const d = ctx.d;
  try {
    let blob;
    if (d.driveFileId) {
      const token = await driveGetAccessToken();
      if (!token) { toast('Drive no conectado', 'err'); return; }
      const resp = await fetch('https://www.googleapis.com/drive/v3/files/'+d.driveFileId+'?alt=media',{headers:{Authorization:'Bearer '+token}});
      if (!resp.ok) throw new Error('Drive '+resp.status);
      blob = await resp.blob();
    } else if (d.r2path && typeof window.descargarR2 === 'function') {
      blob = await window.descargarR2(d.r2path, d.bucket || 'placas');
    } else if (d.dataURL || d.base64) {
      const res = await fetch(d.dataURL || d.base64);
      blob = await res.blob();
    }
    if (blob) {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = d.nombre; a.click();
      setTimeout(() => URL.revokeObjectURL(url), 2000);
    }
  } catch(e) { toast('Error al descargar', 'err'); }
}
async function _pVerDocEliminar(){
  const ctx = window._docPreviewCtx;
  if (!ctx || ctx.pendienteIdx === undefined) return;
  if (!confirm('¿Eliminar este archivo? Esta acción no se puede deshacer.')) return;
  const d = ctx.d;
  // Igual que al adjuntar: se relocaliza el pendiente por id, porque el borrado
  // en Drive tarda y una sincronización de fondo puede reemplazar D.pendientes.
  let p = D.pendientes[ctx.pendienteIdx];
  const _pendIdDel = p && p.id ? p.id : null;
  if (!p || !p.documentos) return;
  if (typeof _placasProgreso === 'function') _placasProgreso('🗑 Eliminando archivo…');
  try {
    // Borrar de Drive si tiene driveFileId
    if (d.driveFileId) {
      try {
        const token = await driveGetAccessToken();
        if (token) {
          const _pDel = fetch('https://www.googleapis.com/drive/v3/files/'+d.driveFileId,{method:'DELETE',headers:{Authorization:'Bearer '+token}});
          await (typeof _sbConTimeout === 'function' ? _sbConTimeout(_pDel, 15000, 'Drive eliminar') : _pDel);
        }
      } catch(e){ console.warn('[Drive placas] eliminar desde visor:', e); }
    }
    // Borrar de R2 si era doc antiguo
    if (d.r2path && typeof window.borrarR2 === 'function') {
      if (typeof _placasProgreso === 'function') _placasProgreso('🗑 Eliminando respaldo…');
      await window.borrarR2(d.r2path, d.bucket || 'placas').catch(e => console.warn('R2 borrar:', e));
    }
    if (typeof _placasResolverPend === 'function') {
      const _pFresco = _placasResolverPend(_pendIdDel, ctx.pendienteIdx);
      if (_pFresco && _pFresco.documentos) p = _pFresco;
    }
    if (typeof _placasProgreso === 'function') _placasProgreso('💾 Guardando…');
    p.documentos.splice(ctx.docIdx, 1);
    save(); renderPend();
    cerrar('mDocPreview');
    toast('Archivo eliminado', 'ok');
  } catch(errDel) {
    console.error('[Placas] error al eliminar documento:', errDel);
    if(typeof registrarError === 'function') registrarError('Placas · eliminar documento', errDel,
      { archivo: (d && d.nombre) || '', driveFileId: (d && d.driveFileId) || '' });
    toast('❌ Error al eliminar: ' + ((errDel && errDel.message) || errDel), 'err');
  } finally {
    if (typeof _placasProgreso === 'function') _placasProgreso(null);
  }
}
// ═══ PENDIENTE — autocompletado de nombre con folios ═══
function pPersonaInput(){
  const q=($('pPersona').value||'').trim().toLowerCase();
  const sug=document.getElementById('pPersonaSug');
  if(!sug) return;
  if(q.length < 2){ sug.style.display='none'; return; }
  // Buscar en recibos originales (no complementos)
  const src = (typeof appData!=='undefined'?appData:REC).recibos || [];
  // Agrupar por nombre: tomar el recibo más reciente por cliente
  const visto={};
  src.filter(r=>!r.esComplemento && r.nombre && r.nombre.toLowerCase().includes(q))
     .sort((a,b)=>b.folio-a.folio)
     .forEach(r=>{ if(!visto[r.nombre.toLowerCase()]) visto[r.nombre.toLowerCase()]=r; });
  const matches=Object.values(visto).slice(0,6);
  if(!matches.length){ sug.style.display='none'; return; }
  sug.innerHTML=matches.map(r=>`
    <div onclick="pSeleccionarPersona(${r.folio}, '${escHTML((r.nombre||'').replace(/'/g,"\\'"))}', '${escHTML((r.tramites||r.conceptos&&r.conceptos[0]&&r.conceptos[0].descripcion||'').replace(/'/g,"\\'").substring(0,40))}')"
      style="padding:8px 12px;cursor:pointer;border-bottom:1px solid var(--border-l);font-size:0.8rem;transition:background 0.1s;"
      onmouseover="this.style.background='var(--gold-pale)'" onmouseout="this.style.background=''">
      <span style="font-weight:600;color:var(--ink);">${escHTML(r.nombre||'')}</span>
      <span style="font-family:monospace;font-size:0.6rem;color:var(--gold-d);margin-left:8px;">Folio #${folioConLetra(r.folio, r.anio_folio, r.letra||letraVersion(r)||'A')}</span>
      <div style="font-size:0.65rem;color:var(--muted);margin-top:2px;">${escHTML(r.fecha||'')} · ${escHTML(r.tramites||'')}</div>
    </div>`).join('');
  sug.style.display='block';
}
function pSeleccionarPersona(folio, nombre, tramite){
  $('pPersona').value=nombre;
  // Autorellenar carpeta con el folio
  $('pCarpeta').value=folioFormato(folio);
  // Mostrar badge de folio vinculado
  const wrap=document.getElementById('pFolioVinculadoWrap');
  const info=document.getElementById('pFolioVinculadoInfo');
  if(wrap && info){
    const src=(typeof appData!=='undefined'?appData:REC).recibos||[];
    const r=src.find(x=>x.folio===folio);
    info.textContent='#'+folioFormato(folio)+' · '+nombre+(r&&r.fecha?' · '+fmtFecha(r.fecha):'');
    wrap.style.display='flex';
  }
  // Ocultar sugerencias
  const sug=document.getElementById('pPersonaSug');
  if(sug) sug.style.display='none';
}
function pLimpiarFolioVinculado(){
  const wrap=document.getElementById('pFolioVinculadoWrap');
  if(wrap) wrap.style.display='none';
  $('pCarpeta').value='';
}
