      costosExtra: (r.costosExtra||_s.costosExtra||[]).filter(function(ce){
        return !_esSinCostoPDF || ((ce&&ce.folioLetra||'').toUpperCase() === (r.letra||letraVersion(r)||'A').toUpperCase());
      }),
