// Marca que un movimiento (manual/caja, no de recibo) se acaba de editar
// localmente — usado por sincronizarFolio() para NO dejar que un pull de
// Supabase (polling de respaldo cada 30s, o broadcast Realtime de otro
// dispositivo/pestaña) revierta la edición mientras la subida debounced
// (syncEstadoSupabaseDebounced, 800ms) todavía no llega al servidor.
function _marcarMovEditadoLocal(id){
  if(!id) return;
  window._movsEditadosRecientemente = window._movsEditadosRecientemente || {};
  window._movsEditadosRecientemente[id] = Date.now();
}
// Misma idea que _marcarMovEditadoLocal pero para BORRADOS de movimientos
// manuales/caja (botón ✕ "Eliminar movimiento" en Borrar Cobro Específico).
// El borrado quita el id de D.movimientos en memoria y agenda la subida a
// Supabase 800ms después (vía guardarTodo→syncEstadoSupabaseDebounced) — si
// un pull llega antes (polling/Realtime), Supabase todavía tiene el
// movimiento viejo y, sin esta marca, el merge de sincronizarFolio() lo
// reinserta en D.movimientos, haciendo parecer que "no se guardó" el borrado.
function _marcarMovEliminadoLocal(id){
  if(!id) return;
  window._movsEliminadosRecientemente = window._movsEliminadosRecientemente || {};
  window._movsEliminadosRecientemente[id] = Date.now();
}
// Mismo patrón que _marcarMovEliminadoLocal, aplicado a pendientes: al marcar
// resuelto (toggleP) o eliminar (eliminarPend) ahora se borra el pendiente
// para siempre en memoria y se agenda el push a Supabase — si un pull llega
// antes de que ese push se confirme, sin esta marca el merge de
// sincronizarFolio() lo resucitaría con la copia vieja del servidor.
function _marcarPendEliminadoLocal(id){
  if(!id) return;
  window._pendsEliminadosRecientemente = window._pendsEliminadosRecientemente || {};
  window._pendsEliminadosRecientemente[id] = Date.now();
}
// Mismo patrón, para juicios (confirmarEliminarJuicio) y contactos del
// directorio (eliminarContacto) — ver uso en el merge de sincronizarFolio().
function _marcarJuicioEliminadoLocal(id){
  if(!id) return;
  window._juiciosEliminadosRecientemente = window._juiciosEliminadosRecientemente || {};
  window._juiciosEliminadosRecientemente[id] = Date.now();
}
function _marcarContactoEliminadoLocal(id){
  if(!id) return;
  window._contactosEliminadosRecientemente = window._contactosEliminadosRecientemente || {};
  window._contactosEliminadosRecientemente[id] = Date.now();
}
// Mismo patrón, para citas (citaEliminar y la auto-limpieza citasLimpiarPasadas).
// Caso real: se borra una cita (manual o por vencida) pero, con dos
// computadoras conectadas al mismo despacho (admin + empleada), el pull de
// alguna de las dos (polling de 30s, Realtime, o al entrar al panel) llegaba
// antes de que el push del borrado se confirmara en Supabase — el merge de
// sincronizarFolio() todavía veía la cita en la copia vieja del servidor y la
// resucitaba en D.citas. Por eso la cita "se borraba y luego volvía a
// aparecer".
function _marcarCitaEliminadaLocal(id){
  if(!id) return;
  window._citasEliminadasRecientemente = window._citasEliminadasRecientemente || {};
  window._citasEliminadasRecientemente[id] = Date.now();
}
function adminGuardarEdicion2Mov() {
  var id = document.getElementById('adminEdit2MovId').value;
  var idx = (D.movimientos || []).findIndex(function(m){ return m.id === id; });
  if(idx < 0){ if(typeof toast==='function') toast('Movimiento no encontrado','err'); return; }
  var monto = parseFloat(document.getElementById('adminEdit2MovMonto').value);
  if(isNaN(monto) || monto < 0){ if(typeof toast==='function') toast('Monto inválido','err'); return; }
  var m = D.movimientos[idx];
  m.descripcion = document.getElementById('adminEdit2MovDesc').value.trim() || m.descripcion;
  m.fecha       = document.getElementById('adminEdit2MovFecha').value || m.fecha;
  m.hora        = document.getElementById('adminEdit2MovHora').value || m.hora;
  m.monto       = monto;
  m.tipo        = document.getElementById('adminEdit2MovTipo').value;
  m.cat         = document.getElementById('adminEdit2MovCat').value;
  m.responsable = document.getElementById('adminEdit2MovResp').value.trim() || m.responsable;
  // Proteger esta edición de que un pull de Supabase (polling/Realtime) la
  // revierta antes de que la subida debounced de abajo termine de confirmarla.
  _marcarMovEditadoLocal(id);
  // Borrar historial de cambios previos del movimiento (registro limpio)
  m.historialCambios = [];
  // Registrar solo esta edición como referencia de auditoría
  m.historialCambios.push({
    tipo:'edicion_admin',
    fecha: typeof hoy==='function'?hoy():'',
    hora: typeof hora==='function'?hora():'',
    usuario: adminSesionUsuario||'Admin'
  });
  // ── Guardar en TODOS los lugares donde se refleja el movimiento ──────────
  // 1. localStorage + Drive principal (D.movimientos vive aquí)
  try { if(typeof backupLocal==='function') backupLocal('D', D); } catch(e){ registrarError('catch vacio', e); }
  // 2. Re-renderizar caja y contabilidad inmediatamente (UI consistente)
  if(typeof renderCaja==='function') renderCaja();
  if(typeof renderContab==='function') renderContab();
  // Indicador visual: botón en estado "guardando"
  var btnGuardar = document.querySelector('#adminEditarMovDesdeEditarZone button[onclick="adminGuardarEdicion2Mov()"]');
  if(btnGuardar){
    btnGuardar.disabled = true;
    btnGuardar.textContent = '⏳ Guardando…';
  }
  // 3. Sincronizar con Supabase y con archivo de control
  var promesas = [];
  promesas.push(syncEstadoSupabaseDebounced().catch(function(e){ console.warn('guardado Supabase:', e); }));
  if(typeof actualizarArchivoControl==='function')
    promesas.push(actualizarArchivoControl().catch(function(e){ console.warn('guardado archivo control:', e); }));
  Promise.all(promesas).then(function(){
    if(typeof toast==='function') toast('✅ Movimiento guardado y sincronizado en todos los registros','ok');
    if(btnGuardar){ btnGuardar.disabled=false; btnGuardar.textContent='💾 Guardar Cambios'; }
    if(typeof window._marcarGuardadoOk==='function') window._marcarGuardadoOk();
    adminVolverEditarCobros();
  }).catch(function(){
    // Incluso si Drive falla, el cambio ya está en localStorage — encolar para reintentar
    if(typeof window._encolarGuardadoPendiente==='function'){
      window._encolarGuardadoPendiente('syncEstado', null);
    }
    if(typeof toast==='function') toast('⚠️ Guardado local OK · se sincronizará cuando haya conexión','warn');
    if(btnGuardar){ btnGuardar.disabled=false; btnGuardar.textContent='💾 Guardar Cambios'; }
    adminVolverEditarCobros();
  });
}
